  `additional_spells_remove_on_casting` bit(1) NOT NULL DEFAULT b'0',
  `attack_type_id` tinyint unsigned NOT NULL,
  `temporary_hp` bit(1) NOT NULL,
  `save_type_id` int unsigned DEFAULT NULL,
  `half_on_save` bit(1) NOT NULL,
  `recharge_on_long_rest` bit(1) NOT NULL DEFAULT b'0',
  `spell_attack_calculation_type_id` tinyint unsigned NOT NULL DEFAULT '1',
  `spell_attack_modifier` tinyint NOT NULL DEFAULT '0',
  `spell_save_dc` tinyint unsigned NOT NULL DEFAULT '0',
  `magical_item_attunement_type_id` tinyint unsigned NOT NULL DEFAULT '1',
  KEY `magical_items_item_idx` (`item_id`),
  KEY `magical_items_dice_sizes_id_fk` (`recharge_dice_size_id`),
  KEY `magical_items_magical_item_types_id_fk` (`magical_item_type_id`),
  KEY `magical_items_rarities_id_fk` (`rarity_id`),
  KEY `magical_items_abilities_attribute_id_fk` (`save_type_id`),
  KEY `magical_items_attack_types_id_fk` (`attack_type_id`),
  KEY `magical_items_magical_item_spell_attack_calculation_types_id_fk` (`spell_attack_calculation_type_id`),
  KEY `magical_items_magical_item_attunement_types_id_fk` (`magical_item_attunement_type_id`),
  CONSTRAINT `magical_items_abilities_attribute_id_fk` FOREIGN KEY (`save_type_id`) REFERENCES `abilities` (`attribute_id`),
  CONSTRAINT `magical_items_attack_types_id_fk` FOREIGN KEY (`attack_type_id`) REFERENCES `attack_types` (`id`),
  CONSTRAINT `magical_items_dice_sizes_id_fk` FOREIGN KEY (`recharge_dice_size_id`) REFERENCES `dice_sizes` (`id`),
  CONSTRAINT `magical_items_items_id_fk` FOREIGN KEY (`item_id`) REFERENCES `items` (`id`),
