  CONSTRAINT `magical_items_magical_item_spell_attack_calculation_types_id_fk` FOREIGN KEY (`spell_attack_calculation_type_id`) REFERENCES `magical_item_spell_attack_calculation_types` (`id`),
  CONSTRAINT `magical_items_magical_item_types_id_fk` FOREIGN KEY (`magical_item_type_id`) REFERENCES `magical_item_types` (`id`),
  CONSTRAINT `magical_items_rarities_id_fk` FOREIGN KEY (`rarity_id`) REFERENCES `rarities` (`id`)
