--
-- Table structure for table `monster_action_damages`
--

DROP TABLE IF EXISTS `monster_action_damages`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `monster_action_damages` (
  `monster_action_id` int unsigned NOT NULL,
  `num_dice` tinyint unsigned NOT NULL,
  `dice_size` tinyint unsigned NOT NULL,
  `ability_modifier_id` int unsigned DEFAULT NULL,
  `misc_mod` smallint unsigned NOT NULL,
  `damage_type_id` int unsigned DEFAULT NULL,
  `healing` bit(1) NOT NULL,
  `adjustment` bit(1) NOT NULL DEFAULT b'1',
  KEY `monster_action_damages_abilities_attribute_id_fk` (`ability_modifier_id`),
  KEY `monster_action_damages_damage_types_attribute_id_fk` (`damage_type_id`),
  KEY `monster_action_damages_dice_sizes_id_fk` (`dice_size`),
  KEY `monster_action_damages_powers_id_fk` (`monster_action_id`),
  CONSTRAINT `monster_action_damages_abilities_attribute_id_fk` FOREIGN KEY (`ability_modifier_id`) REFERENCES `abilities` (`attribute_id`),
  CONSTRAINT `monster_action_damages_damage_types_attribute_id_fk` FOREIGN KEY (`damage_type_id`) REFERENCES `damage_types` (`attribute_id`),
  CONSTRAINT `monster_action_damages_dice_sizes_id_fk` FOREIGN KEY (`dice_size`) REFERENCES `dice_sizes` (`id`),
  CONSTRAINT `monster_action_damages_powers_id_fk` FOREIGN KEY (`monster_action_id`) REFERENCES `monster_actions` (`monster_power_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

