DROP TABLE IF EXISTS `monster_actions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `monster_actions` (
  `monster_power_id` int unsigned NOT NULL,
  `action_type_id` tinyint unsigned DEFAULT NULL,
  `legendary_cost` tinyint unsigned NOT NULL,
  `weapon_range_type_id` tinyint unsigned DEFAULT NULL,
  `reach` tinyint unsigned NOT NULL,
  `normal_range` smallint unsigned NOT NULL,
  `long_range` smallint unsigned NOT NULL,
  `ammo_id` int unsigned DEFAULT NULL,
  `attack_type_id` tinyint unsigned DEFAULT NULL,
  `temporary_hp` bit(1) NOT NULL,
  `attack_mod` tinyint NOT NULL,
  `attack_ability_modifier_id` int unsigned DEFAULT NULL,
  `save_type_id` int unsigned DEFAULT NULL,
  `save_proficiency_modifier` bit(1) NOT NULL,
  `save_ability_modifier_id` int unsigned DEFAULT NULL,
  `half_on_save` bit(1) NOT NULL,
  `description` varchar(2000) NOT NULL,
  KEY `monster_actions_abilities_attribute_id_fk` (`attack_ability_modifier_id`),
  KEY `monster_actions_abilities_attribute_id_fk_2` (`save_type_id`),
  KEY `monster_actions_abilities_attribute_id_fk_3` (`save_ability_modifier_id`),
  KEY `monster_actions_attack_types_id_fk` (`attack_type_id`),
  KEY `monster_actions_creature_action_types_id_fk` (`action_type_id`),
  KEY `monster_actions_monster_powers_id_fk` (`monster_power_id`),
  KEY `monster_actions_weapon_range_types_id_fk` (`weapon_range_type_id`),
  KEY `monster_actions_items_id_fk` (`ammo_id`),
  CONSTRAINT `monster_actions_abilities_attribute_id_fk` FOREIGN KEY (`attack_ability_modifier_id`) REFERENCES `abilities` (`attribute_id`),
  CONSTRAINT `monster_actions_abilities_attribute_id_fk_2` FOREIGN KEY (`save_type_id`) REFERENCES `abilities` (`attribute_id`),
  CONSTRAINT `monster_actions_abilities_attribute_id_fk_3` FOREIGN KEY (`save_ability_modifier_id`) REFERENCES `abilities` (`attribute_id`),
  CONSTRAINT `monster_actions_attack_types_id_fk` FOREIGN KEY (`attack_type_id`) REFERENCES `attack_types` (`id`),
  CONSTRAINT `monster_actions_creature_action_types_id_fk` FOREIGN KEY (`action_type_id`) REFERENCES `actions` (`id`),
  CONSTRAINT `monster_actions_items_id_fk` FOREIGN KEY (`ammo_id`) REFERENCES `items` (`id`),
  CONSTRAINT `monster_actions_monster_powers_id_fk` FOREIGN KEY (`monster_power_id`) REFERENCES `monster_powers` (`id`),
  CONSTRAINT `monster_actions_weapon_range_types_id_fk` FOREIGN KEY (`weapon_range_type_id`) REFERENCES `weapon_range_types` (`id`)
