CREATE TABLE `monster_features` (
  `monster_power_id` int unsigned NOT NULL,
  `description` varchar(2000) NOT NULL,
  KEY `monster_features_monster_powers_id_fk` (`monster_power_id`),
  CONSTRAINT `monster_features_monster_powers_id_fk` FOREIGN KEY (`monster_power_id`) REFERENCES `monster_powers` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
