--
-- Table structure for table `monsters`
--

DROP TABLE IF EXISTS `monsters`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `monsters` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(150) NOT NULL,
  `monster_type_id` tinyint unsigned NOT NULL,
  `type_variation` varchar(45) NOT NULL,
  `size_id` tinyint unsigned NOT NULL,
  `challenge_rating_id` tinyint unsigned NOT NULL,
  `experience` mediumint unsigned NOT NULL,
  `hit_dice_num_dice` tinyint unsigned NOT NULL,
  `hit_dice_size_id` tinyint unsigned NOT NULL,
  `hit_dice_ability_modifier_id` int unsigned DEFAULT NULL,
  `hit_dice_misc_modifier` tinyint unsigned NOT NULL,
  `legendary_points` tinyint unsigned NOT NULL,
  `description` varchar(2000) NOT NULL,
  `ac` smallint unsigned NOT NULL,
  `hover` bit(1) NOT NULL,
  `spellcaster` bit(1) NOT NULL DEFAULT b'0',
  `caster_type_id` int unsigned DEFAULT NULL,
  `spellcaster_level_id` int unsigned DEFAULT NULL,
  `spell_attack_modifier` tinyint unsigned DEFAULT NULL,
  `spell_save_modifier` tinyint unsigned DEFAULT NULL,
  `spellcasting_ability_id` int unsigned DEFAULT NULL,
  `innate_spellcaster` bit(1) NOT NULL DEFAULT b'0',
  `innate_spellcasting_ability_id` int unsigned DEFAULT NULL,
  `innate_spell_attack_modifier` tinyint unsigned DEFAULT NULL,
  `innate_spell_save_modifier` tinyint unsigned DEFAULT NULL,
  `alignment_id` int unsigned DEFAULT NULL,
  `user_id` mediumint unsigned NOT NULL,
  `sid` smallint unsigned NOT NULL DEFAULT '0',
  `version` smallint unsigned NOT NULL DEFAULT '1',
  `published_parent_id` int unsigned DEFAULT NULL,
  `published_parent_version` smallint unsigned DEFAULT NULL,
  `innate_spellcaster_level_id` int unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `monsters_abilities_attribute_id_fk` (`hit_dice_ability_modifier_id`),
  KEY `monsters_abilities_attribute_id_fk_2` (`spellcasting_ability_id`),
  KEY `monsters_alignments_attribute_id_fk` (`alignment_id`),
  KEY `monsters_caster_types_attribute_id_fk` (`caster_type_id`),
  KEY `monsters_challenge_ratings_id_fk` (`challenge_rating_id`),
  KEY `monsters_character_levels_attribute_id_fk` (`spellcaster_level_id`),
  KEY `monsters_dice_sizes_id_fk` (`hit_dice_size_id`),
  KEY `monsters_monster_types_id_fk` (`monster_type_id`),
  KEY `monsters_monsters_id_fk` (`published_parent_id`),
  KEY `monsters_sizes_id_fk` (`size_id`),
  KEY `monsters_abilities_attribute_id_fk_3` (`innate_spellcasting_ability_id`),
  KEY `monsters_character_levels_attribute_id_fk_2` (`innate_spellcaster_level_id`),
  CONSTRAINT `monsters_abilities_attribute_id_fk` FOREIGN KEY (`hit_dice_ability_modifier_id`) REFERENCES `abilities` (`attribute_id`),
  CONSTRAINT `monsters_abilities_attribute_id_fk_2` FOREIGN KEY (`spellcasting_ability_id`) REFERENCES `abilities` (`attribute_id`),
  CONSTRAINT `monsters_abilities_attribute_id_fk_3` FOREIGN KEY (`innate_spellcasting_ability_id`) REFERENCES `abilities` (`attribute_id`),
  CONSTRAINT `monsters_alignments_attribute_id_fk` FOREIGN KEY (`alignment_id`) REFERENCES `alignments` (`attribute_id`),
  CONSTRAINT `monsters_caster_types_attribute_id_fk` FOREIGN KEY (`caster_type_id`) REFERENCES `caster_types` (`attribute_id`),
  CONSTRAINT `monsters_challenge_ratings_id_fk` FOREIGN KEY (`challenge_rating_id`) REFERENCES `challenge_ratings` (`id`),
  CONSTRAINT `monsters_character_levels_attribute_id_fk` FOREIGN KEY (`spellcaster_level_id`) REFERENCES `character_levels` (`attribute_id`),
  CONSTRAINT `monsters_character_levels_attribute_id_fk_2` FOREIGN KEY (`innate_spellcaster_level_id`) REFERENCES `character_levels` (`attribute_id`),
  CONSTRAINT `monsters_dice_sizes_id_fk` FOREIGN KEY (`hit_dice_size_id`) REFERENCES `dice_sizes` (`id`),
  CONSTRAINT `monsters_monster_types_id_fk` FOREIGN KEY (`monster_type_id`) REFERENCES `monster_types` (`id`),
  CONSTRAINT `monsters_monsters_id_fk` FOREIGN KEY (`published_parent_id`) REFERENCES `monsters` (`id`),
  CONSTRAINT `monsters_sizes_id_fk` FOREIGN KEY (`size_id`) REFERENCES `sizes` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=332 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

