CREATE TABLE `spells` (
  `power_id` int unsigned NOT NULL,
  `level` tinyint unsigned NOT NULL,
  `spell_school_id` int unsigned NOT NULL,
  `ritual` bit(1) NOT NULL,
  `casting_time` tinyint unsigned NOT NULL,
  `casting_time_unit` tinyint unsigned NOT NULL,
  `verbal` bit(1) NOT NULL,
  `somatic` bit(1) NOT NULL,
  `material` bit(1) NOT NULL,
  `components` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `instantaneous` bit(1) NOT NULL,
  `concentration` bit(1) NOT NULL,
  `duration` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `description` varchar(4000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `higher_levels` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  KEY `spell_school_idx` (`spell_school_id`),
  KEY `spell_casting_time_unit_idx` (`casting_time_unit`),
  KEY `spell_power_idx` (`power_id`),
  CONSTRAINT `spells_casting_time_units_id_fk` FOREIGN KEY (`casting_time_unit`) REFERENCES `casting_time_units` (`id`),
  CONSTRAINT `spells_powers_id_fk` FOREIGN KEY (`power_id`) REFERENCES `powers` (`id`),
  CONSTRAINT `spells_spell_schools_attribute_id_fk` FOREIGN KEY (`spell_school_id`) REFERENCES `spell_schools` (`attribute_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
