            DELETE FROM attributes WHERE user_id = userId AND id = abilityId;
        ELSE
            DELETE FROM attributes_shared WHERE user_id = userId AND attribute_id = abilityId;
        END IF;
    END IF;

    COMMIT;

    SELECT 1 AS result;
END ;;
