/*!50003 DROP PROCEDURE IF EXISTS `Attributes_GetList_Modifiers` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Attributes_GetList_Modifiers`(
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    SELECT id, name, description, sid, user_id = userId AS is_author, version, attribute_type_id, 2 AS modifier_category_id, 0 AS characteristic_dependant
    FROM attributes
    WHERE attribute_type_id = 1 AND user_id = userId

    UNION

    SELECT id, name, description, sid, a.user_id = userId AS is_author, version, attribute_type_id, 2 AS modifier_category_id, 0 AS characteristic_dependant
    FROM attributes_shared ua
             JOIN attributes a ON a.id = ua.attribute_id
    WHERE ua.user_id = userId AND attribute_type_id = 1

    UNION

    SELECT id, name, description, sid, user_id = userId AS is_author, version, attribute_type_id, 3 AS modifier_category_id, 0 AS characteristic_dependant
    FROM attributes
    WHERE attribute_type_id = 8 AND user_id = userId

    UNION

    SELECT id, name, description, sid, a.user_id = userId AS is_author, version, attribute_type_id, 3 AS modifier_category_id, 0 AS characteristic_dependant
    FROM attributes_shared ua
             JOIN attributes a ON a.id = ua.attribute_id
    WHERE ua.user_id = userId AND attribute_type_id = 8

    UNION

    SELECT misc_att.id, misc_att.name, misc_att.description, misc_att.sid, misc_att.user_id = userId AS is_author, a.version, misc_att.attribute_type_id, ma.modifier_category_id, ma.characteristic_dependant
    FROM attributes a
             JOIN attributes misc_att ON misc_att.id = a.id
             JOIN misc_attributes ma ON misc_att.id = ma.attribute_id
    WHERE a.user_id = userId

    UNION

    SELECT misc_att.id, misc_att.name, misc_att.description, misc_att.sid, misc_att.user_id = userId AS is_author, version, misc_att.attribute_type_id, ma.modifier_category_id, ma.characteristic_dependant
    FROM attributes_shared ua
             JOIN attributes misc_att ON misc_att.id = ua.attribute_id
             JOIN misc_attributes ma ON misc_att.id = ma.attribute_id
    WHERE ua.user_id = userId

    ORDER BY name;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Attributes_GetList_Shared` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Attributes_GetList_Shared`(
    IN userId MEDIUMINT UNSIGNED,
    IN public BIT,
    IN search VARCHAR(45),
    IN offset INT UNSIGNED,
    IN pageSize INT UNSIGNED,
    IN attributeTypeId TINYINT UNSIGNED,
    IN orderBy VARCHAR(100),
    IN orderByAscending BIT
)
BEGIN
    IF orderBy IS NULL THEN
        SET orderBy = 'name';
    END IF;

    IF orderByAscending IS NULL THEN
        SET orderByAscending = 1;
    END IF;

    CREATE TEMPORARY TABLE IF NOT EXISTS temp_attributes
    (
        attribute_id INT UNSIGNED NOT NULL
    );

    IF public THEN
        INSERT INTO temp_attributes
        SELECT attribute_id
        FROM attributes_public ap
        JOIN attributes a ON ap.attribute_id = a.id
            AND a.archived = 0
            AND a.attribute_type_id = attributeTypeId
            AND (a.version IS NULL OR a.user_id != userId);
    ELSE
        INSERT INTO temp_attributes
        SELECT attribute_id
        FROM attributes_private ap
        JOIN attributes a ON ap.attribute_id = a.id
            AND ap.user_id = userId
            AND a.archived = 0
            AND a.attribute_type_id = attributeTypeId
            AND (a.version IS NULL OR a.user_id != userId);
    END IF;

    SELECT id AS attribute_id, name, description, sid, a.user_id = userId AS is_author
    FROM temp_attributes ta
        JOIN attributes a ON a.id = ta.attribute_id
    WHERE (search IS NULL OR search = '' OR search = '%%' OR name LIKE search)
    ORDER BY
        (CASE WHEN orderBy = 'name' AND orderByAscending = 1 THEN name END),
        (CASE WHEN orderBy = 'name' AND orderByAscending = 0 THEN name END) DESC
    LIMIT offset, pageSize;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Attributes_GetList_Skills` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Attributes_GetList_Skills`(
    IN userId MEDIUMINT UNSIGNED,
    IN search VARCHAR(45),
    IN offset INT UNSIGNED,
    IN pageSize INT UNSIGNED,
    IN orderBy VARCHAR(100),
    IN orderByAscending BIT,
    IN listSource TINYINT UNSIGNED
)
BEGIN
    IF orderBy IS NULL THEN
        SET orderBy = 'name';
    END IF;

    IF orderByAscending IS NULL THEN
        SET orderByAscending = 1;
    END IF;

    CREATE TEMPORARY TABLE IF NOT EXISTS temp_list
    (
        id INT UNSIGNED NOT NULL
    );

    IF listSource = 1 THEN
        INSERT INTO temp_list
        SELECT id FROM attributes WHERE user_id = userId
        UNION
        SELECT attribute_id FROM attributes_shared WHERE user_id = userId;
    ELSEIF listSource = 2 THEN
        INSERT INTO temp_list SELECT attribute_id FROM attributes_public;
    ELSEIF listSource = 3 THEN
        INSERT INTO temp_list SELECT attribute_id FROM attributes_private WHERE user_id = userId;
    END IF;

    SELECT a.id AS attribute_id, a.name, a.description, a.sid, a.user_id = userId AS is_author
    FROM temp_list ua
             JOIN attributes a ON a.id = ua.id
             JOIN skills s ON s.attribute_id = a.id
             LEFT JOIN attributes ability ON ability.id = s.ability_id
    WHERE (search IS NULL OR search = '' OR search = '%%' OR a.name LIKE search)
    ORDER BY
        (CASE WHEN orderBy = 'name' AND orderByAscending = 1 THEN a.name END),
        (CASE WHEN orderBy = 'name' AND orderByAscending = 0 THEN a.name END) DESC,
        (CASE WHEN orderBy = 'ability_name' AND orderByAscending = 1 THEN ability.name END),
        (CASE WHEN orderBy = 'ability_name' AND orderByAscending = 0 THEN ability.name END) DESC
    LIMIT offset, pageSize;

    DROP TEMPORARY TABLE IF EXISTS temp_list;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Attributes_GetList_Skills_Detailed` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Attributes_GetList_Skills_Detailed`(
    IN userId MEDIUMINT UNSIGNED,
    IN search VARCHAR(45),
    IN offset INT UNSIGNED,
    IN pageSize INT UNSIGNED
)
BEGIN
    SELECT a.id, a.name, a.description, a.sid, s.ability_id, a2.name AS ability_name,
           a2.description AS ability_description, ab.abbr AS ability_abbr, a2.sid AS ability_sid,
           a2.user_id = userId AS ability_is_author, a2.version AS ability_version,
           a.user_id = userId AS is_author, a.version
    FROM (SELECT id AS attribute_id FROM attributes WHERE user_id = userId
          UNION
          SELECT attribute_id FROM attributes_shared WHERE user_id = userId) AS ua
             JOIN attributes a ON a.id = ua.attribute_id
             JOIN skills s on a.id = s.attribute_id
             JOIN abilities ab on s.ability_id = ab.attribute_id
             JOIN attributes a2 ON a2.id = ab.attribute_id
    WHERE (search IS NULL OR search = '' OR search = '%%' OR a.name LIKE search)
    ORDER BY name
    LIMIT offset, pageSize;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
