CREATE DEFINER=`squire`@`%` PROCEDURE `Attributes_Publish`(
    IN oldAttributeId INT UNSIGNED,
    IN newAttributeId INT UNSIGNED,
    IN attributeTypeId TINYINT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
#     DECLARE privateUserId MEDIUMINT UNSIGNED;
#     DECLARE more_rows BOOLEAN DEFAULT TRUE;
#     DECLARE curs CURSOR FOR SELECT DISTINCT user_id
#                             FROM attributes_private
#                             WHERE attribute_id = oldAttributeId;
#     DECLARE CONTINUE HANDLER FOR NOT FOUND SET more_rows = FALSE;
    DECLARE attributeVersion TINYINT UNSIGNED;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        SELECT 0 AS success;
    END;

    START TRANSACTION;
        SET attributeVersion = (SELECT COALESCE(MAX(version), 0) FROM attributes WHERE published_parent_id = oldAttributeId) + 1;
        UPDATE attributes SET published_parent_id = newAttributeId, archived = 1 WHERE published_parent_id = oldAttributeId AND user_id = userId;
        UPDATE attributes SET published_parent_id = newAttributeId, published = 1, version = attributeVersion WHERE id = oldAttributeId AND user_id = userId;
        CALL Attributes_UseNewVersion(oldAttributeId, newAttributeId, attributeTypeId, userId);

        # loop though privately shared and update to new version
#         OPEN curs;
#         WHILE more_rows DO
#             FETCH curs INTO privateUserId;
#             CALL Attributes_UseNewVersion(oldAttributeId, newAttributeId, attributeTypeId, privateUserId);
#         END WHILE;
#         CLOSE curs;

    COMMIT;

    SELECT 1 AS success;
END ;;
DELIMITER ;
