    IN campaignId INT UNSIGNED
)
BEGIN
    SELECT
        campaign_setting_category_id,
        campaign_setting_id,
        value
    FROM campaign_setting_values csv
    JOIN campaign_settings cs on csv.campaign_setting_id = cs.id
    WHERE campaign_id = campaignId;

