DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Characteristics_DamageModifiers`(
    IN characteristicId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    SELECT damage_type_id,
           damageType.name AS damage_type_name,
           damageType.description AS damage_type_description,
           damageType.sid AS damage_type_sid,
           damageType.user_id = userId AS damage_type_is_author,
           damageType.version AS damage_type_version,
           damage_modifier_type_id
    FROM characteristic_damage_modifiers dm
        JOIN attributes damageType ON damageType.id = dm.damage_type_id
    WHERE characteristic_id = characteristicId;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Characteristics_Delete` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Characteristics_Delete`(
    IN characteristicId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    DECLARE currentCharacteristicId INT UNSIGNED;
    DECLARE characteristicTypeId TINYINT UNSIGNED;
    DECLARE more_rows BOOLEAN DEFAULT TRUE;
    DECLARE curs CURSOR FOR SELECT id FROM temp_characteristics;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET more_rows = FALSE;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        SELECT -1 AS result;
    END;

    START TRANSACTION;

    SET characteristicTypeId = (SELECT characteristic_type_id FROM characteristics WHERE id = characteristicId);

    CREATE TEMPORARY TABLE IF NOT EXISTS temp_characteristics
    (
        id INT UNSIGNED NOT NULL
    );

    INSERT INTO temp_characteristics (id) VALUES (characteristicId);

    INSERT INTO temp_characteristics (id)
    WITH RECURSIVE children (id) AS
    (
        SELECT id
        FROM characteristics
        WHERE parent_characteristic_id = characteristicId

        UNION ALL

        SELECT c2.id
        FROM children c
            JOIN characteristics AS c2 ON c.id = c2.parent_characteristic_id
    )
    SELECT id FROM children;

    OPEN curs;

    WHILE more_rows DO
        FETCH curs INTO currentCharacteristicId;

        IF more_rows THEN
            IF characteristicTypeId = 1 THEN
                CALL Characteristics_Delete_Class(currentCharacteristicId, userId);
            ELSEIF characteristicTypeId = 2 THEN
                CALL Characteristics_Delete_Race(currentCharacteristicId, userId);
            ELSEIF characteristicTypeId = 3 THEN
                CALL Characteristics_Delete_Background(currentCharacteristicId, userId);
            END IF;
        END IF;
    END WHILE;

    CLOSE curs;

    DROP TEMPORARY TABLE IF EXISTS temp_characteristics;

    COMMIT;

    SELECT 1 AS result;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Characteristics_Delete_Background` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Characteristics_Delete_Background`(
    IN characteristicId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    DECLARE backgroundId INT UNSIGNED;
    DECLARE isOwner BIT;

    SELECT id, user_id = userId
    INTO backgroundId, isOwner
    FROM characteristics
    WHERE user_id IN (0, userId) AND id = characteristicId;

    IF backgroundId IS NOT NULL THEN
        DELETE cbt FROM character_background_traits cbt JOIN background_traits bt ON bt.id = cbt.background_trait_id JOIN creatures c ON c.id = cbt.character_id WHERE background_id = backgroundId AND c.user_id = userId;
        UPDATE characters ch JOIN creatures c ON c.id = ch.creature_id SET background_id = NULL WHERE background_id = backgroundId AND c.user_id = userId;
        CALL Characteristics_Delete_Common(backgroundId, userId);

        IF isOwner THEN
            DELETE FROM characteristics_public WHERE characteristic_id = characteristicId;
            DELETE FROM characteristics_private WHERE characteristic_id = characteristicId;
            UPDATE characteristics SET published_parent_id = NULL, published_parent_version = NULL WHERE published_parent_id = characteristicId;

            DELETE bt FROM background_traits bt JOIN characteristics c ON c.id = bt.background_id WHERE background_id = backgroundId AND c.user_id = userId;
            DELETE b FROM backgrounds b JOIN characteristics c ON c.id = b.characteristic_id WHERE characteristic_id = backgroundId AND c.user_id = userId;
            DELETE FROM characteristics WHERE user_id = userId AND id = backgroundId;
        ELSE
            DELETE FROM characteristics_shared WHERE user_id = userId AND characteristic_id = backgroundId;
        END IF;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Characteristics_Delete_Class` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Characteristics_Delete_Class`(
    IN characteristicId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    DECLARE classId INT UNSIGNED;
    DECLARE isOwner BIT;

    SELECT id, user_id = userId
    INTO classId, isOwner
    FROM characteristics
    WHERE user_id IN (0, userId) AND id = characteristicId;

    IF classId IS NOT NULL THEN
        UPDATE character_chosen_classes ccc JOIN creatures c ON c.id = ccc.character_id SET class_id = NULL WHERE class_id = classId AND c.user_id = userId; # this should throw an exception if a match is found

        # not doing this so that the delete will throw an exception if the subclass is currently in use
#     UPDATE character_chosen_classes ccc JOIN creatures c ON c.id = ccc.character_id SET subclass_id = NULL WHERE subclass_id = classId AND c.user_id = userId;
        DELETE asi FROM class_ability_score_increases asi JOIN characteristics c ON c.id = asi.class_id WHERE class_id = classId AND c.user_id = userId;
        DELETE p FROM class_secondary_attribute_profs p JOIN characteristics c ON c.id = p.class_id WHERE class_id = classId AND c.user_id = userId;
        DELETE p FROM class_secondary_choice_profs p JOIN characteristics c ON c.id = p.class_id WHERE class_id = classId AND c.user_id = userId;
        DELETE p FROM class_secondary_item_profs p JOIN characteristics c ON c.id = p.class_id WHERE class_id = classId AND c.user_id = userId;
        DELETE miac FROM magical_item_attunement_classes miac JOIN items i ON i.id = miac.magical_item_id WHERE class_id = classId AND i.user_id = userId;

        CALL Characteristics_Delete_Common(classId, userId);

        IF isOwner THEN
            DELETE FROM characteristics_public WHERE characteristic_id = characteristicId;
            DELETE FROM characteristics_private WHERE characteristic_id = characteristicId;
            UPDATE characteristics SET published_parent_id = NULL, published_parent_version = NULL WHERE published_parent_id = characteristicId;

            DELETE cl FROM classes cl JOIN characteristics c ON c.id = cl.characteristic_id WHERE characteristic_id = classId AND c.user_id = userId;
            DELETE FROM characteristics WHERE user_id = userId AND id = classId;
        ELSE
            DELETE FROM characteristics_shared WHERE user_id = userId AND characteristic_id = classId;
        END IF;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Characteristics_Delete_Common` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Characteristics_Delete_Common`(
    IN characteristicId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    DELETE ccs FROM character_characteristic_spellcasting ccs JOIN creatures c ON c.id = ccs.character_id WHERE characteristic_id = characteristicId AND c.user_id = userId;
    DELETE cv FROM character_validation cv JOIN creatures c ON c.id = cv.character_id WHERE characteristic_id = characteristicId AND c.user_id = userId;

    CALL Characteristics_Delete_Features(characteristicId, userId);

    DELETE cam FROM characteristic_attribute_modifiers cam JOIN characteristics c ON c.id = cam.characteristic_id WHERE characteristic_id = characteristicId AND c.user_id = userId;
    DELETE cap FROM characteristic_attribute_profs cap JOIN characteristics c ON c.id = cap.characteristic_id WHERE characteristic_id = characteristicId AND c.user_id = userId;
    DELETE ccp FROM characteristic_choice_profs ccp JOIN characteristics c ON c.id = ccp.characteristic_id WHERE characteristic_id = characteristicId AND c.user_id = userId;
    DELETE cci FROM characteristic_condition_immunities cci JOIN characteristics c ON c.id = cci.characteristic_id WHERE characteristic_id = characteristicId AND c.user_id = userId;
    DELETE cdm FROM characteristic_damage_modifiers cdm JOIN characteristics c ON c.id = cdm.characteristic_id WHERE characteristic_id = characteristicId AND c.user_id = userId;
    DELETE cip FROM characteristic_item_profs cip JOIN characteristics c ON c.id = cip.characteristic_id WHERE characteristic_id = characteristicId AND c.user_id = userId;
    DELETE cs FROM characteristic_senses cs JOIN characteristics c ON c.id = cs.characteristic_id WHERE characteristic_id = characteristicId AND c.user_id = userId;
    DELETE csc FROM characteristic_spell_configurations csc JOIN characteristics c ON c.id = csc.characteristic_id WHERE characteristic_id = characteristicId AND (c.user_id = userId OR csc.user_id = userId);
    DELETE cse FROM characteristic_starting_equipments cse JOIN characteristics c ON c.id = cse.characteristic_id WHERE characteristic_id = characteristicId AND c.user_id = userId;
    DELETE cs FROM creatures c JOIN creature_powers cp ON cp.creature_id = c.id JOIN creature_spells cs ON cs.creature_power_id = cp.id WHERE cp.assigned_characteristic_id = characteristicId AND c.user_id = userId;
    DELETE cp FROM creature_powers cp JOIN creatures c ON c.id = cp.creature_id WHERE assigned_characteristic_id = characteristicId AND c.user_id = userId;
    UPDATE characteristics SET parent_characteristic_id = NULL WHERE parent_characteristic_id = characteristicId AND user_id = userId;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Characteristics_Delete_Features` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Characteristics_Delete_Features`(
    IN characteristicId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    DELETE cvip FROM character_validation_ignored_powers cvip JOIN creatures c ON c.id = cvip.character_id JOIN features f ON f.power_id = cvip.power_id WHERE f.characteristic_id = characteristicId AND c.user_id = userId;
    DELETE cpt FROM creature_power_tags cpt JOIN creatures c ON c.id = cpt.creature_id JOIN features f ON f.power_id = cpt.power_id WHERE f.characteristic_id = characteristicId AND c.user_id = userId;
    DELETE cp FROM creature_powers cp JOIN creatures c ON c.id = cp.creature_id JOIN features f ON f.power_id = cp.power_id WHERE f.characteristic_id = characteristicId AND c.user_id = userId;
    DELETE pd FROM power_damages pd JOIN powers p ON p.id = pd.power_id JOIN features f ON f.power_id = p.id WHERE f.characteristic_id = characteristicId AND p.user_id = userId;
    DELETE pl FROM power_limited_uses pl JOIN powers p ON p.id = pl.power_id JOIN features f ON f.power_id = p.id WHERE f.characteristic_id = characteristicId AND p.user_id = userId;
    DELETE pm FROM power_modifiers pm JOIN powers p ON p.id = pm.power_id JOIN features f ON f.power_id = p.id WHERE f.characteristic_id = characteristicId AND p.user_id = userId;

    CREATE TEMPORARY TABLE IF NOT EXISTS temp_creature_actions
    (
        id INT UNSIGNED NOT NULL
    );

    INSERT INTO temp_creature_actions
    SELECT ca.id
    FROM creature_action_powers cap
        JOIN features f ON f.power_id = cap.power_id
        JOIN creature_actions ca ON ca.id = cap.creature_action_id
        JOIN creatures c ON c.id = ca.creature_id
    WHERE f.characteristic_id = characteristicId AND c.user_id = userId;

    DELETE cai FROM chained_action_items cai JOIN temp_creature_actions tca ON tca.id = cai.creature_action_id;
    DELETE cap FROM creature_action_powers cap JOIN temp_creature_actions tca ON tca.id = cap.creature_action_id;
    DELETE ca FROM creature_actions ca JOIN temp_creature_actions tca ON tca.id = ca.id;

    DROP TEMPORARY TABLE IF EXISTS temp_creature_actions;

    CREATE TEMPORARY TABLE IF NOT EXISTS temp_feature_ids
    (
        id INT UNSIGNED NOT NULL
    );

    INSERT INTO temp_feature_ids
    SELECT id
    FROM powers p
        JOIN features f ON f.power_id = p.id
    WHERE f.characteristic_id = characteristicId AND user_id = userId;

    UPDATE powers p SET published_parent_id = NULL, published_parent_version = NULL WHERE published_parent_id IN (SELECT id FROM temp_feature_ids);

    DELETE pp FROM powers_public pp JOIN temp_feature_ids p ON p.id = pp.power_id;
    DELETE pp FROM powers_public pp JOIN features f ON f.power_id = pp.power_id AND f.characteristic_id = characteristicId JOIN powers p ON p.id = pp.power_id AND p.user_id = userId;
    DELETE pp FROM powers_private pp JOIN temp_feature_ids p ON p.id = pp.power_id;
    DELETE pp FROM powers_private pp JOIN features f ON f.power_id = pp.power_id AND f.characteristic_id = characteristicId JOIN powers p ON p.id = pp.power_id AND p.user_id = userId;

    DELETE f FROM features f JOIN temp_feature_ids t ON t.id = f.power_id;
    DELETE p FROM powers p JOIN temp_feature_ids t ON t.id = p.id;
    DELETE ps FROM powers_shared ps JOIN temp_feature_ids t ON t.id = ps.power_id WHERE ps.user_id = userId;

    DROP TEMPORARY TABLE IF EXISTS temp_feature_ids;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Characteristics_Delete_Race` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Characteristics_Delete_Race`(
    IN characteristicId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    DECLARE raceId INT UNSIGNED;
    DECLARE isOwner BIT;

    SELECT id, user_id = userId
    INTO raceId, isOwner
    FROM characteristics
    WHERE user_id IN (0, userId) AND id = characteristicId;

    IF raceId IS NOT NULL THEN
        UPDATE characters ch JOIN creatures c ON c.id = ch.creature_id SET race_id = NULL WHERE race_id = raceId AND c.user_id = userId; # this should throw an exception if a match is found
        DELETE miar FROM magical_item_attunement_races miar JOIN items i ON i.id = miar.magical_item_id WHERE race_id = raceId AND i.user_id = userId;

        CALL Characteristics_Delete_Common(raceId, userId);

        IF isOwner THEN
            DELETE FROM characteristics_public WHERE characteristic_id = characteristicId;
            DELETE FROM characteristics_private WHERE characteristic_id = characteristicId;
            UPDATE characteristics SET published_parent_id = NULL, published_parent_version = NULL WHERE published_parent_id = characteristicId;

            DELETE rs FROM race_speeds rs JOIN characteristics c ON c.id = rs.race_id WHERE race_id = raceId AND c.user_id = userId;
            DELETE r FROM races r JOIN characteristics c ON c.id = r.characteristic_id WHERE characteristic_id = raceId AND c.user_id = userId;
            DELETE FROM characteristics WHERE user_id = userId AND id = raceId;
        ELSE
            DELETE FROM characteristics_shared WHERE user_id = userId AND characteristic_id = raceId;
        END IF;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Characteristics_Get` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Characteristics_Get`(
    IN characteristicId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    DECLARE characteristicTypeId TINYINT UNSIGNED;
    SET characteristicTypeId = (SELECT characteristic_type_id FROM characteristics WHERE id = characteristicId);
    SELECT characteristicTypeId AS characteristic_type_id;

    IF characteristicTypeId = 1 THEN
        CALL Characteristics_Get_Class(characteristicId, userId);
    ELSEIF characteristicTypeId = 2 THEN
        CALL Characteristics_Get_Race(characteristicId, userId);
    ELSEIF characteristicTypeId = 3 THEN
        CALL Characteristics_Get_Background(characteristicId, userId);
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Characteristics_GetAddToMyStuffDetails` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Characteristics_GetAddToMyStuffDetails`(
    IN characteristicId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED,
    IN checkRights BIT
)
BEGIN
    DECLARE authorCharacteristicId INT UNSIGNED;
    DECLARE existingCharacteristicId INT UNSIGNED;
    DECLARE authorUserId MEDIUMINT UNSIGNED;
    DECLARE authorCharacteristicTypeId TINYINT UNSIGNED;
    DECLARE existingCharacteristicTypeId TINYINT UNSIGNED;

    IF checkRights = 0 THEN
        SET authorCharacteristicId = characteristicId;
    ELSE
        SET authorCharacteristicId = (SELECT published_parent_id FROM characteristics WHERE user_id = userId AND id = characteristicId);
        IF authorCharacteristicId IS NULL THEN
            SET authorCharacteristicId = (SELECT characteristic_id FROM characteristics_public WHERE characteristic_id = characteristicId);
        END IF;
        IF authorCharacteristicId IS NULL THEN
            SET authorCharacteristicId = (SELECT characteristic_id FROM characteristics_private WHERE user_id = userId AND characteristic_id = characteristicId);
        END IF;
    END IF;

    SELECT user_id, characteristic_type_id
    INTO authorUserId, authorCharacteristicTypeId
    FROM characteristics WHERE id = authorCharacteristicId;

    SELECT id, characteristic_type_id
    INTO existingCharacteristicId, existingCharacteristicTypeId
    FROM characteristics WHERE published_parent_id = authorCharacteristicId AND user_id = userId;

    SELECT authorCharacteristicId AS author_characteristic_id,
           authorUserId AS author_user_id,
           existingCharacteristicId AS existing_characteristic_id,
           authorCharacteristicTypeId AS author_characteristic_type_id,
           existingCharacteristicTypeId AS existing_characteristic_type_id;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Characteristics_GetList` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Characteristics_GetList`(
    IN userId MEDIUMINT UNSIGNED,
    IN search VARCHAR(45),
    IN offset INT UNSIGNED,
    IN pageSize INT UNSIGNED,
    IN includeChildren BIT,
    IN authorOnly BIT,
    IN characteristicTypeId TINYINT UNSIGNED,
    IN listSource TINYINT UNSIGNED
)
BEGIN
    CREATE TEMPORARY TABLE IF NOT EXISTS temp_list
    (
        id INT UNSIGNED NOT NULL
    );

    IF listSource = 1 THEN
        INSERT INTO temp_list
        SELECT id FROM characteristics WHERE user_id = userId
        UNION
        SELECT characteristic_id FROM characteristics_shared WHERE user_id = userId;
    ELSEIF listSource = 2 THEN
        INSERT INTO temp_list SELECT characteristic_id FROM characteristics_public;
    ELSEIF listSource = 3 THEN
        INSERT INTO temp_list SELECT characteristic_id FROM characteristics_private WHERE user_id = userId;
    END IF;

    SELECT c.id AS characteristic_id, name, sid, c.user_id = userId AS is_author
    FROM temp_list ua
             JOIN characteristics c ON c.id = ua.id
        AND (authorOnly = 0 OR c.user_id = userId)
        AND c.characteristic_type_id = characteristicTypeId
        AND (includeChildren OR c.parent_characteristic_id IS NULL)
    WHERE (search IS NULL OR search = '' OR search = '%%' OR name LIKE search)
    ORDER BY name
    LIMIT offset, pageSize;

    DROP TEMPORARY TABLE IF EXISTS temp_list;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
