/*!50003 DROP PROCEDURE IF EXISTS `Character_Get_Background` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Character_Get_Background`(
    IN creatureId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    DECLARE characterId INT UNSIGNED;
    DECLARE backgroundId INT UNSIGNED;

    SET characterId = (SELECT id FROM creatures WHERE user_id = userID AND id = creatureId UNION SELECT creature_id FROM creatures_shared WHERE user_id = userId AND creature_id = creatureId);
    SET backgroundId = (SELECT background_id FROM characters WHERE creature_id = characterId);

    SELECT background_id, background_spellcasting_ability_id,
           custom_background_name, custom_background_variation, custom_background_personality,
           custom_background_ideal, custom_background_bond, custom_background_flaw, bio
    FROM characters
    WHERE creature_id = characterId;

    CALL Characteristics_Get_Background(backgroundId, userId);

    # Characteristic Spellcasting
    SELECT prof, double_prof, half_prof, round_up, misc_modifier, advantage, disadvantage, attack_type_id
    FROM character_characteristic_spellcasting
    WHERE character_id = characterId AND characteristic_id = backgroundId AND attack_type_id IN (1,2)
    ORDER BY attack_type_id;

    # Chosen Traits
    SELECT t.id, t.background_trait_type_id, t.description
    FROM character_background_traits c
             JOIN background_traits t ON c.background_trait_id = t.id
    WHERE c.character_id = characterId;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Character_Get_ChosenClass` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Character_Get_ChosenClass`(
    IN chosenClassId INT UNSIGNED,
    IN creatureId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    DECLARE characterId INT UNSIGNED;
    DECLARE classId INT UNSIGNED;
    DECLARE subclassId INT UNSIGNED;

    SET characterId = (SELECT id FROM creatures WHERE user_id = userID AND id = creatureId UNION SELECT creature_id FROM creatures_shared WHERE user_id = userId AND creature_id = creatureId);

    SELECT class_id, subclass_id
    INTO classId, subclassId
    FROM character_chosen_classes
    WHERE id = chosenClassId AND character_id = characterId;

    SELECT ccc.id, `primary`, num_hit_dice_mod, spellcasting_ability_id, display_spellcasting,
           level_id, levels.name AS level_name, levels.description AS level_description, levels.sid AS level_sid,
           levels.user_id = userId AS level_is_author, levels.version AS level_version, levels2.min_exp, levels2.prof_bonus
    FROM character_chosen_classes ccc
             JOIN attributes levels ON levels.id = ccc.level_id
             JOIN character_levels levels2 ON levels2.attribute_id = levels.id
    WHERE ccc.id = chosenClassId;

    CALL Characteristics_Get_Class(classId, userId);
    CALL Characteristics_Get_Class(subclassId, userId);

    # Characteristic Spellcasting
    SELECT prof, double_prof, half_prof, round_up, misc_modifier, advantage, disadvantage, attack_type_id
    FROM character_characteristic_spellcasting
    WHERE character_id = characterId AND characteristic_id = classId AND attack_type_id IN (1,2)
    ORDER BY attack_type_id;

    # Health Gain Results
    SELECT chgr.level_id, a.name, a.sid, chgr.value, a.user_id = userId AS is_author
    FROM character_health_gain_results chgr
             JOIN attributes a ON chgr.level_id = a.id
    WHERE chgr.chosen_class_id = chosenClassId;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Character_Get_Classes` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Character_Get_Classes`(
    IN creatureId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    DECLARE characterId INT UNSIGNED;
    DECLARE chosenClassId INT UNSIGNED;
    DECLARE more_rows BOOLEAN DEFAULT TRUE;
    DECLARE curs CURSOR FOR SELECT id FROM character_chosen_classes WHERE character_id = characterId;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET more_rows = FALSE;
    SET characterId = (SELECT id FROM creatures WHERE user_id = userID AND id = creatureId UNION SELECT creature_id FROM creatures_shared WHERE user_id = userId AND creature_id = creatureId);

    SELECT id FROM character_chosen_classes WHERE character_id = characterId;

    OPEN curs;

    WHILE more_rows DO
            FETCH curs INTO chosenClassId;

            IF more_rows THEN
                CALL Character_Get_ChosenClass(chosenClassId, characterId, userId);
            END IF;
        END WHILE;

    CLOSE curs;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Character_Get_Race` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Character_Get_Race`(
    IN creatureId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    DECLARE characterId INT UNSIGNED;
    DECLARE raceId INT UNSIGNED;

    SET characterId = (SELECT id FROM creatures WHERE user_id = userID AND id = creatureId UNION SELECT creature_id FROM creatures_shared WHERE user_id = userId AND creature_id = creatureId);
    SET raceId = (SELECT race_id FROM characters WHERE creature_id = characterId);

    SELECT race_spellcasting_ability_id
    FROM characters
    WHERE creature_id = characterId;

    CALL Characteristics_Get_Race(raceId, userId);

    # Characteristic Spellcasting
    SELECT prof, double_prof, half_prof, round_up, misc_modifier, advantage, disadvantage, attack_type_id
    FROM character_characteristic_spellcasting
    WHERE character_id = characterId AND characteristic_id = raceId AND attack_type_id IN (1,2)
    ORDER BY attack_type_id;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Character_Notes_Add` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Character_Notes_Add`(
    IN characterId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED,
    IN noteCategoryName VARCHAR(45),
    IN noteValue VARCHAR(1000)
)
BEGIN
    DECLARE characterNoteCategoryId INT UNSIGNED;
    DECLARE noteId INT UNSIGNED;
    DECLARE noteOrder INT UNSIGNED;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        SELECT -1 AS character_note_id;
    END;

    START TRANSACTION;

    IF noteCategoryName = '' THEN
        SET noteCategoryName = NULL;
    END IF;

    SET characterNoteCategoryId = (SELECT id FROM character_note_categories WHERE character_id = characterId AND name = noteCategoryName);

    IF noteCategoryName IS NOT NULL AND characterNoteCategoryId IS NULL THEN
        INSERT INTO `character_note_categories` (`character_id`, `name`, `expanded`)
        VALUES (characterId, noteCategoryName, 1);
        SET characterNoteCategoryId = (SELECT LAST_INSERT_ID());
    END IF;

    SET noteOrder = (SELECT COUNT(*) + 1 FROM character_notes WHERE character_note_category_id = characterNoteCategoryId OR (character_note_category_id IS NULL AND characterNoteCategoryId IS NULL));

    INSERT INTO `character_notes` (`character_id`, `character_note_category_id`, `note`, `order`)
    VALUES (characterId, characterNoteCategoryId, noteValue, noteOrder);

    COMMIT;

    SET noteId = (SELECT LAST_INSERT_ID());

    CALL Character_Notes_Get(noteId, characterId, userId);
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Character_Notes_Delete` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Character_Notes_Delete`(
    IN noteId INT UNSIGNED,
    IN characterId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    DECLARE originalNoteCategoryId INT UNSIGNED;
    DECLARE characterNoteId INT UNSIGNED;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        SELECT 0 AS success;
    END;

    START TRANSACTION;

    SET characterNoteId = (SELECT note.id FROM character_notes note JOIN creatures c ON c.id = note.character_id WHERE note.id = noteId AND note.character_id = characterId AND c.user_id = userId);
    SET originalNoteCategoryId = (SELECT character_note_category_id FROM character_notes WHERE id = characterNoteId);

    IF characterNoteId IS NOT NULL THEN
        DELETE FROM character_notes WHERE id = characterNoteId;

        IF (originalNoteCategoryId IS NOT NULL AND (SELECT COUNT(*) FROM character_notes WHERE character_note_category_id = originalNoteCategoryId) = 0) THEN
            DELETE FROM character_note_categories WHERE character_id = characterId AND id = originalNoteCategoryId;
        END IF;

        SELECT 1 AS success;
    ELSE
        SELECT 0 AS success;
    END IF;

    COMMIT;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Character_Notes_Get` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Character_Notes_Get`(
    IN noteId INT UNSIGNED,
    IN creatureId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    DECLARE characterId INT UNSIGNED;
    SET characterId = (SELECT id FROM creatures WHERE user_id = userID AND id = creatureId UNION SELECT creature_id FROM creatures_shared WHERE user_id = userId AND creature_id = creatureId);
    IF characterId IS NULL THEN
        SET characterId = (SELECT creature_id FROM creatures_private WHERE user_id = userId AND creature_id = creatureId);
    END IF;

    SELECT note.id, c.id AS category_id, c.name AS category_name, c.expanded, note.note, note.date
    FROM character_notes note
        LEFT JOIN character_note_categories c ON note.character_note_category_id = c.id
    WHERE note.character_id = characterId
        AND note.id = noteId;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Character_Notes_GetList` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Character_Notes_GetList`(
    IN creatureId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED,
    IN categoryValue VARCHAR(100)
)
BEGIN
    DECLARE characterId INT UNSIGNED;
    SET characterId = (SELECT id FROM creatures WHERE user_id = userID AND id = creatureId UNION SELECT creature_id FROM creatures_shared WHERE user_id = userId AND creature_id = creatureId);
    IF characterId IS NULL THEN
        SET characterId = (SELECT creature_id FROM creatures_private WHERE user_id = userId AND creature_id = creatureId);
    END IF;

    SELECT n.id, c.id AS category_id, c.name AS category_name, c.expanded, n.note, n.date
    FROM character_notes n
        LEFT JOIN character_note_categories c ON n.character_note_category_id = c.id
    WHERE n.character_id = characterId
        AND (categoryValue IS NULL OR c.name = categoryValue)
    ORDER BY `order`, date;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Character_Notes_Update` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Character_Notes_Update`(
    IN noteId INT UNSIGNED,
    IN characterId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED,
    IN noteCategoryName VARCHAR(45),
    IN noteValue VARCHAR(1000)
)
BEGIN
    DECLARE originalNoteCategoryId INT UNSIGNED;
    DECLARE characterNoteCategoryId INT UNSIGNED;
    DECLARE characterNoteId INT UNSIGNED;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
    END;

    START TRANSACTION;

    IF noteCategoryName = '' THEN
        SET noteCategoryName = NULL;
    END IF;

    SET characterNoteId = (SELECT note.id FROM character_notes note JOIN creatures c ON c.id = note.character_id WHERE note.id = noteId AND note.character_id = characterId AND c.user_id = userId);
    SET originalNoteCategoryId = (SELECT character_note_category_id FROM character_notes WHERE id = characterNoteId);
    SET characterNoteCategoryId = (SELECT id FROM character_note_categories WHERE character_id = characterId AND name = noteCategoryName);

    IF characterNoteId IS NOT NULL THEN
        IF (originalNoteCategoryId = characterNoteCategoryId) OR (originalNoteCategoryId IS NULL AND noteCategoryName IS NULL) THEN
            UPDATE character_notes SET note = noteValue WHERE id = characterNoteId;
        ELSE
            IF noteCategoryName IS NOT NULL AND characterNoteCategoryId IS NULL THEN
                INSERT INTO `character_note_categories` (`character_id`, `name`)
                VALUES (characterId, noteCategoryName);
                SET characterNoteCategoryId = (SELECT LAST_INSERT_ID());
            END IF;

            UPDATE character_notes SET note = noteValue, character_note_category_id = characterNoteCategoryId WHERE id = characterNoteId;

            IF (originalNoteCategoryId IS NOT NULL AND (SELECT COUNT(*) FROM character_notes WHERE character_note_category_id = originalNoteCategoryId) = 0) THEN
                DELETE FROM character_note_categories WHERE character_id = characterId AND id = originalNoteCategoryId;
            END IF;
        END IF;
    END IF;

    COMMIT;

    CALL Character_Notes_Get(noteId, characterId, userId);
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Character_Settings_Get` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
