        FROM creature_actions ca
        JOIN creature_action_powers cap ON cap.creature_action_id = ca.id AND ca.creature_id = creatureId
        JOIN powers p ON cap.power_id = p.id
        JOIN features f ON f.power_id = p.id
        WHERE f.action_id = actionId

        UNION

        SELECT ca.id AS creature_action_id, ca.creature_action_type_id, i.id AS action_item_id, i.name AS action_item_name,
               i2.id AS action_sub_item_id, i2.name AS action_sub_item_name,
               ca.favorite, ca.favorite_order, null AS default_id, actionId AS action_id
        FROM creature_actions ca
        JOIN creature_action_items cai ON cai.creature_action_id = ca.id AND ca.creature_id = creatureId
        JOIN items i ON cai.item_id = i.id
        LEFT JOIN magical_items mi ON mi.item_id = i.id
        LEFT JOIN items i2 ON cai.sub_item_id = i2.id
        WHERE i.slot = handSlotId
            OR mi.magical_item_type_id = 4 -- rod
            OR mi.magical_item_type_id = 5 -- scroll
            OR mi.magical_item_type_id = 6 -- staff
            OR mi.magical_item_type_id = 7 -- wand
    ) AS a
    ORDER BY action_item_name;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `CreatureActions_Items_Add` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `CreatureActions_Items_Add`(
    IN creatureId INT UNSIGNED,
    IN itemId INT UNSIGNED,
    IN subItemId INT UNSIGNED
)
BEGIN
    DECLARE creatureActionId INT UNSIGNED;
    DECLARE newCreatureActionId INT UNSIGNED;
    DECLARE quantity SMALLINT UNSIGNED;

    SET quantity = (SELECT COUNT(*)
        FROM creature_items
        WHERE creature_id = creatureId
          AND item_id = itemId
          AND (subItemId IS NULL OR magic_item_type_id = subItemId));

    SET creatureActionId = (SELECT ca.id
        FROM creature_action_items cai
            JOIN creature_actions ca ON ca.id = cai.creature_action_id
        WHERE creature_id = creatureId
          AND item_id = itemId
          AND ((sub_item_id IS NULL AND subItemId IS NULL) OR (sub_item_id = subItemId)));

    IF quantity > 0 && creatureActionId IS NULL THEN
        INSERT INTO creature_actions (creature_id, creature_action_type_id, favorite, favorite_order) VALUE
        (creatureId, 3, 0, 0);

        SET newCreatureActionId = (SELECT LAST_INSERT_ID());

        INSERT INTO creature_action_items (creature_action_id, item_id, sub_item_id) VALUE
        (newCreatureActionId, itemId, subItemId);
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `CreatureActions_Items_Delete` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
