/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `CreatureItems_Add` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `CreatureItems_Add`(
    IN creatureId INT UNSIGNED,
    IN itemId INT UNSIGNED,
    IN itemQuantity SMALLINT UNSIGNED,
    IN containerItemId INT UNSIGNED,
    IN magicItemTypeId INT UNSIGNED,
    IN spellId INT UNSIGNED,
    IN creatureItemStateId TINYINT UNSIGNED,
    IN itemCursed BIT
)
BEGIN
    DECLARE x SMALLINT UNSIGNED;
    DECLARE creatureItemId INT UNSIGNED;
    DECLARE matchedItemId INT UNSIGNED;
    DECLARE check1 BIT;
    DECLARE check2 BIT;
    DECLARE check3 BIT;
    DECLARE isContainer BIT;
    DECLARE isMount BIT;
    DECLARE isVehicle BIT;
    DECLARE isScroll BIT;
    DECLARE hasCharges BIT;
    DECLARE maxCharges SMALLINT UNSIGNED;
    DECLARE isPack BIT;
    DECLARE curseEffect VARCHAR(1000);
    DECLARE isCursed BIT;
    DECLARE allowAdditionalSpells BIT;

    SET max_sp_recursion_depth = 1;
    SET check1 = (SELECT 1 FROM items WHERE id = itemId);
    SET check2 = (SELECT 1 FROM creature_items WHERE id = containerItemId);
    SET check3 = (SELECT 1 FROM creatures WHERE id = creatureId);

    IF containerItemId = 0 THEN
        SET containerItemId = NULL;
    END IF;

    IF check1 IS NOT NULL AND (containerItemId IS NULL OR check2 IS NOT NULL) AND check3 IS NOT NULL THEN
        SELECT container, item_type_id = 6, item_type_id = 10, item_type_id = 8, mi.max_charges, mi.curse_effect, mi.additional_spells, mi.magical_item_type_id = 5
        INTO isContainer, isMount, isVehicle, isPack, maxCharges, curseEffect, allowAdditionalSpells, isScroll
        FROM items i
            LEFT JOIN magical_items mi ON mi.item_id = i.id
        WHERE id = itemId;

        IF maxCharges IS NULL THEN
            SET maxCharges = 0;
        END IF;

        IF allowAdditionalSpells IS NULL THEN
            SET allowAdditionalSpells = 0;
        END IF;

        IF isScroll IS NULL THEN
            SET isScroll = 0;
        END IF;

        SET hasCharges = (maxCharges > 0);
        SET isCursed = curseEffect IS NOT NULL AND curseEffect != '';

        IF isPack THEN
            CALL CreatureItems_AddPackItems(creatureId, itemId, itemQuantity, containerItemId, creatureItemStateId);
        ELSEIF isContainer OR isMount OR isVehicle OR hasCharges OR isCursed OR allowAdditionalSpells OR isScroll OR spellId IS NOT NULL THEN
            SET x = 1;
            uniqueLoop: LOOP
                IF x > itemQuantity THEN
                    LEAVE uniqueLoop;
                END IF;

                INSERT INTO creature_items (creature_id, item_id, quantity, container_id, creature_item_state_id, magic_item_type_id, charges, cursed) VALUE
                (creatureId, itemId, 1, containerItemId, creatureItemStateId, magicItemTypeId, maxCharges, isCursed);

                SET creatureItemId = (SELECT LAST_INSERT_ID());
                SELECT creatureItemId AS creature_item_id;

                IF spellId IS NOT NULL THEN
                    CALL CreatureItems_AddSpell(creatureItemId, spellId);
                END IF;

                SET  x = x + 1;
            END LOOP;

            CALL CreatureActions_Items_Add(creatureId, itemId, magicItemTypeId);
        ELSE
            SET matchedItemId = (SELECT id
                FROM creature_items ci
                WHERE
                    ci.item_id = itemId
                    AND creature_id = creatureId
                    AND equipped_slot_id IS NULL
                    AND ((container_id IS NULL AND containerItemId IS NULL) OR container_id = containerItemId)
                    AND creature_item_state_id = creatureItemStateId
                    AND poisoned = 0
                    AND silvered = 0
                    AND full = 0
                    AND attuned = 0
                    AND cursed = itemCursed
                    AND ((magic_item_type_id IS NULL AND magicItemTypeId IS NULL) OR magic_item_type_id = magicItemTypeId)
                    AND (notes IS NULL OR notes = '')
                LIMIT 1);

            IF matchedItemId IS NULL THEN
                INSERT INTO creature_items (creature_id, item_id, quantity, container_id, creature_item_state_id, magic_item_type_id, cursed) VALUE
                (creatureId, itemId, itemQuantity, containerItemId, creatureItemStateId, magicItemTypeId, isCursed);

                SELECT LAST_INSERT_ID() AS creature_item_id;

                CALL CreatureActions_Items_Add(creatureId, itemId, magicItemTypeId);
            ELSE
                UPDATE creature_items
                SET quantity = quantity + itemQuantity
                WHERE id = matchedItemId;

                SELECT matchedItemId AS creature_item_id;
            END IF;
        END IF;
    END IF;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `CreatureItems_AddPackItems` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `CreatureItems_AddPackItems`(
    IN creatureId INT UNSIGNED,
    IN packId INT UNSIGNED,
    IN itemQuantity SMALLINT UNSIGNED,
    IN containerItemId INT UNSIGNED,
    IN creatureItemStateId TINYINT UNSIGNED
)
BEGIN
    DECLARE packItemId INT UNSIGNED;
    DECLARE packItemQuantity SMALLINT UNSIGNED;
    DECLARE more_rows BOOLEAN DEFAULT TRUE;
    DECLARE curs CURSOR FOR SELECT pi.item_id, pi.quantity
                            FROM packs p
                            JOIN pack_items pi on p.item_id = pi.pack_id
                            WHERE p.item_id = packId;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET more_rows = FALSE;

    OPEN curs;

    WHILE more_rows DO
        FETCH curs INTO packItemId, packItemQuantity;

        IF more_rows THEN
            CALL CreatureItems_Add(creatureId, packItemId, packItemQuantity * itemQuantity, containerItemId, null, null, creatureItemStateId, 0);
        END IF;
    END WHILE;

    CLOSE curs;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `CreatureItems_AddSpell` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `CreatureItems_AddSpell`(
    IN creatureItemId INT UNSIGNED,
    IN spellId INT UNSIGNED
)
BEGIN
    DECLARE spellLevel SMALLINT UNSIGNED;

    SET spellLevel = (SELECT level FROM spells WHERE power_id = spellId);

    INSERT INTO creature_item_spells (creature_item_id, spell_id, stored_level, charges, allow_casting_at_higher_level, charges_per_level_above_stored_level, max_level, remove_on_casting, override_spell_attack_calculation, spell_attack_modifier, spell_save_dc) VALUES
    (creatureItemId, spellId, spellLevel, 0, 0, 0, spellLevel, 0, 0, 0, 0);

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `CreatureItems_Delete` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `CreatureItems_Delete`(
    IN creatureItemId INT UNSIGNED
)
BEGIN
    DELETE FROM creature_item_spells WHERE creature_item_id = creatureItemId;
    DELETE FROM creature_items WHERE id = creatureItemId;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `CreatureItems_Discard` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `CreatureItems_Discard`(
    IN creatureItemId INT UNSIGNED,
    IN itemQuantity SMALLINT UNSIGNED
)
BEGIN
    DECLARE currentQuantity SMALLINT UNSIGNED;
    DECLARE isContainer BIT;
    DECLARE isMount BIT;
    DECLARE isVehicle BIT;
    DECLARE creatureId INT UNSIGNED;
    DECLARE itemId INT UNSIGNED;
    DECLARE subItemId INT UNSIGNED;

    SELECT ci.quantity, i.container, i.item_type_id = 6, i.item_type_id = 10, creature_id, item_id, magic_item_type_id
    INTO currentQuantity, isContainer, isMount, isVehicle, creatureId, itemId, subItemId
    FROM creature_items ci
    JOIN items i ON ci.item_id = i.id
    WHERE ci.id = creatureItemId;

    IF itemQuantity > currentQuantity THEN
        SET itemQuantity = currentQuantity;
    END IF;

    IF itemQuantity = currentQuantity THEN
        IF isContainer OR isMount OR isVehicle THEN
            CALL CreatureItems_DiscardContainerItems(creatureItemId, creatureId, 0);
        END IF;

        CALL CreatureItems_Delete(creatureItemId);

        CALL CreatureActions_Items_Validate(creatureId);
   ELSE
        UPDATE creature_items
        SET quantity = quantity - itemQuantity
        WHERE id = creatureItemId;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `CreatureItems_DiscardContainerItems` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `CreatureItems_DiscardContainerItems`(
    IN containerItemId INT UNSIGNED,
    IN creatureId INT UNSIGNED,
    IN validateActions BIT
)
BEGIN
    DECLARE nestedItemId INT UNSIGNED;
    DECLARE isContainer BIT;
    DECLARE isMount BIT;
    DECLARE isVehicle BIT;

    DECLARE more_rows BOOLEAN DEFAULT TRUE;
    DECLARE curs CURSOR FOR SELECT ci.id, i.container, i.item_type_id = 6, i.item_type_id = 10
                            FROM creature_items ci
                            JOIN items i on ci.item_id = i.id
                            WHERE container_id = containerItemId;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET more_rows = FALSE;

    SET max_sp_recursion_depth = 255;

    OPEN curs;
    WHILE more_rows DO
        FETCH curs INTO nestedItemId, isContainer, isMount, isVehicle;

        IF more_rows THEN
            IF isContainer OR isMount OR isVehicle THEN
                CALL CreatureItems_DiscardContainerItems(nestedItemId, creatureId, 0);
            END IF;
            CALL CreatureItems_Delete(nestedItemId);
        END IF;
    END WHILE;
    CLOSE curs;

    IF validateActions THEN
        CALL CreatureActions_Items_Validate(creatureId);
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `CreatureItems_Disenchant` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `CreatureItems_Disenchant`(
    IN creatureId INT UNSIGNED,
    IN creatureItemId INT UNSIGNED,
    IN itemQuantity SMALLINT UNSIGNED,
    IN creatureItemStateId TINYINT UNSIGNED
)
BEGIN
    DECLARE originalQuantity SMALLINT UNSIGNED;
    DECLARE baseItemId INT UNSIGNED;
    DECLARE containerItemId INT UNSIGNED;
    DECLARE originalCreatureItemStateId TINYINT UNSIGNED;
    DECLARE equippedSlotId INT UNSIGNED;

    SELECT quantity, magic_item_type_id, container_id, creature_item_state_id, equipped_slot_id
    INTO originalQuantity, baseItemId, containerItemId, originalCreatureItemStateId, equippedSlotId
    FROM creature_items
    WHERE id = creatureItemId;

    IF creatureItemStateId IS NULL THEN
        SET creatureItemStateId = originalCreatureItemStateId;
    END IF;

    IF creatureItemStateId = 4 THEN -- expended
        SET containerItemId = NULL;
    END IF;

    IF creatureItemStateId = 3 THEN -- equipped
        INSERT INTO creature_items (creature_id, item_id, quantity, equipped_slot_id, container_id, expanded, poisoned, silvered, full, attuned, charges, cursed, magic_item_type_id, notes, creature_item_state_id) VALUES
        (creatureId, baseItemId, itemQuantity, equippedSlotId, null, 0, 0, 0, 0, 0, 0, 0, null, '', 3);

        CALL CreatureActions_Items_Add(creatureId, baseItemId, null);
    ELSE
        CALL CreatureItems_Add(creatureId,baseItemId,itemQuantity,containerItemId,null, null,creatureItemStateId,0);
    END IF;

    IF itemQuantity = originalQuantity THEN
        CALL CreatureItems_Delete(creatureItemId);
        CALL CreatureActions_Items_Validate(creatureId);
    ELSE
        UPDATE creature_items SET quantity = quantity - 1 WHERE id = creatureItemId;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `CreatureItems_Drop` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `CreatureItems_Drop`(
    IN creatureId INT UNSIGNED,
    IN creatureItemId INT UNSIGNED,
    IN itemQuantity SMALLINT UNSIGNED,
    IN containerItemId INT UNSIGNED
)
BEGIN
    DECLARE droppedCreatureItemStateId TINYINT UNSIGNED;
    SET droppedCreatureItemStateId = 2;
    CALL CreatureItems_Move(creatureId, creatureItemId, itemQuantity, containerItemId, droppedCreatureItemStateId);
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `CreatureItems_EmptyContainer` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `CreatureItems_EmptyContainer`(
    IN creatureItemId INT UNSIGNED,
    IN containerItemId INT UNSIGNED
)
BEGIN
    DECLARE creatureId INT UNSIGNED;
    DECLARE nestedItemId INT UNSIGNED;
    DECLARE itemQuantity SMALLINT UNSIGNED;
    DECLARE creatureItemStateId TINYINT UNSIGNED;

    DECLARE more_rows BOOLEAN DEFAULT TRUE;
    DECLARE curs CURSOR FOR SELECT ci.creature_id, ci.id, ci.quantity, ci.creature_item_state_id
                            FROM creature_items ci
                            JOIN items i on ci.item_id = i.id
                            WHERE container_id = creatureItemId;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET more_rows = FALSE;

    OPEN curs;

    WHILE more_rows DO
        FETCH curs INTO creatureId, nestedItemId, itemQuantity, creatureItemStateId;

        IF more_rows THEN
            CALL CreatureItems_Move(creatureId,nestedItemId,itemQuantity,containerItemId,creatureItemStateId);
        END IF;
    END WHILE;

    CLOSE curs;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `CreatureItems_Equip` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `CreatureItems_Equip`(
    IN creatureId INT UNSIGNED,
    IN creatureItemId INT UNSIGNED,
    IN equipmentSlotId INT UNSIGNED,
    IN containerItemId INT UNSIGNED
)
BEGIN
    DECLARE currentlyEquippedItemId INT UNSIGNED;
    DECLARE currentQuantity SMALLINT UNSIGNED;
    DECLARE equippedCreatureItemStateId TINYINT UNSIGNED;
    SET equippedCreatureItemStateId = 3;

    SET currentlyEquippedItemId = (SELECT id FROM creature_items WHERE creature_id = creatureId AND equipped_slot_id = equipmentSlotId);

    IF currentlyEquippedItemId IS NOT NULL THEN
        CALL CreatureItems_UnEquip(creatureId, currentlyEquippedItemId, containerItemId);
    END IF;

    SET currentQuantity = (SELECT quantity FROM creature_items WHERE id = creatureItemId);

    IF currentQuantity > 1 THEN
        UPDATE creature_items
        SET quantity = quantity - 1
        WHERE id = creatureItemId;

        INSERT INTO creature_items (creature_id, item_id, quantity, equipped_slot_id, creature_item_state_id, container_id, expanded, poisoned, silvered, full, attuned, charges, cursed, magic_item_type_id, notes)
        SELECT creatureId, item_id, 1, equipmentSlotId, equippedCreatureItemStateId, null, expanded, poisoned, silvered, full, attuned, charges, cursed, magic_item_type_id, notes FROM creature_items WHERE id = creatureItemId;

        SELECT LAST_INSERT_ID() AS creature_item_id;
    ELSE
        UPDATE creature_items
        SET equipped_slot_id = equipmentSlotId,
            container_id = NULL,
            creature_item_state_id = equippedCreatureItemStateId
        WHERE id = creatureItemId;

        SELECT creatureItemId AS creature_item_id;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `CreatureItems_Expend` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `CreatureItems_Expend`(
    IN creatureId INT UNSIGNED,
    IN creatureItemId INT UNSIGNED,
    IN itemQuantity SMALLINT UNSIGNED,
    IN containerItemId INT UNSIGNED
)
BEGIN
    DECLARE isMagical BIT;
    DECLARE expendedCreatureItemStateId TINYINT UNSIGNED;

    SET expendedCreatureItemStateId = 4;
    SET isMagical = (SELECT item_type_id = 9 FROM items i JOIN creature_items ci ON ci.item_id = i.id AND ci.id = creatureItemId);

    IF isMagical THEN
        CALL CreatureItems_Disenchant(creatureId, creatureItemId, itemQuantity, expendedCreatureItemStateId);
    ELSE
        CALL CreatureItems_Move(creatureId, creatureItemId, itemQuantity, containerItemId, expendedCreatureItemStateId);
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `CreatureItems_Gain` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `CreatureItems_Gain`(
    IN creatureItemId INT UNSIGNED,
    IN itemQuantity SMALLINT UNSIGNED
)
BEGIN
    DECLARE currentContainer INT UNSIGNED;
    DECLARE currentCreatureItemStateId TINYINT UNSIGNED;
    DECLARE isContainer BIT;
    DECLARE isMount BIT;
    DECLARE isVehicle BIT;
    DECLARE hasCharges BIT;
    DECLARE maxCharges SMALLINT UNSIGNED;
    DECLARE isCursed BIT;
    DECLARE isScroll BIT;
    DECLARE spellId INT UNSIGNED;
    DECLARE allowAdditionalSpells BIT;
    DECLARE creatureId INT UNSIGNED;
    DECLARE baseItemId INT UNSIGNED;
    DECLARE magicalItemTypeId INT UNSIGNED;
    DECLARE forceNew BIT;

    SELECT ci.creature_id, ci.item_id, ci.container_id, ci.creature_item_state_id, i.container, i.item_type_id = 6, i.item_type_id = 10, ci.magic_item_type_id, mi.max_charges, ci.cursed, mi.additional_spells, mi.magical_item_type_id = 5
    INTO creatureId, baseItemId, currentContainer, currentCreatureItemStateId, isContainer, isMount, isVehicle, magicalItemTypeId, maxCharges, isCursed, allowAdditionalSpells, isScroll
    FROM creature_items ci
    JOIN items i ON ci.item_id = i.id
    LEFT JOIN magical_items mi ON mi.item_id = i.id
    WHERE ci.id = creatureItemId;

    SET forceNew = currentCreatureItemStateId = 3; -- equipped
    IF forceNew THEN -- equipped
        SET currentCreatureItemStateId = 1; -- carried
        SET currentContainer = NULL;
    END IF;

    IF allowAdditionalSpells IS NULL THEN
        SET allowAdditionalSpells = 0;
    END IF;

    IF isScroll IS NULL THEN
        SET isScroll = 0;
    END IF;

    IF isScroll THEN
        SET spellId = (SELECT spell_id FROM creature_item_spells WHERE creature_item_id = creatureItemId LIMIT 1);
    END IF;

    SET hasCharges = (maxCharges IS NOT NULL AND maxCharges > 0);

    IF isContainer OR isMount OR isVehicle OR hasCharges OR allowAdditionalSpells OR isCursed OR isScroll OR forceNew THEN
        CALL CreatureItems_Add(creatureId,baseItemId,itemQuantity,currentContainer,magicalItemTypeId, spellId,currentCreatureItemStateId,isCursed);
    ELSE
        UPDATE creature_items
        SET quantity = quantity + itemQuantity
        WHERE id = creatureItemId;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `CreatureItems_Get` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `CreatureItems_Get`(
    IN creatureId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    DECLARE creatureUserId MEDIUMINT UNSIGNED;
    DECLARE itemId INT UNSIGNED;
    DECLARE magicItemId INT UNSIGNED;
    DECLARE more_rows BOOLEAN DEFAULT TRUE;
    DECLARE curs CURSOR FOR SELECT DISTINCT item_id FROM creature_items WHERE creature_id = creatureId;
    DECLARE curs2 CURSOR FOR SELECT DISTINCT magic_item_type_id FROM creature_items WHERE creature_id = creatureId AND magic_item_type_id IS NOT NULL;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET more_rows = FALSE;

    SET creatureUserId = (SELECT user_id FROM creatures WHERE id = creatureId);

    SELECT
        ci.id,
        ci.item_id,
        i.name AS item_name,
        i.sid AS item_sid,
        i.item_type_id,
        i.container AS is_container,
        i.ignore_weight,
        i.weight,
        ci.quantity,
        ci.equipped_slot_id,
        es.name AS equipped_slot_name,
        es.equipment_slot_type_id,
        ci.container_id,
        ci.creature_item_state_id,
        ci.expanded,
        ci.poisoned,
        ci.silvered,
        ci.full,
        ci.attuned,
        ci.charges AS charges_remaining,
        mi.max_charges,
        ci.cursed,
        ci.magic_item_type_id,
        ci.notes
    FROM creature_items ci
    JOIN items i ON ci.item_id = i.id
    LEFT JOIN equipment_slots es ON ci.equipped_slot_id = es.id
    LEFT JOIN magical_items mi ON mi.item_id = i.id
    WHERE creature_id = creatureId
    ORDER BY i.name;

    SELECT COUNT(DISTINCT item_id) AS item_count FROM creature_items WHERE creature_id = creatureId;

    OPEN curs;

    WHILE more_rows DO
        FETCH curs INTO itemId;

        IF more_rows THEN
            CALL Items_Get(itemId, creatureUserId);
        END IF;
    END WHILE;

    CLOSE curs;

    SELECT COUNT(DISTINCT magic_item_type_id) AS magic_item_count FROM creature_items WHERE creature_id = creatureId AND magic_item_type_id IS NOT NULL;

    OPEN curs2;

    SET more_rows = 1;
    WHILE more_rows DO
        FETCH curs2 INTO magicItemId;

        IF more_rows THEN
            CALL Items_Get(magicItemId, creatureUserId);
        END IF;
    END WHILE;

    CLOSE curs2;

    # spells
    CREATE TEMPORARY TABLE IF NOT EXISTS temp_additional_spells
    (
        creature_item_id INT UNSIGNED NOT NULL,
        item_id INT UNSIGNED NOT NULL,
        spell_id INT UNSIGNED NOT NULL
    );

    CREATE TEMPORARY TABLE IF NOT EXISTS temp_magical_item_spells
    (
        creature_item_id INT UNSIGNED NOT NULL,
        item_id INT UNSIGNED NOT NULL,
        spell_id INT UNSIGNED NOT NULL
    );

    CREATE TEMPORARY TABLE IF NOT EXISTS temp_all_spells
    (
        spell_id INT UNSIGNED NOT NULL
    );

    INSERT INTO temp_additional_spells
    SELECT ci.id, ci.item_id, cis.spell_id
    FROM creature_items ci
    JOIN creature_item_spells cis ON cis.creature_item_id = ci.id AND ci.creature_id = creatureId;

    INSERT INTO temp_magical_item_spells
    SELECT ci.id, ci.item_id, mis.spell_id
    FROM creature_items ci
    JOIN magical_item_spells mis ON mis.magical_item_id = ci.item_id AND ci.creature_id = creatureId;

    INSERT INTO temp_all_spells
    SELECT DISTINCT spell_id FROM (
        SELECT spell_id FROM temp_additional_spells
        UNION
        SELECT spell_id FROM temp_magical_item_spells
    ) AS a;

    SELECT creature_item_id, additional, spell_id, stored_level, charges, allow_casting_at_higher_level, charges_per_level_above_stored_level,
           max_level, remove_on_casting, override_spell_attack_calculation, spell_attack_modifier, spell_save_dc,
           p.name AS spell_name, p.sid AS spell_sid, p.user_id = userId AS spell_is_author, s.level AS spell_level,
           caster_level_id, level_name, level_description, level_sid, level_is_author, level_version, min_exp, prof_bonus
    FROM
    (
        SELECT t.creature_item_id, 1 AS additional, cis.spell_id, cis.stored_level, cis.charges,
               cis.allow_casting_at_higher_level, cis.charges_per_level_above_stored_level, cis.max_level,
               cis.remove_on_casting, cis.override_spell_attack_calculation, cis.spell_attack_modifier, cis.spell_save_dc,
               cis.caster_level_id, a.name AS level_name, a.description AS level_description, a.sid AS level_sid,
               a.user_id = userId AS level_is_author, a.version AS level_version, cl.min_exp, cl.prof_bonus
        FROM creature_item_spells cis
        JOIN temp_additional_spells t ON cis.creature_item_id = t.creature_item_id AND cis.spell_id = t.spell_id
        LEFT JOIN attributes a ON a.id = cis.caster_level_id
        LEFT JOIN character_levels cl ON a.id = cl.attribute_id

        UNION

        SELECT t.creature_item_id, 0 AS additional, mis.spell_id, mis.stored_level, mis.charges,
               mis.allow_casting_at_higher_level, mis.charges_per_level_above_stored_level, mis.max_level,
               mis.remove_on_casting, mis.override_spell_attack_calculation, mis.spell_attack_modifier, mis.spell_save_dc,
               mis.caster_level_id, a.name AS level_name, a.description AS level_description, a.sid AS level_sid,
               a.user_id = userId AS level_is_author, a.version AS level_version, cl.min_exp, cl.prof_bonus
        FROM magical_item_spells mis
        JOIN temp_magical_item_spells t ON mis.magical_item_id = t.item_id AND mis.spell_id = t.spell_id
        LEFT JOIN attributes a ON a.id = mis.caster_level_id
        LEFT JOIN character_levels cl ON a.id = cl.attribute_id
    ) AS cis
    JOIN powers p ON p.id = cis.spell_id
    JOIN spells s ON s.power_id = p.id
    ORDER BY p.name;

    # spell tags
    SELECT p.power_id, t.id, t.power_type_id, t.title, t.color
    FROM creature_power_tags p
        JOIN creature_tags t ON p.creature_tag_id = t.id
    WHERE p.creature_id = creatureId and p.power_id IN (SELECT spell_id FROM temp_all_spells);

    DROP TEMPORARY TABLE IF EXISTS temp_additional_spells;
    DROP TEMPORARY TABLE IF EXISTS temp_magical_item_spells;
    DROP TEMPORARY TABLE IF EXISTS temp_all_spells;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `CreatureItems_Move` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `CreatureItems_Move`(
    IN creatureId INT UNSIGNED,
    IN creatureItemId INT UNSIGNED,
    IN itemQuantity SMALLINT UNSIGNED,
    IN containerItemId INT UNSIGNED,
    IN toCreatureItemStateId TINYINT UNSIGNED
)
BEGIN
    DECLARE currentQuantity SMALLINT UNSIGNED;
    DECLARE matchedItemId INT UNSIGNED;
    DECLARE currentContainer INT UNSIGNED;
    DECLARE currentSlot INT UNSIGNED;
    DECLARE currentCreatureItemStateId TINYINT UNSIGNED;
    DECLARE check1 BIT;
    DECLARE check2 BIT;
    DECLARE check3 BIT;
    DECLARE isContainer BIT;
    DECLARE isMount BIT;
    DECLARE isVehicle BIT;
    DECLARE hasCharges BIT;
    DECLARE maxCharges SMALLINT UNSIGNED;
    DECLARE isCursed BIT;
    DECLARE isScroll BIT;
    DECLARE revertContainer BIT;
    DECLARE nestedContainerId INT UNSIGNED;
    DECLARE allowAdditionalSpells BIT;

    SET check1 = (SELECT 1 FROM creature_items WHERE id = creatureItemId);
    SET check2 = (SELECT 1 FROM creature_items WHERE id = containerItemId);
    SET check3 = (SELECT 1 FROM creatures WHERE id = creatureId);

    IF check1 IS NOT NULL AND (containerItemId IS NULL OR check2 IS NOT NULL) AND check3 IS NOT NULL THEN
        SELECT ci.quantity, ci.equipped_slot_id, ci.container_id, ci.creature_item_state_id, i.container, i.item_type_id = 6, i.item_type_id = 10, mi.max_charges, ci.cursed, mi.additional_spells, mi.magical_item_type_id = 5
        INTO currentQuantity, currentSlot, currentContainer, currentCreatureItemStateId, isContainer, isMount, isVehicle, maxCharges, isCursed, allowAdditionalSpells, isScroll
        FROM creature_items ci
        JOIN items i ON ci.item_id = i.id
        LEFT JOIN magical_items mi ON mi.item_id = i.id
        WHERE ci.id = creatureItemId;

        SET hasCharges = (maxCharges IS NOT NULL AND maxCharges > 0);

        IF toCreatureItemStateId IS NULL THEN
            SET toCreatureItemStateId = currentCreatureItemStateId;
        END IF;

        IF allowAdditionalSpells IS NULL THEN
            SET allowAdditionalSpells = 0;
        END IF;

        IF isScroll IS NULL THEN
            SET isScroll = 0;
        END IF;

        IF isContainer OR isMount OR isVehicle OR hasCharges OR allowAdditionalSpells OR isCursed OR isScroll THEN
            SET revertContainer = 0;
            IF containerItemId = creatureItemId THEN
                SET revertContainer = 1;
            END IF;

            SET nestedContainerId = (SELECT id
                FROM (WITH RECURSIVE containers (id, name, container_id) AS
                    (
                        SELECT ci.id, i.name, ci.container_id
                        FROM creature_items ci
                            JOIN items i ON i.id = ci.item_id
                        WHERE ci.container_id IS NULL
                            AND i.container = 1
                            AND ci.id = creatureItemId

                        UNION ALL

                        SELECT ci2.id, i2.name, ci2.container_id
                        FROM containers AS c
                            JOIN creature_items AS ci2 ON c.id = ci2.container_id
                            JOIN items i2 ON i2.id = ci2.item_id
                        WHERE i2.container = 1
                    )
                    SELECT * FROM containers) AS a
                    WHERE container_id IS NOT NULL
                        AND id = containerItemId
                    LIMIT 1);

            IF nestedContainerId IS NOT NULL THEN
                SET revertContainer = 1;
            END IF;

            IF revertContainer THEN
                # don't move to the new container. instead just keep it where it already is
                SET containerItemId = (SELECT container_id FROM creature_items WHERE id = creatureItemId);
            END IF;

            UPDATE creature_items
            SET creature_item_state_id = toCreatureItemStateId,
                equipped_slot_id = NULL,
                container_id = containerItemId
            WHERE id = creatureItemId;

            SELECT creatureItemId AS creature_item_id;

        ELSEIF (currentContainer IS NULL AND containerItemId IS NOT NULL)
                   OR (currentContainer IS NOT NULL AND containerItemId IS NULL)
                   OR currentContainer != containerItemId
                   OR currentSlot IS NOT NULL
                   OR currentCreatureItemStateId != toCreatureItemStateId THEN
            IF itemQuantity > currentQuantity THEN
                SET itemQuantity = currentQuantity;
            END IF;

            SET matchedItemId = (
                SELECT ci2_id FROM matching_creature_items
                WHERE ci_id =  creatureItemId
                  AND (
                        (containerItemId IS NULL AND ci2_container_id IS NULL AND ci2_creature_item_state_id = toCreatureItemStateId)
                        OR ci2_container_id = containerItemId
                      )
                LIMIT 1);

            IF itemQuantity = currentQuantity THEN
                IF matchedItemId IS NULL THEN
                    UPDATE creature_items
                    SET container_id = containerItemId,
                        equipped_slot_id = NULL,
                        creature_item_state_id = toCreatureItemStateId
                    WHERE id = creatureItemId;

                    SELECT creatureItemId AS creature_item_id;
                ELSE
                    UPDATE creature_items
                    SET quantity = quantity + itemQuantity
                    WHERE id = matchedItemId;

                    CALL CreatureItems_Delete(creatureItemId);

                    SELECT matchedItemId AS creature_item_id;
                END IF;
            ELSE
                IF matchedItemId IS NULL THEN
                    INSERT INTO creature_items (creature_id, item_id, quantity, equipped_slot_id, creature_item_state_id, container_id, expanded, poisoned, silvered, full, attuned, charges, cursed, magic_item_type_id, notes)
                    SELECT creatureId, item_id, itemQuantity, null, toCreatureItemStateId, containerItemId, expanded, poisoned, silvered, full, attuned, charges, cursed, magic_item_type_id, notes FROM creature_items WHERE id = creatureItemId;

                    SELECT LAST_INSERT_ID() AS creature_item_id;
                ELSE
                    UPDATE creature_items
                    SET quantity = quantity + itemQuantity
                    WHERE id = matchedItemId;

                    SELECT matchedItemId AS creature_item_id;
                END IF;

                UPDATE creature_items
                SET quantity = quantity - itemQuantity,
                    equipped_slot_id = NULL
                WHERE id = creatureItemId;
            END IF;
#             SELECT 1 AS result;
#         ELSE
#             SELECT 0;
        END IF;
#     ELSE
#         SELECT 0;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `CreatureItems_Pickup` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `CreatureItems_Pickup`(
    IN creatureId INT UNSIGNED,
    IN creatureItemId INT UNSIGNED,
    IN itemQuantity SMALLINT UNSIGNED,
    IN containerItemId INT UNSIGNED,
    IN discardRemaining BIT
)
BEGIN
    DECLARE originalCreatureItemStateId TINYINT UNSIGNED;
    DECLARE carriedCreatureItemStateId TINYINT UNSIGNED;
    SET originalCreatureItemStateId = (SELECT creature_item_state_id FROM creature_items WHERE id = creatureItemId);
    SET carriedCreatureItemStateId = 1;
    CALL CreatureItems_Move(creatureId, creatureItemId, itemQuantity, containerItemId, carriedCreatureItemStateId);
    IF discardRemaining THEN
        CALL CreatureItems_Delete(creatureItemId);
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `CreatureItems_UnEquip` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `CreatureItems_UnEquip`(
    IN creatureId INT UNSIGNED,
    IN creatureItemId INT UNSIGNED,
    IN containerItemId INT UNSIGNED
)
BEGIN
    DECLARE carriedCreatureItemStateId TINYINT UNSIGNED;
    SET carriedCreatureItemStateId = 1;
    CALL CreatureItems_Move(creatureId, creatureItemId, 1, containerItemId, carriedCreatureItemStateId);
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `CreatureItems_Update` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `CreatureItems_Update`(
    IN creatureItemId INT UNSIGNED,
    IN itemQuantity SMALLINT UNSIGNED,
    IN itemPoisoned BIT,
    IN itemSilvered BIT,
    IN itemFull BIT,
    IN itemAttuned BIT,
    IN itemCursed BIT
)
BEGIN
    DECLARE creatureId INT UNSIGNED;
    DECLARE itemId INT UNSIGNED;
    DECLARE containerItemId INT UNSIGNED;
    DECLARE magicItemTypeId INT UNSIGNED;
    DECLARE currentQuantity SMALLINT UNSIGNED;
    DECLARE currentCreatureItemStateId TINYINT UNSIGNED;
    DECLARE currentPoisoned BIT;
    DECLARE currentSilvered BIT;
    DECLARE currentFull BIT;
    DECLARE currentAttuned BIT;
    DECLARE currentCursed BIT;
    DECLARE currentNotes VARCHAR(100);
    DECLARE matchedItemId INT UNSIGNED;

    DECLARE isContainer BIT;
    DECLARE isMount BIT;
    DECLARE isVehicle BIT;
    DECLARE hasCharges BIT;
    DECLARE maxCharges SMALLINT UNSIGNED;
    DECLARE curseEffect VARCHAR(1000);
    DECLARE isCursed BIT;
    DECLARE useMatch BIT;
    DECLARE allowAdditionalSpells BIT;
    DECLARE isScroll BIT;

    SELECT creature_id, item_id, container_id, quantity, creature_item_state_id, poisoned, silvered, full, attuned, cursed, magic_item_type_id, notes
    INTO creatureId, itemId, containerItemId, currentQuantity, currentCreatureItemStateId, currentPoisoned, currentSilvered, currentFull, currentAttuned, currentCursed, magicItemTypeId, currentNotes
    FROM creature_items
    WHERE id = creatureItemId;

    SELECT container, item_type_id = 6, item_type_id = 10, mi.max_charges, mi.curse_effect, mi.additional_spells, mi.magical_item_type_id = 5
    INTO isContainer, isMount, isVehicle, maxCharges, curseEffect, allowAdditionalSpells, isScroll
    FROM items i
         LEFT JOIN magical_items mi ON mi.item_id = i.id
    WHERE id = itemId;

    IF allowAdditionalSpells IS NULL THEN
        SET allowAdditionalSpells = 0;
    END IF;

    IF isScroll IS NULL THEN
        SET isScroll = 0;
    END IF;

    SET hasCharges = (maxCharges IS NOT NULL AND maxCharges > 0);
    SET isCursed = curseEffect IS NOT NULL AND curseEffect != '';

    SET useMatch = (NOT isContainer AND NOT isMount AND NOT isVehicle AND NOT hasCharges AND NOT allowAdditionalSpells AND NOT isCursed AND NOT isScroll);

    SELECT
            IF(itemPoisoned IS NULL, currentPoisoned, itemPoisoned),
            IF(itemSilvered IS NULL, currentSilvered, itemSilvered),
            IF(itemFull IS NULL, currentFull, itemFull),
            IF(itemAttuned IS NULL, currentAttuned, itemAttuned),
            IF(itemCursed IS NULL, currentCursed, itemCursed)
    INTO itemPoisoned, itemSilvered, itemFull, itemAttuned, itemCursed;

    IF itemQuantity > currentQuantity THEN
        SET itemQuantity = currentQuantity;
    END IF;

    IF useMatch THEN
        SET matchedItemId = (
            SELECT id
            FROM creature_items
            WHERE
                creature_id = creatureId
                AND item_id = itemId
                AND equipped_slot_id IS NULL
                AND ((container_id IS NULL AND containerItemId IS NULL) OR container_id = containerItemId)
                AND creature_item_state_id = currentCreatureItemStateId
                AND poisoned = itemPoisoned
                AND silvered = itemSilvered
                AND full = itemFull
                AND attuned = itemAttuned
                AND cursed = itemCursed
                AND charges = 0
                AND ((magic_item_type_id IS NULL AND magicItemTypeId IS NULL) OR magic_item_type_id = magicItemTypeId)
                AND ((notes IS NULL AND currentNotes IS NULL) OR notes = currentNotes)
            LIMIT 1);
    ELSE
        SET matchedItemId = NULL;
    END IF;

    IF itemQuantity = currentQuantity THEN
        IF matchedItemId IS NULL THEN
            # update original item properties
            UPDATE creature_items
            SET poisoned = itemPoisoned,
                silvered = itemSilvered,
                full = itemFull,
                attuned = itemAttuned,
                cursed = itemCursed
            WHERE id = creatureItemId;

            SELECT creatureItemId AS creature_item_id;
        ELSE
            # update matched item quantity
            UPDATE creature_items
            SET quantity = quantity + itemQuantity
            WHERE id = matchedItemId;

            # delete the original item
            CALL CreatureItems_Delete(creatureItemId);

            SELECT matchedItemId AS creature_item_id;
        END IF;
    ELSE
        IF matchedItemId IS NULL THEN
            # insert new item
            INSERT INTO creature_items (creature_id, item_id, quantity, equipped_slot_id, creature_item_state_id, container_id, expanded, poisoned, silvered, full, attuned, charges, cursed, magic_item_type_id, notes)
            SELECT creature_id, item_id, itemQuantity, null, creature_item_state_id, container_id, expanded, itemPoisoned, itemSilvered, itemFull, itemAttuned, charges, itemCursed, magic_item_type_id, notes FROM creature_items WHERE id = creatureItemId;

            SELECT LAST_INSERT_ID() AS creature_item_id;
        ELSE
            # update matched item quantity
            UPDATE creature_items
            SET quantity = quantity + itemQuantity
            WHERE id = matchedItemId;

            SELECT matchedItemId AS creature_item_id;
        END IF;

        # update original quantity
        UPDATE creature_items
        SET quantity = quantity - itemQuantity
        WHERE id = creatureItemId;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `CreatureItems_UpdateExpanded` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `CreatureItems_UpdateExpanded`(
    IN creatureItemId INT UNSIGNED,
    IN isExpanded BIT
)
BEGIN
    UPDATE creature_items
    SET expanded = isExpanded
    WHERE id = creatureItemId;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `CreaturePowers_Add` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `CreaturePowers_Add`(
    IN creatureId INT UNSIGNED,
    IN powerId INT UNSIGNED,
    IN powerTypeId TINYINT UNSIGNED,
    IN assignedCharacteristicId INT UNSIGNED,
    IN usesRemaining TINYINT UNSIGNED
)
BEGIN
    DECLARE originalCreaturePowerId INT UNSIGNED;
    DECLARE newCreaturePowerId INT UNSIGNED;

    SET originalCreaturePowerId = (SELECT id FROM creature_powers WHERE creature_id = creatureId AND power_id = powerId AND assigned_characteristic_id = assignedCharacteristicId);

    IF originalCreaturePowerId IS NULL THEN
        INSERT INTO creature_powers (creature_id, power_id, power_type_id, assigned_characteristic_id, uses_remaining) VALUES (creatureId, powerId, powerTypeId, assignedCharacteristicId, usesRemaining);

        IF powerTypeId = 1 THEN
            SET newCreaturePowerId = (SELECT LAST_INSERT_ID());
            INSERT INTO creature_spells (creature_power_id, concentrating, prepared) VALUES (newCreaturePowerId, 0, 0);
        END IF;

        CALL CreatureActions_Powers_Add(creatureId, powerId);
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `CreaturePowers_Add_Spell` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `CreaturePowers_Add_Spell`(
    IN creatureId INT UNSIGNED,
    IN powerId INT UNSIGNED,
    IN powerTypeId TINYINT UNSIGNED,
    IN assignedCharacteristicId INT UNSIGNED,
    IN powerInnate BIT,
    IN usesRemaining TINYINT UNSIGNED,
    IN maxUses TINYINT UNSIGNED,
    IN slot TINYINT UNSIGNED
)
BEGIN
    DECLARE originalCreaturePowerId INT UNSIGNED;
    DECLARE newCreaturePowerId INT UNSIGNED;

    SET originalCreaturePowerId = (SELECT id FROM creature_powers WHERE creature_id = creatureId AND power_id = powerId AND assigned_characteristic_id = assignedCharacteristicId);

    IF originalCreaturePowerId IS NULL THEN
        INSERT INTO creature_powers (creature_id, power_id, power_type_id, assigned_characteristic_id, uses_remaining) VALUES (creatureId, powerId, powerTypeId, assignedCharacteristicId, usesRemaining);
        SET newCreaturePowerId = (SELECT LAST_INSERT_ID());
        INSERT INTO creature_spells (creature_power_id, concentrating, prepared, innate, innate_max_uses, innate_slot) VALUES (newCreaturePowerId, 0, 0, powerInnate, maxUses, slot);
        CALL CreatureActions_Powers_Add(creatureId, powerId);
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `CreaturePowers_Delete` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `CreaturePowers_Delete`(
    IN creaturePowerId INT UNSIGNED
)
BEGIN
    DECLARE creatureId INT UNSIGNED;
    DECLARE powerId INT UNSIGNED;

    SELECT creature_id, power_id
    INTO creatureId, powerId
    FROM creature_powers
    WHERE id = creaturePowerId;

    DELETE FROM creature_spells
    WHERE creature_power_id = creaturePowerId;

    DELETE FROM creature_powers
    WHERE id = creaturePowerId;

    CALL CreatureActions_Powers_Delete(creatureId, powerId);
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `CreaturePowers_Get` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `CreaturePowers_Get`(
    IN creatureId INT UNSIGNED,
    IN powerIdArray VARCHAR(1000),
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    CREATE TEMPORARY TABLE IF NOT EXISTS temp_powers
    (
        id INT UNSIGNED NOT NULL
    );

    IF powerIdArray IS NOT NULL THEN
        SET @sql = CONCAT('INSERT INTO temp_powers (id) SELECT power_id FROM creature_powers WHERE power_id IN (', powerIdArray, ')');
        PREPARE stmt FROM @sql;
        EXECUTE stmt;
        DEALLOCATE PREPARE stmt;
    END IF;

    SELECT cp.id, cp.power_id, p.name AS power_name, cp.power_type_id, c.characteristic_type_id,
           cp.assigned_characteristic_id, cp.active, cp.active_target_creature_id, cp.uses_remaining,
           p.recharge_on_short_rest, p.recharge_on_long_rest, p.extra_modifiers, p.modifier_advancement,
           p.modifiers_num_levels_above_base
    FROM creature_powers cp
        JOIN powers p ON cp.power_id = p.id
        LEFT JOIN characteristics c ON c.id = cp.assigned_characteristic_id
    WHERE cp.creature_id = creatureId AND cp.power_id IN (SELECT id FROM temp_powers);

    # Limited Uses
    SELECT p.power_id, p.limited_use_type_id, p.level_id, a.name AS level_name, a.sid AS level_sid,
           a.user_id = userId AS level_is_author, p.quantity, p.ability_modifier_id, p.dice_size_id
    FROM power_limited_uses p
        JOIN character_levels l ON p.level_id = l.attribute_id
        JOIN attributes a ON l.attribute_id = a.id
    WHERE p.power_id IN (SELECT id FROM temp_powers);

    DROP TEMPORARY TABLE IF EXISTS temp_powers;
END ;;
DELIMITER ;
