CREATE DEFINER=`squire`@`%` PROCEDURE `Creatures_Delete`(
    IN creatureId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    DECLARE creatureTypeId TINYINT UNSIGNED;

    SET creatureTypeId = (SELECT creature_type_id FROM creatures WHERE id = creatureId);

    IF creatureTypeId = 1 THEN
        CALL Creatures_Delete_Character(creatureId, userId);
    ELSEIF creatureTypeId = 2 THEN
        CALL Creatures_Delete_BattleMonster(creatureId, userId);
    ELSEIF creatureTypeId = 5 THEN
        CALL Creatures_Delete_Companion(creatureId, userId);
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Creatures_Delete_BattleMonster` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Creatures_Delete_BattleMonster`(
    IN creatureId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    DECLARE battleMonsterId INT UNSIGNED;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
        BEGIN
            GET DIAGNOSTICS condition 1 @SQLState = RETURNED_SQLSTATE, @SQLMessage = MESSAGE_TEXT;
            ROLLBACK;
            INSERT INTO exception_logs (state, message) VALUES (@SQLState, @SQLMessage);
            SELECT -1 AS result;
        END;

    START TRANSACTION;

    SET battleMonsterId = (SELECT id FROM creatures WHERE user_id = userId AND id = creatureId);

    IF battleMonsterId IS NOT NULL THEN
        CALL Creatures_Delete_Common(battleMonsterId, userId);

        UPDATE encounter_creatures ec JOIN creatures c ON c.id = ec.creature_id SET ec.creature_id = NULL WHERE ec.creature_id = battleMonsterId AND c.user_id = userId;
        DELETE s FROM battle_monster_setting_values s JOIN creatures c ON c.id = s.battle_monster_id WHERE battle_monster_id = battleMonsterId AND c.user_id = userId;
        DELETE p FROM battle_monster_powers p JOIN creatures c ON c.id = p.battle_monster_id WHERE battle_monster_id = battleMonsterId AND c.user_id = userId;
        DELETE bm FROM battle_monsters bm JOIN creatures c ON c.id = bm.creature_id WHERE creature_id = battleMonsterId AND c.user_id = userId;
        DELETE FROM creatures WHERE user_id = userId AND id = battleMonsterId;
    END IF;

    COMMIT;

    SELECT 1 AS result;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Creatures_Delete_Character` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Creatures_Delete_Character`(
    IN creatureId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    DECLARE characterId INT UNSIGNED;
    DECLARE companionId INT UNSIGNED;
    DECLARE more_rows BOOLEAN DEFAULT TRUE;
    DECLARE curs CURSOR FOR SELECT id
                            FROM temp_creatures ;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET more_rows = FALSE;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
        BEGIN
            GET DIAGNOSTICS condition 1 @SQLState = RETURNED_SQLSTATE, @SQLMessage = MESSAGE_TEXT;
            ROLLBACK;
            INSERT INTO exception_logs (state, message) VALUES (@SQLState, @SQLMessage);
            SELECT -1 AS result;
        END;

    START TRANSACTION;

    CREATE TEMPORARY TABLE IF NOT EXISTS temp_creatures
    (
        id INT UNSIGNED NOT NULL
    );

    SET characterId = (SELECT id FROM creatures WHERE user_id = userId AND id = creatureId);

    IF characterId IS NOT NULL THEN
        CALL Creatures_Share_UnPublish (creatureId,userId);

        DELETE h FROM character_health_gain_results h JOIN character_chosen_classes ccc ON ccc.id = h.chosen_class_id JOIN creatures c ON c.id = ccc.character_id WHERE c.id = characterId AND c.user_id = userId;
        DELETE asi FROM character_ability_scores_to_increase asi JOIN creatures c ON c.id = asi.character_id WHERE character_id = characterId AND c.user_id = userId;
        DELETE bt FROM character_background_traits bt JOIN creatures c ON c.id = bt.character_id WHERE character_id = characterId AND c.user_id = userId;
        DELETE ccs FROM character_characteristic_spellcasting ccs JOIN creatures c ON c.id = ccs.character_id WHERE character_id = characterId AND c.user_id = userId;
        DELETE ccc FROM character_chosen_classes ccc JOIN creatures c ON c.id = ccc.character_id WHERE character_id = characterId AND c.user_id = userId;
        DELETE cn FROM character_notes cn JOIN creatures c ON c.id = cn.character_id WHERE character_id = characterId AND c.user_id = userId;
        DELETE cnc FROM character_note_categories cnc JOIN creatures c ON c.id = cnc.character_id WHERE character_id = characterId AND c.user_id = userId;
        DELETE cp FROM character_pages cp JOIN creatures c ON c.id = cp.character_id WHERE character_id = characterId AND c.user_id = userId;
        DELETE csv FROM character_setting_values csv JOIN creatures c ON c.id = csv.character_id WHERE character_id = characterId AND c.user_id = userId;
        DELETE cv FROM character_validation cv JOIN creatures c ON c.id = cv.character_id WHERE character_id = characterId AND c.user_id = userId;
        DELETE cvip FROM character_validation_ignored_powers cvip JOIN creatures c ON c.id = cvip.character_id WHERE character_id = characterId AND c.user_id = userId;

        # companions
        INSERT INTO temp_creatures (id)
        SELECT companion_id
        FROM character_companions cc
            JOIN characters ch ON ch.creature_id = cc.character_id AND ch.creature_id = characterId
            JOIN creatures c ON c.id = ch.creature_id
        WHERE c.user_id = userId;
        DELETE cc FROM character_companions cc JOIN characters ch ON ch.creature_id = cc.character_id AND ch.creature_id = characterId JOIN creatures c ON c.id = ch.creature_id WHERE c.user_id = userId;

        CALL Creatures_Delete_Common(characterId, userId);

        DELETE ec FROM encounter_characters ec JOIN encounter_creatures e ON ec.encounter_creature_id = e.id JOIN creatures c ON e.creature_id = c.id WHERE e.creature_id = creatureId AND c.user_id = userId;
        DELETE ec FROM encounter_creatures ec JOIN creatures c ON ec.creature_id = c.id WHERE ec.creature_id = creatureId AND c.user_id = userId;
        DELETE ch FROM characters ch JOIN creatures c ON c.id = ch.creature_id WHERE creature_id = characterId AND c.user_id = userId;
        DELETE cc FROM creatures c JOIN campaign_characters cc ON c.id = cc.creature_id AND c.id = creatureId WHERE c.user_id = userId;
        DELETE FROM creatures WHERE user_id = userId AND id = characterId;

        # delete companions creatures
        OPEN curs;
        WHILE more_rows DO
            FETCH curs INTO companionId;
            IF more_rows THEN
                CALL Creatures_Delete_Companion(companionId, userId);
            END IF;
        END WHILE;
        CLOSE curs;
    END IF;

    COMMIT;

    DROP TEMPORARY TABLE IF EXISTS temp_creatures;
    SELECT 1 AS result;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Creatures_Delete_Characteristic` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Creatures_Delete_Characteristic`(
    IN creatureId INT UNSIGNED,
    IN characteristicId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    CREATE TEMPORARY TABLE IF NOT EXISTS temp_powers
    (
        id INT UNSIGNED NOT NULL,
        power_id INT UNSIGNED NOT NULL
    );

    CREATE TEMPORARY TABLE IF NOT EXISTS temp_powers_2
    (
        power_id INT UNSIGNED NOT NULL
    );

    CREATE TEMPORARY TABLE IF NOT EXISTS temp_actions
    (
        id INT UNSIGNED NOT NULL
    );

    INSERT INTO temp_powers (id, power_id)
    SELECT cp.id, cp.power_id FROM creature_powers cp JOIN creatures c ON c.id = cp.creature_id AND c.id = creatureId AND c.user_id = userId WHERE assigned_characteristic_id = characteristicId;

    DELETE cs FROM creature_spells cs JOIN creature_powers cp ON cs.creature_power_id = cp.id JOIN temp_powers t ON t.id = cp.id;
    DELETE cp FROM creature_powers cp JOIN temp_powers t ON t.id = cp.id;

    INSERT INTO temp_powers_2 (power_id)
    SELECT tp.power_id FROM temp_powers tp WHERE tp.power_id NOT IN (SELECT DISTINCT power_id FROM creature_powers WHERE creature_id = creatureId);

    INSERT INTO temp_actions (id)
    SELECT ca.id FROM creature_actions ca JOIN creature_action_powers cap ON cap.creature_action_id = ca.id WHERE cap.power_id IN (SELECT power_id FROM temp_powers_2);

    DELETE cai FROM chained_action_items cai JOIN temp_actions ta ON ta.id = cai.creature_action_id;
    DELETE cap FROM creature_action_powers cap JOIN temp_actions ta ON ta.id = cap.creature_action_id;
    DELETE ca FROM creature_actions ca JOIN temp_actions ta ON ta.id = ca.id;

    DROP TEMPORARY TABLE IF EXISTS temp_powers;
    DROP TEMPORARY TABLE IF EXISTS temp_powers_2;
    DROP TEMPORARY TABLE IF EXISTS temp_actions;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Creatures_Delete_ChosenClass` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Creatures_Delete_ChosenClass`(
    IN creatureId INT UNSIGNED,
    IN classId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    DECLARE chosenClassId INT UNSIGNED;
    DECLARE subclassId INT UNSIGNED;

    SELECT id, subclass_id
    INTO chosenClassId, subclassId
    FROM character_chosen_classes WHERE character_id = creatureId AND class_id = classId;

    CALL Creatures_Delete_Characteristic(creatureId, classId, userId);
    CALL Creatures_Delete_Characteristic(creatureId, subclassId, userId);

    DELETE h FROM character_health_gain_results h JOIN character_chosen_classes ccc ON ccc.id = h.chosen_class_id JOIN creatures c ON c.id = ccc.character_id WHERE ccc.id = chosenClassId AND c.user_id = userId;
    DELETE ccc FROM character_chosen_classes ccc JOIN creatures c ON c.id = ccc.character_id WHERE ccc.id = chosenClassId AND c.user_id = userId;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Creatures_Delete_Common` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Creatures_Delete_Common`(
    IN creatureId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    DELETE cap FROM creatures c JOIN creature_attribute_profs cap ON cap.creature_id = c.id WHERE c.id = creatureId AND c.user_id = userId;
    DELETE cip FROM creatures c JOIN creature_item_profs cip ON cip.creature_id = c.id WHERE c.id = creatureId AND c.user_id = userId;
    DELETE csc FROM creatures c JOIN creature_spell_configurations csc ON csc.creature_id = c.id WHERE c.id = creatureId AND (c.user_id = userId OR csc.user_id = userId);
	UPDATE creature_powers cp JOIN creatures c ON c.id = cp.creature_id SET active_target_creature_id = NULL WHERE active_target_creature_id = creatureId AND c.user_id = userId;
    DELETE cas FROM creatures c JOIN creature_active_spells cas ON cas.creature_id = c.id WHERE c.id = creatureId AND c.user_id = userId;
    DELETE cs FROM creatures c JOIN creature_powers cp ON cp.creature_id = c.id JOIN creature_spells cs ON cs.creature_power_id = cp.id WHERE c.id = creatureId AND c.user_id = userId;
    DELETE css FROM creatures c JOIN creature_spell_slots css ON css.creature_id = c.id WHERE c.id = creatureId AND c.user_id = userId;
    DELETE cdm FROM creatures c JOIN creature_damage_modifiers cdm ON cdm.creature_id = c.id WHERE c.id = creatureId AND c.user_id = userId;
    DELETE cci FROM creatures c JOIN creature_condition_immunities cci ON cci.creature_id = c.id WHERE c.id = creatureId AND c.user_id = userId;
    DELETE cc FROM creatures c JOIN creature_conditions cc ON cc.creature_id = c.id WHERE c.id = creatureId AND c.user_id = userId;
    DELETE cs FROM creatures c JOIN creature_senses cs ON cs.creature_id = c.id WHERE c.id = creatureId AND c.user_id = userId;
    DELETE cp FROM creatures c JOIN creature_powers cp ON cp.creature_id = c.id WHERE c.id = creatureId AND c.user_id = userId;
    UPDATE creature_items ci JOIN creatures c ON c.id = ci.creature_id SET container_id = NULL WHERE creature_id = creatureId AND c.user_id = userId;
    DELETE cis FROM creatures c JOIN creature_items ci ON ci.creature_id = c.id JOIN creature_item_spells cis ON cis.creature_item_id = ci.id WHERE c.id = creatureId AND c.user_id = userId;
    DELETE ci FROM creatures c JOIN creature_items ci ON ci.creature_id = c.id WHERE c.id = creatureId AND c.user_id = userId;
    DELETE cai FROM creatures c JOIN creature_actions ca ON ca.creature_id = c.id JOIN chained_action_items cai ON cai.chained_action_id = ca.id WHERE c.id = creatureId AND c.user_id = userId;
    DELETE cha FROM creatures c JOIN creature_actions ca ON ca.creature_id = c.id JOIN chained_actions cha ON cha.creature_action_id = ca.id WHERE c.id = creatureId AND c.user_id = userId;
    DELETE cap FROM creatures c JOIN creature_actions ca ON ca.creature_id = c.id JOIN creature_action_powers cap ON cap.creature_action_id = ca.id WHERE c.id = creatureId AND c.user_id = userId;
    DELETE cai FROM creatures c JOIN creature_actions ca ON ca.creature_id = c.id JOIN creature_action_items cai ON cai.creature_action_id = ca.id WHERE c.id = creatureId AND c.user_id = userId;
    DELETE ca FROM creatures c JOIN creature_actions ca ON ca.creature_id = c.id  WHERE c.id = creatureId AND c.user_id = userId;
    DELETE chd FROM creatures c JOIN creature_hit_dice chd ON chd.creature_id = c.id WHERE c.id = creatureId AND c.user_id = userId;
    DELETE cw FROM creatures c JOIN creature_wealth cw ON cw.creature_id = c.id WHERE c.id = creatureId AND c.user_id = userId;
    DELETE ch FROM creatures c JOIN creature_health ch ON ch.creature_id = c.id WHERE c.id = creatureId AND c.user_id = userId;
    DELETE ac FROM creatures c JOIN creature_ac_abilities ac ON ac.creature_id = c.id WHERE c.id = creatureId AND c.user_id = userId;
    DELETE cas FROM creatures c JOIN creature_ability_scores cas ON cas.creature_id = c.id WHERE c.id = creatureId AND c.user_id = userId;
    DELETE cf FROM creatures c JOIN creature_stored_filters cf ON cf.creature_id = c.id WHERE c.id = creatureId AND c.user_id = userId;
    DELETE cs FROM creatures c JOIN creature_stored_sorts cs ON cs.creature_id = c.id WHERE c.id = creatureId AND c.user_id = userId;
    DELETE cs FROM creatures c JOIN creature_spellcasting cs ON cs.creature_id = c.id WHERE c.id = creatureId AND c.user_id = userId;
    DELETE cpt FROM creatures c JOIN creature_power_tags cpt ON cpt.creature_id = c.id WHERE c.id = creatureId AND c.user_id = userId;
    DELETE ct FROM creatures c JOIN creature_tags ct ON ct.creature_id = c.id WHERE c.id = creatureId AND c.user_id = userId;
	DELETE rdr FROM roll_dice_results rdr JOIN roll_results rr on rdr.roll_result_id = rr.id JOIN rolls r ON r.id = rr.roll_id JOIN creatures c ON c.id = r.creature_id WHERE r.creature_id = creatureId AND c.user_id = userId;
    DELETE rr FROM roll_results rr JOIN rolls r ON r.id = rr.roll_id JOIN creatures c ON c.id = r.creature_id WHERE r.creature_id = creatureId AND c.user_id = userId;
    UPDATE rolls r JOIN creatures c ON c.id = r.creature_id SET parent_roll_id = NULL WHERE creature_id = creatureId AND c.user_id = userId;
    DELETE r FROM rolls r JOIN creatures c ON c.id = r.creature_id WHERE creature_id = creatureId AND c.user_id = userId;
    DELETE d FROM creatures c JOIN encounter_creatures ec ON c.id = ec.creature_id AND c.id = creatureId JOIN encounter_creature_conditions bcc ON bcc.encounter_creature_id = ec.id JOIN encounter_creature_condition_damages d ON d.encounter_creature_condition_id = bcc.id WHERE c.user_id = userId;
    DELETE bcc FROM creatures c JOIN encounter_creatures ec ON c.id = ec.creature_id AND c.id = creatureId JOIN encounter_creature_conditions bcc ON bcc.encounter_creature_id = ec.id WHERE c.user_id = userId;

#     UPDATE encounter_creatures ec JOIN creatures c ON c.id = ec.creature_id SET ec.creature_id = NULL WHERE ec.creature_id = creatureId AND c.user_id = userId;
#     DELETE em FROM encounter_monsters em JOIN encounter_creatures e ON em.encounter_creature_id = e.id JOIN creatures c ON e.creature_id = c.id WHERE e.creature_id = creatureId AND c.user_id = userId;
#     DELETE ec FROM encounter_characters ec JOIN encounter_creatures e ON ec.encounter_creature_id = e.id JOIN creatures c ON e.creature_id = c.id WHERE e.creature_id = creatureId AND c.user_id = userId;
#     DELETE ec FROM encounter_creatures ec JOIN creatures c ON ec.creature_id = c.id WHERE ec.creature_id = creatureId AND c.user_id = userId;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
