/*!50003 DROP PROCEDURE IF EXISTS `Creatures_GetAddToMyStuffDetails` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Creatures_GetAddToMyStuffDetails`(
    IN creatureId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED,
    IN checkRights BIT
)
BEGIN
    DECLARE authorCreatureId INT UNSIGNED;
    DECLARE existingCreatureId INT UNSIGNED;
    DECLARE authorUserId MEDIUMINT UNSIGNED;
    DECLARE authorCreatureTypeId TINYINT UNSIGNED;
    DECLARE existingCreatureTypeId TINYINT UNSIGNED;

    IF checkRights = 0 THEN
        SET authorCreatureId = creatureId;
    ELSE
        SET authorCreatureId = (SELECT published_parent_id FROM creatures WHERE user_id = userId AND id = creatureId);
        IF authorCreatureId IS NULL THEN
            SET authorCreatureId = (SELECT creature_id FROM creatures_public WHERE creature_id = creatureId);
        END IF;
        IF authorCreatureId IS NULL THEN
            SET authorCreatureId = (SELECT creature_id FROM creatures_private WHERE user_id = userId AND creature_id = creatureId);
        END IF;
    END IF;

    SELECT user_id, creature_type_id
    INTO authorUserId, authorCreatureTypeId
    FROM creatures WHERE id = authorCreatureId;

    SELECT id, creature_type_id
    INTO existingCreatureId, existingCreatureTypeId
    FROM creatures WHERE published_parent_id = authorCreatureId AND user_id = userId;

    SELECT authorCreatureId AS author_creature_id,
           authorUserId AS author_user_id,
           existingCreatureId AS existing_creature_id,
           authorCreatureTypeId AS author_creature_type_id,
           existingCreatureTypeId AS existing_creature_type_id;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Creatures_GetList_Characters` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Creatures_GetList_Characters`(
    IN userId MEDIUMINT UNSIGNED,
    IN search VARCHAR(45),
    IN offset INT UNSIGNED,
    IN pageSize INT UNSIGNED,
    IN listSource TINYINT UNSIGNED
)
BEGIN
    CREATE TEMPORARY TABLE IF NOT EXISTS temp_list
    (
        id INT UNSIGNED NOT NULL
    );

    IF listSource = 1 THEN
        INSERT INTO temp_list
        SELECT id FROM creatures WHERE creature_type_id = 1 AND user_id = userId
        UNION
        SELECT creature_id FROM creatures_shared WHERE user_id = userId;
    ELSEIF listSource = 2 THEN
        INSERT INTO temp_list SELECT creature_id FROM creatures_public;
    ELSEIF listSource = 3 THEN
        INSERT INTO temp_list SELECT creature_id FROM creatures_private WHERE user_id = userId;
    END IF;

    SELECT c.id, name, sid, c.user_id = userId AS is_author
    FROM temp_list uc
        JOIN creatures c ON c.id = uc.id
    WHERE creature_type_id = 1
        AND (search IS NULL OR search = '' OR search = '%%' OR name LIKE search)
    ORDER BY name
    LIMIT offset, pageSize;

    DROP TEMPORARY TABLE IF EXISTS temp_list;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Creatures_GetPublishedDetails` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Creatures_GetPublishedDetails`(
    IN creatureId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    DECLARE authorCreatureId INT UNSIGNED;

    SET authorCreatureId = (SELECT id FROM creatures WHERE user_id = userId AND id = creatureId);
    SELECT EXISTS(
                   SELECT 1 FROM creatures_public WHERE creature_id = authorCreatureId
                   UNION
                   SELECT 1 FROM creatures_private WHERE creature_id = authorCreatureId
               ) AS published;

    SELECT u.username
    FROM creatures_private ap
             JOIN users u ON u.id = ap.user_id AND ap.creature_id = authorCreatureId;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
