CREATE DEFINER=`squire`@`%` PROCEDURE `Creatures_Get_Character`(
    IN creatureId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    DECLARE characterId INT UNSIGNED;
    DECLARE characterUserId MEDIUMINT UNSIGNED;

    SET characterId = (SELECT id FROM creatures WHERE user_id = userID AND id = creatureId UNION SELECT creature_id FROM creatures_shared WHERE user_id = userId AND creature_id = creatureId);
    IF characterId IS NULL THEN
        SET characterId = (SELECT creature_id FROM creatures_public WHERE creature_id = creatureId);
    END IF;
    IF characterId IS NULL THEN
        SET characterId = (SELECT creature_id FROM creatures_private WHERE user_id = userId AND creature_id = creatureId);
    END IF;

    SET characterUserId = (SELECT user_id FROM creatures WHERE id = characterId);

    SELECT c.id, c.user_id AS character_user_id, c.name, c.alignment_id, alignment.name AS alignment_name, alignment.sid AS alignment_sid,
           alignment.user_id = characterUserId AS alignment_is_author, c.spellcasting_ability_id,
           ch.race_id, ch.race_spellcasting_ability_id, ch.exp, ch.background_id, ch.background_spellcasting_ability_id,
           ch.custom_background_name, ch.custom_background_variation, ch.custom_background_personality,
           ch.custom_background_ideal, ch.custom_background_bond, ch.custom_background_flaw, ch.bio,
           ch.height, ch.eyes, ch.hair, ch.skin, ch.gender_id, ch.age, ch.weight, ch.deity_id,
           deity.name AS deity_name, deity.sid AS deity_sid, deity.user_id = characterUserId AS deity_is_author, ch.inspiration,
           ch.hp_gain_modifier, ch.health_calculation_type_id, c3.token AS campaign_token, ch.image_file_location
    FROM creatures c
        JOIN characters ch ON ch.creature_id = c.id AND c.id = characterId
        LEFT JOIN alignments al ON c.alignment_id = al.attribute_id
        LEFT JOIN attributes alignment ON al.attribute_id = alignment.id
        LEFT JOIN deities d ON ch.deity_id = d.attribute_id
        LEFT JOIN attributes deity ON d.attribute_id = deity.id
        LEFT JOIN campaign_characters cc2 on ch.creature_id = cc2.creature_id
        LEFT JOIN campaigns c3 on cc2.campaign_id = c3.id;

    # todo - if not null

    CALL Creatures_Get_StoredFilters(creatureId);
    CALL Creatures_Get_StoredSorts(creatureId);
    CALL Character_Get_Race(creatureId, characterUserId);
    CALL Character_Get_Classes(creatureId, characterUserId);
    CALL Character_Get_Background(creatureId, characterUserId);

    # Ability Scores
    SELECT a.id, a.name, a.description, a.sid, a.user_id = characterUserId AS is_author, a.version, ab.abbr, cas.value, cas.misc_modifier, cas.asi_modifier
    FROM creature_ability_scores cas
        JOIN abilities ab ON ab.attribute_id = cas.ability_id
        JOIN attributes a ON a.id = ab.attribute_id
    WHERE cas.creature_id = characterId;

    # AC Abilities
    SELECT a.id, a.name, a.description, a.sid, a.user_id = characterUserId AS is_author
    FROM creature_ac_abilities cas
        JOIN attributes a ON a.id = cas.ability_id
    WHERE cas.creature_id = characterId;

    # Wealth
    SELECT cost_unit_id, cu.name AS cost_unit_name, abbreviation AS cost_unit_abbreviation, conversion_unit AS conversion_unit_id, conversion_value, cu.weight AS cost_unit_weight, quantity, display, display_order
    FROM creature_wealth cw
        JOIN cost_units cu ON cw.cost_unit_id = cu.id
    WHERE creature_id = characterId
    ORDER BY display_order;

    # Creature Health
    SELECT current_hp, temp_hp, max_hp_mod, num_death_saving_throw_successes, num_death_saving_throw_failures, death_save_mod, death_save_advantage, death_save_disadvantage, resurrection_penalty, exhaustion_level, creature_state
    FROM creature_health
    WHERE creature_id = characterId;

    # Creature Hit Dice
    SELECT dice_size_id, remaining
    FROM creature_hit_dice
    WHERE creature_id = characterId;

    # Attribute Profs
    SELECT p.attribute_id, a.name, a.description, a.attribute_type_id, a.sid, a.user_id = characterUserId AS is_author, a.version,
           p.proficient, p.misc_modifier, p.advantage, p.disadvantage, p.double_prof, p.half_prof, p.round_up
    FROM creature_attribute_profs p
        JOIN attributes a ON p.attribute_id = a.id
    WHERE creature_id = characterId;

    # Item Profs
    SELECT p.item_id, i.name, i.description, i.item_type_id, i.sid, i.user_id = characterUserId AS is_author, i.version,
           p.misc_modifier, p.advantage, p.disadvantage, p.double_prof, p.half_prof, p.round_up,
           a.armor_type_id, w.weapon_type_id
    FROM creature_item_profs p
        JOIN items i ON p.item_id = i.id
        LEFT JOIN armors a ON a.item_id = i.id
        LEFT JOIN weapons w ON w.item_id = i.id
    WHERE creature_id = characterId;

    # Damage Modifiers
    SELECT damage_type_id, damage_modifier_type_id, `condition`, damageType.name AS damage_type_name,
           damageType.description AS damage_type_description, damageType.sid AS damage_type_sid,
           damageType.user_id = characterUserId AS damage_type_is_author, damageType.version AS damage_type_version
    FROM creature_damage_modifiers
        JOIN attributes damageType ON damageType.id = damage_type_id
    WHERE creature_id = characterId;

    # Condition Immunities
    SELECT a.id, a.name, a.sid, a.user_id = characterUserId AS is_author
    FROM creature_condition_immunities cci
        JOIN attributes a ON cci.condition_id = a.id
    WHERE cci.creature_id = characterId;

    # Senses
    SELECT sense_id, `range`
    FROM creature_senses
    WHERE creature_id = characterId;

    # Active Conditions
    CALL Creature_ActiveConditions(characterId, characterUserId);

    # Spell Tags
    SELECT id, power_type_id, title, color
    FROM creature_tags
    WHERE creature_id = characterId AND power_type_id = 1;

    # Feature Tags
    SELECT id, power_type_id, title, color
    FROM creature_tags
    WHERE creature_id = characterId AND power_type_id = 2;

    # Creature Spellcasting - Attack
    SELECT prof, double_prof, half_prof, round_up, misc_modifier, advantage, disadvantage, attack_type_id
    FROM creature_spellcasting
    WHERE creature_id = characterId AND attack_type_id = 1;

    # Creature Spellcasting - Save
    SELECT prof, double_prof, half_prof, round_up, misc_modifier, advantage, disadvantage, attack_type_id
    FROM creature_spellcasting
    WHERE creature_id = characterId AND attack_type_id = 2;

    # Spell Slots
    SELECT slot_level, max_modifier, remaining
    FROM creature_spell_slots
    WHERE creature_id = characterId;

    # Spell Configurations
    SELECT p.id, p.name, p.sid, p.user_id = characterUserId AS is_author,
           cs.level_gained, a.name AS level_name, a.sid AS level_sid, a.user_id = characterUserId AS level_is_author,
           cs.always_prepared,
           cs.counts_towards_prepared_limit, cs.notes, cs.user_id = characterUserId AS config_is_author
    FROM creature_spell_configurations cs
        JOIN spells s ON cs.spell_id = s.power_id
        JOIN powers p ON s.power_id = p.id
        LEFT JOIN attributes a ON cs.level_gained = a.id
    WHERE cs.creature_id = characterId;

    # Character Settings
    CALL Character_Settings_Get(characterId);

    # Ability Scores to Increase by One
    SELECT a.id, a.name, a.sid, a.user_id = characterUserId AS is_author
    FROM character_ability_scores_to_increase casi
        JOIN attributes a ON casi.ability_id = a.id
    WHERE casi.character_id = characterId;

    # Favorite Actions
    CALL CreatureActions_Get_Favorites(characterId);

    # Items
    CALL CreatureItems_Get(characterId, characterUserId);

    # Companions
    SELECT c2.id, c2.name, c2.sid, c2.user_id = characterUserId AS is_author, c.companion_type_id, c.max_hp,
        current_hp, temp_hp, max_hp_mod, num_death_saving_throw_successes, num_death_saving_throw_failures, death_save_mod, death_save_advantage, death_save_disadvantage, resurrection_penalty, exhaustion_level, creature_state
    FROM character_companions cc
        JOIN companions c ON c.creature_id = cc.companion_id
        JOIN creatures c2 ON c2.id = c.creature_id
        LEFT JOIN creature_health h ON c2.id = h.creature_id
    WHERE cc.character_id = characterId
    ORDER BY c2.name;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Creatures_Get_Companion` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Creatures_Get_Companion`(
    IN creatureId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    DECLARE companionId INT UNSIGNED;
    DECLARE companionUserId MEDIUMINT UNSIGNED;

    SET companionId = (SELECT id FROM creatures WHERE user_id = userID AND id = creatureId UNION SELECT creature_id FROM creatures_shared WHERE user_id = userId AND creature_id = creatureId);
    IF companionId IS NULL THEN
        SET companionId = (SELECT creature_id FROM creatures_public WHERE creature_id = creatureId);
    END IF;
    IF companionId IS NULL THEN
        SET companionId = (SELECT creature_id FROM creatures_private WHERE user_id = userId AND creature_id = creatureId);
    END IF;
    IF companionId IS NULL THEN
        SET companionId = (SELECT c.companion_id
                           FROM character_companions c
                                    JOIN campaign_characters cc ON cc.creature_id = c.character_id AND c.companion_id = creatureId
                                    JOIN campaigns c2 ON c2.id = cc.campaign_id AND c2.user_id = userId
                           LIMIT 1);
    END IF;

    SET companionUserId = (SELECT user_id FROM creatures WHERE id = companionId);

    SELECT c.id, c.name, ch.companion_type_id, ch.max_hp, ch.roll_over_damage, ch.ac_include_characters_prof,
           ch.ac_misc, ch.saving_throws_include_characters_prof, ch.saving_throws_misc,
           ch.skill_checks_include_characters_prof, ch.skill_checks_misc, ch.attack_include_characters_prof,
           ch.attack_misc, ch.damage_include_characters_prof, ch.damage_misc, ch.include_character_saves,
           ch.include_character_skills
    FROM creatures c
        JOIN companions ch ON ch.creature_id = c.id AND c.id = companionId;

    # Companion Score Modifiers
    SELECT ability_id, use_characters_score, include_characters_prof, misc
    FROM companion_score_modifiers
    WHERE companion_id = companionId;

    # Creature Health
    SELECT current_hp, temp_hp, max_hp_mod, num_death_saving_throw_successes, num_death_saving_throw_failures, death_save_mod, death_save_advantage, death_save_disadvantage, resurrection_penalty, exhaustion_level, creature_state
    FROM creature_health
    WHERE creature_id = companionId;

    # Monster
    SELECT m.id, m.name, m.alignment_id, m.ac, m.hit_dice_num_dice, m.hit_dice_size_id, m.hit_dice_misc_modifier, m.spellcasting_ability_id, m.challenge_rating_id, m.experience,
           m.hit_dice_ability_modifier_id, hitDice.name AS hit_dice_ability_modifier_name, hitDice.description AS hit_dice_ability_modifier_description, hitDice.sid AS hit_dice_ability_modifier_sid, hitDice.user_id = userId AS hit_dice_ability_modifier_is_author, hitDice.version AS hit_dice_ability_modifier_version, hitDice2.abbr AS hit_dice_ability_modifier_abbr,
           m.spellcaster_level_id, level.name AS spellcaster_level_name, level.sid AS spellcaster_level_sid, level.user_id = userId AS spellcaster_level_is_author,
           m.innate_spellcaster_level_id, level2.name AS innate_spellcaster_level_name, level2.sid AS innate_spellcaster_level_sid, level2.user_id = userId AS innate_spellcaster_level_is_author,
           p.attribute_id AS perception_prof, p2.attribute_id AS stealth_prof, m.legendary_points
    FROM monsters m
        JOIN companions c ON c.monster_id = m.id AND c.creature_id = companionId
        LEFT JOIN attributes hitDice ON hitDice.id = m.hit_dice_ability_modifier_id
        LEFT JOIN abilities hitDice2 ON hitDice2.attribute_id = hitDice.id
        LEFT JOIN attributes level ON level.id = m.spellcaster_level_id
        LEFT JOIN attributes level2 ON level2.id = m.innate_spellcaster_level_id
        LEFT JOIN monster_attribute_profs p ON p.monster_id = m.id AND p.attribute_id = 113 -- perception
        LEFT JOIN monster_attribute_profs p2 ON p2.monster_id = m.id AND p2.attribute_id = 118; -- stealth

    # Monster Ability Scores
    SELECT a.id, a.name, a.description, a.sid, a.user_id = userId AS is_author, a.version, ab.abbr, mas.value
    FROM monster_ability_scores mas
        JOIN companions c ON c.monster_id = mas.monster_id AND c.creature_id = companionId
        JOIN abilities ab ON ab.attribute_id = mas.ability_id
        JOIN attributes a ON a.id = ab.attribute_id;

    # Active Conditions
    CALL Creature_ActiveConditions(companionId, companionUserId);
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Creatures_Get_CompanionActions` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Creatures_Get_CompanionActions`(
    IN creatureId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    DECLARE companionId INT UNSIGNED;
    DECLARE monsterId INT UNSIGNED;
    DECLARE companionUserId MEDIUMINT UNSIGNED;

    SET companionId = (SELECT id FROM creatures WHERE user_id = userID AND id = creatureId UNION SELECT creature_id FROM creatures_shared WHERE user_id = userId AND creature_id = creatureId);
    IF companionId IS NULL THEN
        SET companionId = (SELECT c.companion_id
                           FROM character_companions c
                                    JOIN campaign_characters cc ON cc.creature_id = c.character_id AND c.companion_id = creatureId
                                    JOIN campaigns c2 ON c2.id = cc.campaign_id AND c2.user_id = userId
                           LIMIT 1);
    END IF;
    SET companionUserId = (SELECT user_id FROM creatures WHERE id = companionId);
    SET monsterId = (SELECT monster_id FROM companions WHERE creature_id = companionId);

    SELECT mps.id AS creature_power_id, mp.id AS action_id, mp.name AS action_name, mp.sid AS action_sid, mp.user_id = userId AS action_is_author,
           mps.active, mps.active_target_creature_id, mps.uses_remaining, ma.action_type_id, ma.legendary_cost
    FROM monster_powers mp
    JOIN monster_actions ma ON mp.id = ma.monster_power_id AND mp.monster_id = monsterId
    LEFT JOIN monster_power_states mps ON mps.creature_id = creatureId AND mps.monster_power_id = mp.id;

    CALL MonsterPowers_GetList_Actions(monsterId, companionUserId);
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Creatures_Get_CompanionFeatures` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Creatures_Get_CompanionFeatures`(
    IN creatureId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    DECLARE companionId INT UNSIGNED;
    DECLARE monsterId INT UNSIGNED;
    DECLARE companionUserId MEDIUMINT UNSIGNED;

    SET companionId = (SELECT id FROM creatures WHERE user_id = userID AND id = creatureId UNION SELECT creature_id FROM creatures_shared WHERE user_id = userId AND creature_id = creatureId);
    IF companionId IS NULL THEN
        SET companionId = (SELECT c.companion_id
                           FROM character_companions c
                                    JOIN campaign_characters cc ON cc.creature_id = c.character_id AND c.companion_id = creatureId
                                    JOIN campaigns c2 ON c2.id = cc.campaign_id AND c2.user_id = userId
                           LIMIT 1);
    END IF;
    SET companionUserId = (SELECT user_id FROM creatures WHERE id = companionId);
    SET monsterId = (SELECT monster_id FROM companions WHERE creature_id = companionId);

    SELECT mps.id AS creature_power_id, mp.id AS feature_id, mp.name AS feature_name, mp.sid AS feature_sid, mp.user_id = userId AS feature_is_author,
           mps.active, mps.active_target_creature_id, mps.uses_remaining
    FROM monster_powers mp
    JOIN monster_features mf ON mp.id = mf.monster_power_id AND mp.monster_id = monsterId
    LEFT JOIN monster_power_states mps ON mps.creature_id = creatureId AND mps.monster_power_id = mp.id;

    CALL MonsterPowers_GetList_Features(monsterId, companionUserId);
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Creatures_Get_CompanionSpells` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Creatures_Get_CompanionSpells`(
    IN creatureId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    DECLARE companionId INT UNSIGNED;
    DECLARE monsterId INT UNSIGNED;

    SET companionId = (SELECT id FROM creatures WHERE user_id = userID AND id = creatureId UNION SELECT creature_id FROM creatures_shared WHERE user_id = userId AND creature_id = creatureId);
    IF companionId IS NULL THEN
        SET companionId = (SELECT c.companion_id
                           FROM character_companions c
                                    JOIN campaign_characters cc ON cc.creature_id = c.character_id AND c.companion_id = creatureId
                                    JOIN campaigns c2 ON c2.id = cc.campaign_id AND c2.user_id = userId
                           LIMIT 1);
    END IF;
    SET monsterId = (SELECT monster_id FROM companions WHERE creature_id = companionId);

    # Spells
    SELECT cp.id AS creature_power_id, ms.spell_id AS power_id, p.name AS spell_name, p.sid AS spell_sid, p.user_id = userId AS spell_is_author,
           cp.assigned_characteristic_id, cs.prepared, cp.active,
           cp.active_target_creature_id, cs.concentrating, cs.active_level, cp.uses_remaining,
           s.level, p.recharge_on_short_rest, p.recharge_on_long_rest, p.extra_modifiers,
           p.modifiers_num_levels_above_base, p.modifier_advancement, s.casting_time_unit
    FROM monster_spells ms
        JOIN powers p ON ms.spell_id = p.id
        JOIN spells s ON s.power_id = p.id
        LEFT JOIN creature_powers cp ON cp.creature_id = companionId AND cp.power_id = ms.spell_id
        LEFT JOIN creature_spells cs ON cs.creature_power_id = cp.id
    WHERE ms.monster_id = monsterId
    ORDER BY p.name;

    # Innate Spells
    SELECT cp.id AS creature_power_id, ms.spell_id AS power_id, p.name AS spell_name, p.sid AS spell_sid, p.user_id = userId AS spell_is_author,
           cp.assigned_characteristic_id, cs.prepared, cp.active,
           cp.active_target_creature_id, cs.concentrating, ms.slot AS active_level, cp.uses_remaining,
           s.level, p.recharge_on_short_rest, p.recharge_on_long_rest, p.extra_modifiers,
           p.modifiers_num_levels_above_base, p.modifier_advancement, s.casting_time_unit,
           ms.limited_use_type_id, ms.quantity, ms.ability_modifier_id, ms.dice_size_id, ms.slot
    FROM monster_innate_spells ms
        JOIN powers p ON ms.spell_id = p.id
        JOIN spells s ON s.power_id = p.id
        LEFT JOIN creature_powers cp ON cp.creature_id = companionId AND cp.power_id = ms.spell_id
        LEFT JOIN creature_spells cs ON cs.creature_power_id = cp.id
    WHERE ms.monster_id = monsterId
    ORDER BY p.name;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
