/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Creatures_Get_CreatureFeatures` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Creatures_Get_CreatureFeatures`(
    IN creatureId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED,

    IN search VARCHAR(50),
    IN isActive BIT,
    IN isPassive BIT,
    IN isFeat BIT,
    IN characteristicTypeId TINYINT UNSIGNED,
    IN characteristicId INT UNSIGNED,
    IN includeChildren BIT,
    IN characterLevelId INT UNSIGNED,
    IN isRanged BIT,
    IN isAreaOfEffect BIT,
    IN areaOfEffectId INT UNSIGNED,
    IN tagArray VARCHAR(100),

    IN orderBy VARCHAR(100),
    IN orderByAscending BIT
)
BEGIN
    DECLARE characterId INT UNSIGNED;
    SET characterId = (SELECT id FROM creatures WHERE user_id = userID AND id = creatureId UNION SELECT creature_id FROM creatures_shared WHERE user_id = userId AND creature_id = creatureId);
    IF characterId IS NULL THEN
        SET characterId = (SELECT creature_id FROM creatures_private WHERE user_id = userId AND creature_id = creatureId);
    END IF;

    CREATE TEMPORARY TABLE IF NOT EXISTS temp_characteristics
    (
        id INT UNSIGNED NOT NULL
    );

    CREATE TEMPORARY TABLE IF NOT EXISTS temp_tags
    (
        id INT UNSIGNED NOT NULL
    );

    IF orderBy IS NULL THEN
        SET orderBy = 'name';
    END IF;

    IF orderByAscending IS NULL THEN
        SET orderByAscending = 1;
    END IF;

    IF characteristicId IS NOT NULL THEN
        INSERT INTO temp_characteristics (id) VALUES (characteristicId);

        INSERT INTO temp_characteristics (id)
        WITH RECURSIVE parents (parent_characteristic_id) AS
        (
            SELECT parent_characteristic_id
            FROM characteristics
            WHERE id = characteristicId

            UNION ALL

            SELECT c2.parent_characteristic_id
            FROM parents p
                JOIN characteristics AS c2 ON p.parent_characteristic_id = c2.id AND c2.parent_characteristic_id IS NOT NULL
        )
        SELECT parent_characteristic_id FROM parents WHERE parent_characteristic_id IS NOT NULl;

        IF includeChildren THEN
            INSERT INTO temp_characteristics (id)
            WITH RECURSIVE children (id) AS
            (
               SELECT id
               FROM characteristics
               WHERE parent_characteristic_id = characteristicId

               UNION ALL

               SELECT c2.id
               FROM children c
                        JOIN characteristics AS c2 ON c.id = c2.parent_characteristic_id
            )
            SELECT id FROM children;
        END IF;
    END IF;

    IF tagArray IS NOT NULL THEN
        SET @sql = CONCAT('INSERT INTO temp_tags (id) SELECT id FROM creature_tags WHERE id IN (', tagArray, ')');
        PREPARE stmt FROM @sql;
        EXECUTE stmt;
        DEALLOCATE PREPARE stmt;
    END IF;

    # Get All Powers
    SELECT cp.id AS creature_power_id, p.id AS feature_id, p.name AS feature_name, p.sid as feature_sid, p.user_id = userId AS feature_is_author,
           f.characteristic_type_id, c.id AS characteristic_id, c.name AS characteristic_name,
           c.sid AS characteristic_sid, c.user_id = userId AS characteristic_is_author,
           cp.active, cp.active_target_creature_id, cp.uses_remaining, f.passive,
           p.recharge_on_short_rest, p.recharge_on_long_rest, p.modifier_advancement, p.extra_modifiers,
           p.modifiers_num_levels_above_base, f.action_id
    FROM creature_powers cp
        JOIN features f ON f.power_id = cp.power_id
        JOIN powers p ON p.id = f.power_id
        LEFT JOIN characteristics c ON f.characteristic_id = c.id
    WHERE cp.creature_id = characterId
    ORDER BY
        (CASE WHEN orderBy = 'name' AND orderByAscending = 1 THEN p.name END),
        (CASE WHEN orderBy = 'name' AND orderByAscending = 0 THEN p.name END) DESC,
        (CASE WHEN orderBy = 'level' AND orderByAscending = 1 THEN f.character_level_id END),
        (CASE WHEN orderBy = 'level' AND orderByAscending = 0 THEN f.character_level_id END) DESC,
        (CASE WHEN orderBy = 'category' AND orderByAscending = 1 THEN c.name END),
        (CASE WHEN orderBy = 'category' AND orderByAscending = 0 THEN c.name END) DESC;

    # Get Filtered
    SELECT DISTINCT(cp.power_id)
    FROM creature_powers cp
        JOIN features f ON f.power_id = cp.power_id
        JOIN powers p ON p.id = f.power_id
        LEFT JOIN creature_power_tags tags ON tags.power_id = p.id
    WHERE cp.creature_id = characterId
        AND (search IS NULL OR search = '' OR search = '%%' OR p.name LIKE search)
        AND (isActive IS NULL OR cp.active = isActive)
        AND (isPassive IS NULL OR f.passive = isPassive)
        AND (isFeat IS NULL
                 OR (isFeat = 1 AND f.characteristic_type_id IS NULL)
                 OR (isFeat = 0 AND f.characteristic_type_id IS NOT NULL AND (
                     characteristicTypeId IS NULL OR (
                         f.characteristic_type_id = characteristicTypeId AND (
                             characteristicId IS NULL OR f.characteristic_id IN (SELECT id FROM temp_characteristics)
                            )
                         )
                     )
                 )
            )
        AND (characterLevelId IS NULL OR f.character_level_id = characterLevelId)
        AND (isRanged IS NULL
                 OR (isRanged = 1 AND p.range_type = 5)
                 OR (isRanged = 0 AND p.range_type != 5))
        AND (isAreaOfEffect IS NULL
                 OR (isAreaOfEffect = 1 AND p.area_of_effect_id IS NOT NULL AND (areaOfEffectId IS NULL OR p.area_of_effect_id = areaOfEffectId))
                 OR (isAreaOfEffect = 0 AND p.area_of_effect_id IS NULL))
        AND (tagArray IS NULL OR tags.creature_tag_id IN (SELECT id FROM temp_tags));

    # Tags
    SELECT p.power_id, t.id, t.power_type_id, t.title, t.color
    FROM creature_power_tags p
        JOIN creature_tags t ON p.creature_tag_id = t.id
    WHERE p.creature_id = characterId and p.power_id IN (SELECT power_id FROM creature_powers WHERE creature_id = characterId AND power_type_id = 2);

    # Limited Uses
    SELECT p.power_id, p.limited_use_type_id, p.level_id, a.name AS level_name, a.sid AS level_sid, a.user_id = userId AS level_is_author, p.quantity, p.ability_modifier_id, p.dice_size_id
    FROM power_limited_uses p
        LEFT JOIN attributes a ON p.level_id = a.id
    WHERE p.power_id IN (SELECT power_id FROM creature_powers WHERE creature_id = characterId AND power_type_id = 2);

    # Modifiers - Base
    SELECT power_id, modifier_category_id, modifier_sub_category_id, characteristic_dependant, attribute_id,
           a.name AS attribute_name, a.description AS attribute_description, a.attribute_type_id, a.sid as attribute_sid,
           a.user_id = userId AS attribute_is_author, a.version AS attribute_version,
           value, adjustment, proficient, half_proficient, round_up, advantage, disadvantage, extra, character_advancement,
           character_level_id, al.name AS character_level_name, al.sid AS character_level_sid, al.user_id = userId AS character_level_is_author,
           pm.use_level, pm.use_half_level, pm.ability_modifier_id, ab.name AS ability_modifier_name, ab.sid AS ability_modifier_sid, ab.user_id = userId AS ability_modifier_is_author
    FROM power_modifiers pm
        JOIN attributes a ON pm.attribute_id = a.id
        LEFT JOIN attributes al ON character_level_id = al.id
        LEFT JOIN attributes ab ON ability_modifier_id = ab.id
    WHERE power_id IN (SELECT power_id FROM creature_powers WHERE creature_id = characterId AND power_type_id = 2)
        AND character_advancement = 0
        AND extra = 0;

    # Modifiers - Advancement
    SELECT power_id, modifier_category_id, modifier_sub_category_id, characteristic_dependant, attribute_id,
           a.name AS attribute_name, a.description AS attribute_description, a.attribute_type_id, a.sid as attribute_sid,
           a.user_id = userId AS attribute_is_author, a.version AS attribute_version,
           value, adjustment, proficient, half_proficient, round_up, advantage, disadvantage, extra, character_advancement,
           character_level_id, al.name AS character_level_name, al.sid AS character_level_sid, al.user_id = userId AS character_level_is_author,
           pm.use_level, pm.use_half_level, pm.ability_modifier_id, ab.name AS ability_modifier_name, ab.sid AS ability_modifier_sid, ab.user_id = userId AS ability_modifier_is_author
    FROM power_modifiers pm
        JOIN attributes a ON pm.attribute_id = a.id
        LEFT JOIN attributes al ON character_level_id = al.id
        LEFT JOIN attributes ab ON ability_modifier_id = ab.id
    WHERE power_id IN (SELECT power_id FROM creature_powers WHERE creature_id = characterId AND power_type_id = 2)
        AND character_advancement = 1
        AND extra = 0;

    # Modifiers - Extra
    SELECT power_id, modifier_category_id, modifier_sub_category_id, characteristic_dependant, attribute_id,
           a.name AS attribute_name, a.description AS attribute_description, a.attribute_type_id, a.sid as attribute_sid,
           a.user_id = userId AS attribute_is_author, a.version AS attribute_version,
           value, adjustment, proficient, half_proficient, round_up, advantage, disadvantage, extra, character_advancement,
           character_level_id, al.name AS character_level_name, al.sid AS character_level_sid, al.user_id = userId AS character_level_is_author,
           pm.use_level, pm.use_half_level, pm.ability_modifier_id, ab.name AS ability_modifier_name, ab.sid AS ability_modifier_sid, ab.user_id = userId AS ability_modifier_is_author
    FROM power_modifiers pm
        JOIN attributes a ON pm.attribute_id = a.id
        LEFT JOIN attributes al ON character_level_id = al.id
        LEFT JOIN attributes ab ON ability_modifier_id = ab.id
    WHERE power_id IN (SELECT power_id FROM creature_powers WHERE creature_id = characterId AND power_type_id = 2)
        AND character_advancement = 0
        AND extra = 1;

    DROP TEMPORARY TABLE IF EXISTS temp_characteristics;
    DROP TEMPORARY TABLE IF EXISTS temp_tags;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Creatures_Get_CreatureSpells` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Creatures_Get_CreatureSpells`(
    IN creatureId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED,

    IN search VARCHAR(50),
    IN isActive BIT,
    IN spellSchoolId INT UNSIGNED,
    IN isRitual BIT,
    IN spellLevel TINYINT UNSIGNED,
    IN isVerbal BIT,
    IN isSomatic BIT,
    IN isMaterial BIT,
    IN isInstantaneous BIT,
    IN isConcentration BIT,
    IN isAreaOfEffect BIT,
    IN areaOfEffectId INT UNSIGNED,
    IN characteristicId INT UNSIGNED,
    IN tagArray VARCHAR(100),

    IN orderBy VARCHAR(100),
    IN orderByAscending BIT,
    IN innate BIT
)
BEGIN
    DECLARE characterId INT UNSIGNED;
    DECLARE characterUserId MEDIUMINT UNSIGNED;
    SET characterId = (SELECT id FROM creatures WHERE user_id = userID AND id = creatureId UNION SELECT creature_id FROM creatures_shared WHERE user_id = userId AND creature_id = creatureId);
    IF characterId IS NULL THEN
        SET characterId = (SELECT creature_id FROM creatures_private WHERE user_id = userId AND creature_id = creatureId);
    END IF;
    SET characterUserId = (SELECT user_id FROM creatures WHERE id = characterId);

    CREATE TEMPORARY TABLE IF NOT EXISTS temp_characteristics
    (
        id INT UNSIGNED NOT NULL
    );

    CREATE TEMPORARY TABLE IF NOT EXISTS temp_tags
    (
        id INT UNSIGNED NOT NULL
    );

    IF characteristicId IS NOT NULL THEN
        INSERT INTO temp_characteristics (id) VALUES (characteristicId);

        INSERT INTO temp_characteristics (id)
        WITH RECURSIVE parents (parent_characteristic_id) AS
        (
            SELECT parent_characteristic_id
            FROM characteristics c
            WHERE user_id = characterUserId AND id = characteristicId

            UNION ALL

            SELECT parent_characteristic_id
            FROM characteristics c
                JOIN characteristics_shared uc ON uc.user_id = characterUserId AND uc.characteristic_id = c.id AND c.id = characteristicId

            UNION ALL

            SELECT c2.parent_characteristic_id
            FROM parents p
                JOIN characteristics AS c2 ON p.parent_characteristic_id = c2.id AND c2.parent_characteristic_id IS NOT NULL
                JOIN characteristics uc2 ON uc2.user_id = characterUserId AND uc2.id = c2.id

            UNION ALL

            SELECT c2.parent_characteristic_id
            FROM parents p
                JOIN characteristics AS c2 ON p.parent_characteristic_id = c2.id AND c2.parent_characteristic_id IS NOT NULL
                JOIN characteristics_shared uc2 ON uc2.user_id = characterUserId AND uc2.characteristic_id = c2.id
        )
        SELECT parent_characteristic_id FROM parents WHERE parent_characteristic_id IS NOT NULl;
    END IF;

    IF tagArray IS NOT NULL THEN
        SET @sql = CONCAT('INSERT INTO temp_tags (id) SELECT id FROM creature_tags WHERE id IN (', tagArray, ')');
        PREPARE stmt FROM @sql;
        EXECUTE stmt;
        DEALLOCATE PREPARE stmt;
    END IF;

    IF orderBy IS NULL THEN
        SET orderBy = 'name';
    END IF;

    IF orderByAscending IS NULL THEN
        SET orderByAscending = 1;
    END IF;

    # Get All Powers
    SELECT cp.id AS creature_power_id, cp.power_id, p.name AS spell_name, p.sid AS spell_sid, p.user_id = userId AS spell_is_author,
           c.characteristic_type_id, cp.assigned_characteristic_id, cs.prepared, cp.active,
           cp.active_target_creature_id, cs.concentrating, cs.active_level, cp.uses_remaining,
           s.level,p.recharge_on_short_rest, p.recharge_on_long_rest, p.extra_modifiers,
           p.modifiers_num_levels_above_base, p.modifier_advancement, s.casting_time_unit,
           cs.innate, cs.innate_slot, cs.innate_max_uses
    FROM creature_spells cs
        JOIN creature_powers cp ON cs.creature_power_id = cp.id
        JOIN powers p ON cp.power_id = p.id
        JOIN spells s ON s.power_id = p.id
        LEFT JOIN characteristics c ON c.id = cp.assigned_characteristic_id
    WHERE cp.creature_id = characterId AND cs.innate = innate
    ORDER BY
        (CASE WHEN orderBy = 'name' AND orderByAscending = 1 THEN p.name END),
        (CASE WHEN orderBy = 'name' AND orderByAscending = 0 THEN p.name END) DESC,
        (CASE WHEN orderBy = 'level' AND orderByAscending = 1 THEN s.level END),
        (CASE WHEN orderBy = 'level' AND orderByAscending = 0 THEN s.level END) DESC;

    # Get Filtered
    SELECT DISTINCT(cp.power_id)
    FROM creature_powers cp
        JOIN creature_spells cs ON cs.creature_power_id = cp.id
        JOIN spells s ON s.power_id = cp.power_id
        JOIN powers p ON p.id = s.power_id
        LEFT JOIN characteristic_spell_configurations csc ON csc.spell_id = s.power_id
        LEFT JOIN characteristics c ON c.id = csc.characteristic_id
        LEFT JOIN creature_power_tags tags ON tags.power_id = p.id
    WHERE cp.creature_id = characterId
        AND cs.innate = innate
        AND (search IS NULL OR search = '' OR search = '%%' OR p.name LIKE search)
        AND (characteristicId IS NULL OR (csc.characteristic_id IN (SELECT id FROM temp_characteristics) AND (csc.user_id = characterUserId OR csc.user_id = c.user_id)))
        AND (isActive IS NULL OR cp.active = isActive)
        AND (spellSchoolId IS NULL OR s.spell_school_id = spellSchoolId)
        AND (isRitual IS NULL OR s.ritual = isRitual)
        AND (spellLevel IS NULL OR s.level = spellLevel)
        AND (isVerbal IS NULL OR s.verbal = isVerbal)
        AND (isSomatic IS NULL OR s.somatic = isSomatic)
        AND (isMaterial IS NULL OR s.material = isMaterial)
        AND (isInstantaneous IS NULL OR s.instantaneous = isInstantaneous)
        AND (isConcentration IS NULL OR s.concentration = isConcentration)
        AND (isAreaOfEffect IS NULL
                 OR (isAreaOfEffect = 1 AND p.area_of_effect_id IS NOT NULL AND (areaOfEffectId IS NULL OR p.area_of_effect_id = areaOfEffectId))
                 OR (isAreaOfEffect = 0 AND p.area_of_effect_id IS NULL))
        AND (tagArray IS NULL OR tags.creature_tag_id IN (SELECT id FROM temp_tags));

    # Tags
    SELECT p.power_id, t.id, t.power_type_id, t.title, t.color
    FROM creature_power_tags p
             JOIN creature_tags t ON p.creature_tag_id = t.id
    WHERE p.creature_id = characterId and p.power_id IN (SELECT power_id FROM creature_powers WHERE creature_id = characterId AND power_type_id = 1);

    # Modifiers - Base
    SELECT power_id, modifier_category_id, modifier_sub_category_id, characteristic_dependant, attribute_id,
           a.name AS attribute_name, a.description AS attribute_description, a.attribute_type_id, a.sid as attribute_sid,
           a.user_id = userId AS attribute_is_author, a.version AS attribute_version,
           value, adjustment, proficient, half_proficient, round_up, advantage, disadvantage, extra, character_advancement,
           character_level_id, al.name AS character_level_name, al.sid AS character_level_sid, al.user_id = userId AS character_level_is_author,
           pm.use_level, pm.use_half_level, pm.ability_modifier_id, ab.name AS ability_modifier_name, ab.sid AS ability_modifier_sid, ab.user_id = userId AS ability_modifier_is_author
    FROM power_modifiers pm
             JOIN attributes a ON pm.attribute_id = a.id
             LEFT JOIN attributes al ON character_level_id = al.id
             LEFT JOIN attributes ab ON ability_modifier_id = ab.id
    WHERE power_id IN (SELECT power_id FROM creature_powers WHERE creature_id = characterId AND power_type_id = 1)
        AND character_advancement = 0
        AND extra = 0;

    # Modifiers - Advancement
    SELECT power_id, modifier_category_id, modifier_sub_category_id, characteristic_dependant, attribute_id,
           a.name AS attribute_name, a.description AS attribute_description, a.attribute_type_id, a.sid as attribute_sid,
           a.user_id = userId AS attribute_is_author, a.version AS attribute_version,
           value, adjustment, proficient, half_proficient, round_up, advantage, disadvantage, extra, character_advancement,
           character_level_id, al.name AS character_level_name, al.sid AS character_level_sid, al.user_id = userId AS character_level_is_author,
           pm.use_level, pm.use_half_level, pm.ability_modifier_id, ab.name AS ability_modifier_name, ab.sid AS ability_modifier_sid, ab.user_id = userId AS ability_modifier_is_author
    FROM power_modifiers pm
             JOIN attributes a ON pm.attribute_id = a.id
             LEFT JOIN attributes al ON character_level_id = al.id
             LEFT JOIN attributes ab ON ability_modifier_id = ab.id
    WHERE power_id IN (SELECT power_id FROM creature_powers WHERE creature_id = characterId AND power_type_id = 1)
        AND character_advancement = 1
        AND extra = 0;

    # Modifiers - Extra
    SELECT power_id, modifier_category_id, modifier_sub_category_id, characteristic_dependant, attribute_id,
           a.name AS attribute_name, a.description AS attribute_description, a.attribute_type_id, a.sid as attribute_sid,
           a.user_id = userId AS attribute_is_author, a.version AS attribute_version,
           value, adjustment, proficient, half_proficient, round_up, advantage, disadvantage, extra, character_advancement,
           character_level_id, al.name AS character_level_name, al.sid AS character_level_sid, al.user_id = userId AS character_level_is_author,
           pm.use_level, pm.use_half_level, pm.ability_modifier_id, ab.name AS ability_modifier_name, ab.sid AS ability_modifier_sid, ab.user_id = userId AS ability_modifier_is_author
    FROM power_modifiers pm
             JOIN attributes a ON pm.attribute_id = a.id
             LEFT JOIN attributes al ON character_level_id = al.id
             LEFT JOIN attributes ab ON ability_modifier_id = ab.id
    WHERE power_id IN (SELECT power_id FROM creature_powers WHERE creature_id = characterId AND power_type_id = 1)
        AND character_advancement = 0
        AND extra = 1;

    DROP TEMPORARY TABLE IF EXISTS temp_characteristics;
    DROP TEMPORARY TABLE IF EXISTS temp_tags;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Creatures_Get_MissingFeatures` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Creatures_Get_MissingFeatures`(
    IN creatureId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED,

    IN search VARCHAR(50),
    IN isPassive BIT,
    IN isFeat BIT,
    IN characteristicTypeId TINYINT UNSIGNED,
    IN characteristicId INT UNSIGNED,
    IN includeChildren BIT,
    IN characterLevelId INT UNSIGNED,
    IN isRanged BIT,
    IN isAreaOfEffect BIT,
    IN areaOfEffectId INT UNSIGNED,
    IN tagArray VARCHAR(100),

    IN offset INT UNSIGNED,
    IN pageSize INT UNSIGNED
)
BEGIN
    DECLARE characterId INT UNSIGNED;
    SET characterId = (SELECT id FROM creatures WHERE user_id = userID AND id = creatureId UNION SELECT creature_id FROM creatures_shared WHERE user_id = userId AND creature_id = creatureId);

    CREATE TEMPORARY TABLE IF NOT EXISTS temp_characteristics
    (
        id INT UNSIGNED NOT NULL
    );

    CREATE TEMPORARY TABLE IF NOT EXISTS user_list
    (
        id INT UNSIGNED NOT NULL
    );

    CREATE TEMPORARY TABLE IF NOT EXISTS temp_features
    (
        id INT UNSIGNED NOT NULL
    );

    CREATE TEMPORARY TABLE IF NOT EXISTS temp_tags
    (
        id INT UNSIGNED NOT NULL
    );

    IF characteristicId IS NOT NULL THEN
        INSERT INTO temp_characteristics (id) VALUES (characteristicId);

        INSERT INTO temp_characteristics (id)
        WITH RECURSIVE parents (parent_characteristic_id) AS
                           (
                               SELECT parent_characteristic_id
                               FROM characteristics
                               WHERE id = characteristicId

                               UNION ALL

                               SELECT c2.parent_characteristic_id
                               FROM parents p
                                        JOIN characteristics AS c2 ON p.parent_characteristic_id = c2.id AND c2.parent_characteristic_id IS NOT NULL
                           )
        SELECT parent_characteristic_id FROM parents WHERE parent_characteristic_id IS NOT NULl;

        IF includeChildren THEN
            INSERT INTO temp_characteristics (id)
            WITH RECURSIVE children (id) AS
                               (
                                   SELECT id
                                   FROM characteristics
                                   WHERE parent_characteristic_id = characteristicId

                                   UNION ALL

                                   SELECT c2.id
                                   FROM children c
                                            JOIN characteristics AS c2 ON c.id = c2.parent_characteristic_id
                               )
            SELECT id FROM children;
        END IF;
    END IF;

    IF tagArray IS NOT NULL THEN
        SET @sql = CONCAT('INSERT INTO temp_tags (id) SELECT id FROM creature_tags WHERE id IN (', tagArray, ')');
        PREPARE stmt FROM @sql;
        EXECUTE stmt;
        DEALLOCATE PREPARE stmt;
    END IF;

    INSERT INTO user_list
    SELECT id FROM powers WHERE user_id = userId
    UNION
    SELECT power_id FROM powers_shared WHERE user_id = userId;

    INSERT INTO temp_features
    SELECT p.id
    FROM user_list up
             JOIN powers p ON up.id = p.id
             JOIN features f ON f.power_id = p.id
             LEFT JOIN creature_power_tags tags ON tags.power_id = p.id
    WHERE p.id NOT IN (SELECT power_id FROM creature_powers WHERE creature_id = characterId)
      AND (search IS NULL OR search = '' OR search = '%%' OR p.name LIKE search)
      AND (isPassive IS NULL OR f.passive = isPassive)
      AND (isFeat IS NULL
        OR (isFeat = 1 AND f.characteristic_type_id IS NULL)
        OR (isFeat = 0 AND f.characteristic_type_id IS NOT NULL AND (
                characteristicTypeId IS NULL OR (
                        f.characteristic_type_id = characteristicTypeId AND (
                        characteristicId IS NULL OR f.characteristic_id IN (SELECT id FROM temp_characteristics)
                    )
                )
            )
               )
        )
      AND (characterLevelId IS NULL OR f.character_level_id = characterLevelId)
      AND (isRanged IS NULL
        OR (isRanged = 1 AND p.range_type = 5)
        OR (isRanged = 0 AND p.range_type != 5))
      AND (isAreaOfEffect IS NULL
        OR (isAreaOfEffect = 1 AND p.area_of_effect_id IS NOT NULL AND (areaOfEffectId IS NULL OR p.area_of_effect_id = areaOfEffectId))
        OR (isAreaOfEffect = 0 AND p.area_of_effect_id IS NULL))
      AND (tagArray IS NULL OR tags.creature_tag_id IN (SELECT id FROM temp_tags))
    GROUP BY p.id, p.name
    ORDER BY p.name
    LIMIT offset, pageSize;

    # Features
    SELECT p.id AS feature_id, p.name AS feature_name, p.sid as feature_sid, p.user_id = userId AS feature_is_author,
           f.characteristic_type_id, c.id AS characteristic_id, c.name AS characteristic_name, c.sid AS characteristic_sid, c.user_id = userId AS characteristic_is_author, f.passive
    FROM temp_features tf
             JOIN powers p ON p.id = tf.id
             JOIN features f ON f.power_id = p.id
             LEFT JOIN characteristics c ON c.id = f.characteristic_id
    GROUP BY p.id;

    # Tags
    SELECT p.power_id, t.id, t.power_type_id, t.title, t.color
    FROM creature_power_tags p
             JOIN creature_tags t ON p.creature_tag_id = t.id
    WHERE p.creature_id = characterId and p.power_id IN (SELECT id FROM temp_features);

    DROP TEMPORARY TABLE IF EXISTS temp_characteristics;
    DROP TEMPORARY TABLE IF EXISTS temp_features;
    DROP TEMPORARY TABLE IF EXISTS user_list;
    DROP TEMPORARY TABLE IF EXISTS temp_tags;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Creatures_Get_MissingSpells` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Creatures_Get_MissingSpells`(
    IN creatureId INT UNSIGNED,
    IN assignedCharacteristicId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED,

    IN search VARCHAR(50),
    IN spellSchoolId INT UNSIGNED,
    IN isRitual BIT,
    IN spellLevel TINYINT UNSIGNED,
    IN isVerbal BIT,
    IN isSomatic BIT,
    IN isMaterial BIT,
    IN isInstantaneous BIT,
    IN isConcentration BIT,
    IN isAreaOfEffect BIT,
    IN areaOfEffectId INT UNSIGNED,
    IN characteristicId INT UNSIGNED,
    IN tagArray VARCHAR(100),

    IN offset INT UNSIGNED,
    IN pageSize INT UNSIGNED,
    IN powerInnate BIT
)
BEGIN
    DECLARE characterId INT UNSIGNED;
    SET characterId = (SELECT id FROM creatures WHERE user_id = userID AND id = creatureId UNION SELECT creature_id FROM creatures_shared WHERE user_id = userId AND creature_id = creatureId);

    CREATE TEMPORARY TABLE IF NOT EXISTS temp_characteristics
    (
        id INT UNSIGNED NOT NULL
    );

    CREATE TEMPORARY TABLE IF NOT EXISTS user_list
    (
        id INT UNSIGNED NOT NULL
    );

    CREATE TEMPORARY TABLE IF NOT EXISTS temp_spells
    (
        id INT UNSIGNED NOT NULL
    );

    CREATE TEMPORARY TABLE IF NOT EXISTS temp_tags
    (
        id INT UNSIGNED NOT NULL
    );

    IF characteristicId IS NOT NULL THEN
        INSERT INTO temp_characteristics (id) VALUES (characteristicId);

        INSERT INTO temp_characteristics (id)
        WITH RECURSIVE parents (parent_characteristic_id) AS
        (
            SELECT parent_characteristic_id
            FROM characteristics c
            WHERE user_id = userId AND id = characteristicId

            UNION ALL

            SELECT parent_characteristic_id
            FROM characteristics c
                JOIN characteristics_shared uc ON uc.user_id = userId AND uc.characteristic_id = c.id AND c.id = characteristicId

            UNION ALL

            SELECT c2.parent_characteristic_id
            FROM parents p
                JOIN characteristics AS c2 ON p.parent_characteristic_id = c2.id AND c2.parent_characteristic_id IS NOT NULL
                JOIN characteristics uc2 ON uc2.user_id = userId AND uc2.id = c2.id

            UNION ALL

            SELECT c2.parent_characteristic_id
            FROM parents p
                JOIN characteristics AS c2 ON p.parent_characteristic_id = c2.id AND c2.parent_characteristic_id IS NOT NULL
                JOIN characteristics_shared uc2 ON uc2.user_id = userId AND uc2.characteristic_id = c2.id
        )
        SELECT parent_characteristic_id FROM parents WHERE parent_characteristic_id IS NOT NULl;
    END IF;

    IF tagArray IS NOT NULL THEN
        SET @sql = CONCAT('INSERT INTO temp_tags (id) SELECT id FROM creature_tags WHERE id IN (', tagArray, ')');
        PREPARE stmt FROM @sql;
        EXECUTE stmt;
        DEALLOCATE PREPARE stmt;
    END IF;

    INSERT INTO user_list
    SELECT id FROM powers WHERE user_id = userId
    UNION
    SELECT power_id FROM powers_shared WHERE user_id = userId;

    INSERT INTO temp_spells
    SELECT p.id
    FROM user_list up
        JOIN powers p ON p.id = up.id
        JOIN spells s ON s.power_id = p.id
        LEFT JOIN characteristic_spell_configurations csc ON csc.spell_id = s.power_id
        LEFT JOIN characteristics c ON c.id = csc.characteristic_id
        LEFT JOIN creature_power_tags tags ON tags.power_id = p.id
    WHERE p.id NOT IN (
            SELECT cp.power_id
            FROM creature_spells cs
                JOIN creature_powers cp ON cs.creature_power_id = cp.id
            WHERE cp.creature_id = characterId
              AND (
                  (assignedCharacteristicId IS NULL && cp.assigned_characteristic_id IS NULL)
                      OR cp.assigned_characteristic_id = assignedCharacteristicId)
              AND cs.innate = powerInnate
        )
        AND (search IS NULL OR search = '' OR search = '%%' OR p.name LIKE search)
        AND (characteristicId IS NULL OR (csc.characteristic_id IN (SELECT id FROM temp_characteristics) AND (csc.user_id = userId OR csc.user_id = c.user_id)))
        AND (spellSchoolId IS NULL OR s.spell_school_id = spellSchoolId)
        AND (isRitual IS NULL OR s.ritual = isRitual)
        AND (spellLevel IS NULL OR s.level = spellLevel)
        AND (isVerbal IS NULL OR s.verbal = isVerbal)
        AND (isSomatic IS NULL OR s.somatic = isSomatic)
        AND (isMaterial IS NULL OR s.material = isMaterial)
        AND (isInstantaneous IS NULL OR s.instantaneous = isInstantaneous)
        AND (isConcentration IS NULL OR s.concentration = isConcentration)
        AND (isAreaOfEffect IS NULL
                 OR (isAreaOfEffect = 1 AND p.area_of_effect_id IS NOT NULL AND (areaOfEffectId IS NULL OR p.area_of_effect_id = areaOfEffectId))
                 OR (isAreaOfEffect = 0 AND p.area_of_effect_id IS NULL))
        AND (tagArray IS NULL OR tags.creature_tag_id IN (SELECT id FROM temp_tags))
    GROUP BY p.id, p.name
    ORDER BY p.name
    LIMIT offset, pageSize;

    # Spells
    SELECT p.id AS spell_id, p.name AS spell_name, p.sid AS spell_sid, p.user_id = userId AS spell_is_author, s.level AS spell_level
    FROM temp_spells ts
        JOIN powers p ON p.id = ts.id
        JOIN spells s ON s.power_id = p.id
        LEFT JOIN characteristic_spell_configurations csc ON csc.spell_id = s.power_id
    GROUP BY p.id;

    # Tags
    SELECT p.power_id, t.id, t.power_type_id, t.title, t.color
    FROM creature_power_tags p
        JOIN creature_tags t ON p.creature_tag_id = t.id
    WHERE p.creature_id = characterId and p.power_id IN (SELECT id FROM temp_spells);
    
    DROP TEMPORARY TABLE IF EXISTS temp_characteristics;
    DROP TEMPORARY TABLE IF EXISTS temp_spells;
    DROP TEMPORARY TABLE IF EXISTS user_list;
    DROP TEMPORARY TABLE IF EXISTS temp_tags;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Creatures_Get_Monster` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Creatures_Get_Monster`(
    IN creatureId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    DECLARE battleMonsterId INT UNSIGNED;
    DECLARE monsterUserId MEDIUMINT UNSIGNED;

    SET battleMonsterId = (SELECT id FROM creatures WHERE user_id = userID AND id = creatureId UNION SELECT creature_id FROM creatures_shared WHERE user_id = userId AND creature_id = creatureId);
    IF battleMonsterId IS NULL THEN
        SET battleMonsterId = (SELECT creature_id FROM creatures_public WHERE creature_id = creatureId);
    END IF;
    IF battleMonsterId IS NULL THEN
        SET battleMonsterId = (SELECT creature_id FROM creatures_private WHERE user_id = userId AND creature_id = creatureId);
    END IF;

    SET monsterUserId = (SELECT user_id FROM creatures WHERE id = battleMonsterId);

    SELECT c.id, c.user_id AS creature_user_id, c.name,
           bm.monster_id, bm.max_hp, c.spellcasting_ability_id, c.innate_spellcasting_ability_id,
           bm.legendary_points, m.legendary_points AS max_legendary_points
    FROM creatures c
        JOIN battle_monsters bm ON bm.creature_id = c.id AND c.id = battleMonsterId
        JOIN monsters m ON m.id = bm.monster_id;

    CALL Creatures_Get_StoredFilters(battleMonsterId);
    CALL Creatures_Get_StoredSorts(battleMonsterId);

    # Ability Scores
    SELECT a.id, a.name, a.description, a.sid, a.user_id = monsterUserId AS is_author, a.version, ab.abbr, cas.value, cas.misc_modifier, cas.asi_modifier
    FROM creature_ability_scores cas
        JOIN abilities ab ON ab.attribute_id = cas.ability_id
        JOIN attributes a ON a.id = ab.attribute_id
    WHERE cas.creature_id = battleMonsterId;

    # AC Abilities
    SELECT a.id, a.name, a.description, a.sid, a.user_id = monsterUserId AS is_author
    FROM creature_ac_abilities cas
        JOIN attributes a ON a.id = cas.ability_id
    WHERE cas.creature_id = battleMonsterId;

    # Wealth
    SELECT cost_unit_id, cu.name AS cost_unit_name, abbreviation AS cost_unit_abbreviation, conversion_unit AS conversion_unit_id, conversion_value, cu.weight AS cost_unit_weight, quantity, display, display_order
    FROM creature_wealth cw
        JOIN cost_units cu ON cw.cost_unit_id = cu.id
    WHERE creature_id = battleMonsterId
    ORDER BY display_order;

    # Creature Health
    SELECT current_hp, temp_hp, max_hp_mod, num_death_saving_throw_successes, num_death_saving_throw_failures, death_save_mod, death_save_advantage, death_save_disadvantage, resurrection_penalty, exhaustion_level, creature_state
    FROM creature_health
    WHERE creature_id = battleMonsterId;

    # Creature Hit Dice
#     SELECT dice_size_id, remaining
#     FROM creature_hit_dice
#     WHERE creature_id = battleMonsterId;

    # Attribute Profs
    SELECT p.attribute_id, a.name, a.description, a.attribute_type_id, a.sid, a.user_id = monsterUserId AS is_author, a.version,
           p.proficient, p.misc_modifier, p.advantage, p.disadvantage, p.double_prof, p.half_prof, p.round_up
    FROM creature_attribute_profs p
        JOIN attributes a ON p.attribute_id = a.id
    WHERE creature_id = battleMonsterId;

    # Item Profs
    SELECT p.item_id, i.name, i.description, i.item_type_id, i.sid, i.user_id = monsterUserId AS is_author, i.version,
           p.misc_modifier, p.advantage, p.disadvantage, p.double_prof, p.half_prof, p.round_up,
           a.armor_type_id, w.weapon_type_id
    FROM creature_item_profs p
        JOIN items i ON p.item_id = i.id
        LEFT JOIN armors a ON a.item_id = i.id
        LEFT JOIN weapons w ON w.item_id = i.id
    WHERE creature_id = battleMonsterId;

    # Damage Modifiers
    SELECT damage_type_id, damage_modifier_type_id, `condition`, damageType.name AS damage_type_name,
           damageType.description AS damage_type_description, damageType.sid AS damage_type_sid,
           damageType.user_id = monsterUserId AS damage_type_is_author, damageType.version AS damage_type_version
    FROM creature_damage_modifiers
        JOIN attributes damageType ON damageType.id = damage_type_id
    WHERE creature_id = battleMonsterId;

    # Condition Immunities
    SELECT a.id, a.name, a.sid, a.user_id = monsterUserId AS is_author
    FROM creature_condition_immunities cci
        JOIN attributes a ON cci.condition_id = a.id
    WHERE cci.creature_id = battleMonsterId;

    # Senses
#     SELECT sense_id, `range`
#     FROM creature_senses
#     WHERE creature_id = battleMonsterId;

    # Active Conditions
    CALL Creature_ActiveConditions(battleMonsterId, monsterUserId);

    # Spell Tags
#     SELECT id, power_type_id, title, color
#     FROM creature_tags
#     WHERE creature_id = monsterId AND power_type_id = 1;

    # Feature Tags
#     SELECT id, power_type_id, title, color
#     FROM creature_tags
#     WHERE creature_id = monsterId AND power_type_id = 2;

    # Creature Spellcasting - Attack
    SELECT prof, double_prof, half_prof, round_up, misc_modifier, advantage, disadvantage, attack_type_id
    FROM creature_spellcasting
    WHERE creature_id = battleMonsterId AND attack_type_id = 1 AND innate = 0;

    # Creature Spellcasting - Save
    SELECT prof, double_prof, half_prof, round_up, misc_modifier, advantage, disadvantage, attack_type_id
    FROM creature_spellcasting
    WHERE creature_id = battleMonsterId AND attack_type_id = 2 AND innate = 0;

    # Spell Slots
    SELECT slot_level, max_modifier, remaining
    FROM creature_spell_slots
    WHERE creature_id = battleMonsterId;

    # Spell Configurations
    SELECT p.id, p.name, p.sid, p.user_id = monsterUserId AS is_author,
           cs.level_gained, a.name AS level_name, a.sid AS level_sid, a.user_id = monsterUserId AS level_is_author,
           cs.always_prepared,
           cs.counts_towards_prepared_limit, cs.notes, cs.user_id = monsterUserId AS config_is_author
    FROM creature_spell_configurations cs
        JOIN spells s ON cs.spell_id = s.power_id
        JOIN powers p ON s.power_id = p.id
        LEFT JOIN attributes a ON cs.level_gained = a.id
    WHERE cs.creature_id = battleMonsterId;

    # Creature Spellcasting - Attack
    SELECT prof, double_prof, half_prof, round_up, misc_modifier, advantage, disadvantage, attack_type_id
    FROM creature_spellcasting
    WHERE creature_id = battleMonsterId AND attack_type_id = 1 AND innate = 1;

    # Creature Spellcasting - Save
    SELECT prof, double_prof, half_prof, round_up, misc_modifier, advantage, disadvantage, attack_type_id
    FROM creature_spellcasting
    WHERE creature_id = battleMonsterId AND attack_type_id = 2 AND innate = 1;

    # Items
    CALL CreatureItems_Get(battleMonsterId, monsterUserId);

    # BattleMonster Settings
    CALL BattleMonster_Settings_Get(battleMonsterId);
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Creatures_Get_StoredFilters` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Creatures_Get_StoredFilters`(
    IN creatureId INT UNSIGNED
)
BEGIN
    # Item Filters
    SELECT filter_key_id, filter_value
    FROM creature_stored_filters
    WHERE creature_id = creatureId AND filter_type_id = 1;

    # Spell Filters
    SELECT filter_key_id, filter_value
    FROM creature_stored_filters
    WHERE creature_id = creatureId AND filter_type_id = 2;

    # Feature Filters
    SELECT filter_key_id, filter_value
    FROM creature_stored_filters
    WHERE creature_id = creatureId AND filter_type_id = 3;

    # Skill Filters
    SELECT filter_key_id, filter_value
    FROM creature_stored_filters
    WHERE creature_id = creatureId AND filter_type_id = 4;

    # Note Filters
    SELECT filter_key_id, filter_value
    FROM creature_stored_filters
    WHERE creature_id = creatureId AND filter_type_id = 5;

    # Companion Filters
    SELECT filter_key_id, filter_value
    FROM creature_stored_filters
    WHERE creature_id = creatureId AND filter_type_id = 6;

    # Condition Filters
    SELECT filter_key_id, filter_value
    FROM creature_stored_filters
    WHERE creature_id = creatureId AND filter_type_id = 7;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Creatures_Get_StoredSorts` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Creatures_Get_StoredSorts`(
    IN creatureId INT UNSIGNED
)
BEGIN
    # Item Sorts
    SELECT sort_key_id, ascending
    FROM creature_stored_sorts
    WHERE creature_id = creatureId AND sort_type_id = 1;

    # Spell Sorts
    SELECT sort_key_id, ascending
    FROM creature_stored_sorts
    WHERE creature_id = creatureId AND sort_type_id = 2;

    # Feature Sorts
    SELECT sort_key_id, ascending
    FROM creature_stored_sorts
    WHERE creature_id = creatureId AND sort_type_id = 3;

    # Skill Sorts
    SELECT sort_key_id, ascending
    FROM creature_stored_sorts
    WHERE creature_id = creatureId AND sort_type_id = 4;

    # Note Sorts
    SELECT sort_key_id, ascending
    FROM creature_stored_sorts
    WHERE creature_id = creatureId AND sort_type_id = 5;

    # Companion Sorts
    SELECT sort_key_id, ascending
    FROM creature_stored_sorts
    WHERE creature_id = creatureId AND sort_type_id = 6;

    # Condition Sorts
    SELECT sort_key_id, ascending
    FROM creature_stored_sorts
    WHERE creature_id = creatureId AND sort_type_id = 7;
END ;;
DELIMITER ;
