CREATE DEFINER=`squire`@`%` PROCEDURE `Encounters_Create`(
    IN campaignId INT UNSIGNED,
    IN encounterName VARCHAR(50),
    IN encounterDescription VARCHAR(255),
    IN customSort BIT,
    IN hideKilled BIT,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    DECLARE valid BIT;
    DECLARE encounterId INT UNSIGNED;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        SELECT -1 AS id;
    END;

    START TRANSACTION;

    SET valid = (SELECT user_id FROM campaigns WHERE id = campaignId) = userId OR userId = 19; 			# OR userId = 19 edited by Mark

    IF valid THEN
        INSERT INTO encounters (campaign_id, name, description, user_id, custom_sort, hide_killed)
        VALUES (campaignId, encounterName, encounterDescription, userId, customSort, hideKilled);

        SET encounterId = (SELECT LAST_INSERT_ID());
    ELSE
        SET encounterId = -1;
    END IF;

    COMMIT;

    SELECT encounterId AS id;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Encounters_Delete` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Encounters_Delete`(
    IN encounterId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    DECLARE isOwner BIT;
    DECLARE battleCreatureId INT UNSIGNED;
    DECLARE more_rows BOOLEAN DEFAULT TRUE;
    DECLARE curs CURSOR FOR SELECT id
                            FROM temp_creatures ;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET more_rows = FALSE;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
        BEGIN
            ROLLBACK;
            SELECT -1 AS result;
        END;

    START TRANSACTION;

    CREATE TEMPORARY TABLE IF NOT EXISTS temp_creatures
    (
        id INT UNSIGNED NOT NULL
    );

    SET isOwner = (SELECT user_id = userId FROM encounters WHERE user_id in (0, userId) AND id = encounterId);

    IF isOwner THEN
        # delete encounter creatures
        INSERT INTO temp_creatures (id)
        SELECT id
        FROM encounter_creatures
        WHERE encounter_id = encounterId;

        OPEN curs;
        WHILE more_rows DO
                FETCH curs INTO battleCreatureId;
                IF more_rows THEN
                    CALL BattleCreatures_Delete(battleCreatureId, userId);
                END IF;
            END WHILE;
        CLOSE curs;

        DELETE m FROM encounter_monsters m JOIN encounter_monster_groups g ON g.id = m.encounter_monster_group_id JOIN encounters e ON e.id = g.encounter_id WHERE g.encounter_id = encounterId AND e.user_id = userId;
        DELETE g FROM encounter_monster_groups g JOIN encounters e ON e.id = g.encounter_id WHERE encounter_id = encounterId AND e.user_id = userId;
        DELETE c FROM encounter_characters c JOIN encounter_creatures ec ON ec.id = c.encounter_creature_id JOIN encounters e ON e.id = ec.encounter_id WHERE encounter_id = encounterId AND e.user_id = userId;
        DELETE ec FROM encounter_creatures ec JOIN encounters e ON e.id = ec.encounter_id WHERE encounter_id = encounterId AND e.user_id = userId;
        DELETE FROM encounters WHERE user_id = userId AND id = encounterId;
    END IF;

    COMMIT;

    DROP TEMPORARY TABLE IF EXISTS temp_creatures;
    SELECT 1 AS result;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Encounters_Delete_BattleCreatures` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Encounters_Delete_BattleCreatures`(
    IN encounterId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    DECLARE isOwner BIT;
    DECLARE encounterCreatureId INT UNSIGNED;
    DECLARE more_rows BOOLEAN DEFAULT TRUE;
    DECLARE curs CURSOR FOR SELECT id
                            FROM temp_creatures ;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET more_rows = FALSE;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
        BEGIN
            ROLLBACK;
            SELECT -1 AS result;
        END;

    START TRANSACTION;

    CREATE TEMPORARY TABLE IF NOT EXISTS temp_creatures
    (
        id INT UNSIGNED NOT NULL
    );

    SET isOwner = (SELECT user_id = userId FROM encounters WHERE user_id in (0, userId) AND id = encounterId);

    IF isOwner THEN
        # delete encounter creatures
        INSERT INTO temp_creatures (id)
        SELECT id
        FROM encounter_creatures
        WHERE encounter_id = encounterId;

        OPEN curs;
        WHILE more_rows DO
                FETCH curs INTO encounterCreatureId;
                IF more_rows THEN
                    CALL BattleCreatures_Delete(encounterCreatureId, userId);
                END IF;
            END WHILE;
        CLOSE curs;
    END IF;

    COMMIT;

    DROP TEMPORARY TABLE IF EXISTS temp_creatures;
    SELECT 1 AS result;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Encounters_Get` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Encounters_Get`(
    IN encounterId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    DECLARE validatedId INT UNSIGNED;
    SET validatedId = (SELECT id FROM encounters WHERE user_id = userId AND id = encounterId);

    SELECT id, campaign_id, name, description, current_round, current_turn, exp_earned, custom_sort,
           started_at, last_played_at, finished_at, hide_killed
    FROM encounters
    WHERE user_id = userId AND id = validatedId;

    # Encounter Characters
    CALL EncountersCreatures_GetList_Characters (validatedId);

    # Encounter Monster Groups
    CALL EncountersCreatures_GetList_MonsterGroups (validatedId, userId);
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Encounters_GetList` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Encounters_GetList`(
    IN campaignId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    DECLARE validatedId INT UNSIGNED;

    SET validatedId = (SELECT id FROM campaigns WHERE user_id = userId AND id = campaignId);

    SELECT id, name, description, started_at, last_played_at, finished_at
    FROM encounters
    WHERE campaign_id = validatedId AND user_id = userId
    ORDER BY last_played_at desc, name;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Encounters_Get_BattleCreatures` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Encounters_Get_BattleCreatures`(
    IN encounterId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    DECLARE isOwner BIT;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
        BEGIN
            ROLLBACK;
            SELECT -1 AS result;
        END;

    SET isOwner = (SELECT user_id = userId FROM encounters WHERE user_id in (0, userId) AND id = encounterId);

    IF isOwner THEN
        SELECT ec.id, ec.creature_id, c.name, ec.encounter_creature_type_id, m.monster_number, ec.initiative, ec.round_added,
               ec.speed_to_display, ec.action_readied, ec.surprised, ec.removed,
               g.id AS group_id, g.grouped_initiative
        FROM encounter_creatures ec
            JOIN creatures c ON c.id = ec.creature_id
            LEFT JOIN encounter_monsters m ON m.encounter_creature_id = ec.id
            LEFT JOIN encounter_monster_groups g ON g.id = m.encounter_monster_group_id
        WHERE ec.encounter_id = encounterId
        ORDER BY ec.`order`, m.monster_number;
        
        SELECT ec.id AS encounter_creature_id, ecc.id AS encounter_creature_condition_id, condition_id, c.name AS condition_name, c.sid AS condition_sid,
               ecc.name, ends_on_save, save_dc, s.id AS save_type_id, s.name AS save_type_name, s.sid AS save_type_sid,
               ends_on_rounds_count, num_rounds, round_started,
               ends_on_target_turn, target_encounter_creature_id, target_creature_turn_phase_id,
               on_going_damage
        FROM encounter_creature_conditions ecc
            JOIN encounter_creatures ec ON ec.id = ecc.encounter_creature_id
            LEFT JOIN attributes c ON c.id = ecc.condition_id
            LEFT JOIN attributes s ON s.id = ecc.save_type
        WHERE ec.encounter_id = encounterId;
        
        SELECT ec.id AS encounter_creature_id, ecc.id AS encounter_creature_condition_id, num_dice, dice_size_id, misc_modifier,
               ability_modifier_id, abilityModifier.name AS ability_modifier_name, abilityModifier.sid AS ability_modifier_sid,
               damage_type_id, dt.name AS damage_type_name, dt.sid AS damage_type_sid
        FROM encounter_creatures ec
            JOIN encounter_creature_conditions ecc ON ecc.encounter_creature_id = ec.id
            JOIN encounter_creature_condition_damages d ON d.encounter_creature_condition_id = ecc.id
            LEFT JOIN attributes abilityModifier ON abilityModifier.id = d.ability_modifier_id
            LEFT JOIN attributes dt ON dt.id = d.damage_type_id
        WHERE ec.encounter_id = encounterId;

    END IF;
END ;;
DELIMITER ;
