CREATE DEFINER=`squire`@`%` PROCEDURE `Encounters_Start`(
    IN encounterId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED,
    IN startedAt TIMESTAMP
)
BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        SELECT 0 AS valid_request;
    END;

    START TRANSACTION;

    UPDATE encounters SET started_at = startedAt, last_played_at = startedAt, finished_at = NULL, current_round = 1, current_turn = 1 WHERE id = encounterId AND user_id = userId;
    UPDATE encounter_creatures SET removed = 0 WHERE encounter_id = encounterId;

    COMMIT;

    SELECT 1 AS valid_request;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Encounters_Update` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Encounters_Update`(
    IN encounterId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED,
    IN encounterName VARCHAR(50),
    IN encounterDescription VARCHAR(255),
    IN customSort BIT,
    IN hideKilled BIT
)
BEGIN
    DECLARE valid BIT;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        SELECT 0 AS valid_request;
    END;

    START TRANSACTION;

    SET valid = (SELECT user_id FROM encounters WHERE id = encounterId) = userId OR userId = 19; 			# OR userId = 19 edited by Mark

    IF valid THEN
        UPDATE encounters
        SET name = encounterName, description = encounterDescription, custom_sort = customSort, hide_killed = hideKilled
        WHERE id = encounterId;
    END IF;

    COMMIT;

    SELECT valid AS valid_request;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
