    DECLARE EXIT HANDLER FOR SQLEXCEPTION
        BEGIN
            ROLLBACK;
            SELECT -1 AS result;
        END;

    START TRANSACTION;

    SELECT id, user_id = userId
    INTO toolId, isOwner
    FROM items
    WHERE user_id IN (0, userId) AND id = itemId;

    IF toolId IS NOT NULL THEN
        CALL Items_Delete_Common(toolId, userId);

        IF isOwner THEN
            DELETE FROM items_public WHERE item_id = itemId;
            DELETE FROM items_private WHERE item_id = itemId;
            UPDATE items SET published_parent_id = NULL, published_parent_version = NULL WHERE published_parent_id = itemId;

            DELETE t FROM tools t JOIN items i ON i.id = t.item_id WHERE item_id = toolId AND i.user_id = userId;
            DELETE FROM items WHERE user_id = userId AND id = toolId;
        ELSE
            DELETE FROM items_shared WHERE user_id = userId AND item_id = toolId;
