CREATE DEFINER=`squire`@`%` PROCEDURE `Items_Get_VersionInfo`(
    IN itemId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    DECLARE userItemId INT UNSIGNED;
    DECLARE parentItemId INT UNSIGNED;
    DECLARE publishedItemId INT UNSIGNED;
    DECLARE currentVersion SMALLINT UNSIGNED;
    DECLARE authorVersion SMALLINT UNSIGNED;

    SET userItemId = (SELECT id FROM items WHERE user_id = userID AND id = itemId UNION SELECT item_id FROM items_shared WHERE user_id = userId AND item_id = itemId);

    IF userItemId IS NOT NULL THEN
        SET parentItemId = (SELECT published_parent_id FROM items WHERE id = userItemId);
        SET publishedItemId = (SELECT item_id FROM items_public WHERE item_id = parentItemId);
        IF publishedItemId IS NULL THEN
            SET publishedItemId = (SELECT item_id FROM items_private WHERE user_id = userId AND item_id = parentItemId);
        END IF;

        SELECT i2.version, i1.published_parent_version
        INTO authorVersion, currentVersion
        FROM items i1
                 LEFT JOIN items i2 ON i1.published_parent_id = i2.id AND i1.id = userItemId AND i2.id = publishedItemId
        WHERE i2.version IS NOT NULL;
    ELSE
        SET userItemId = (SELECT id FROM items WHERE published_parent_id = itemId AND user_id = userId);
        IF userItemId IS NOT NULL THEN
            SELECT i2.version, i1.published_parent_version
            INTO authorVersion, currentVersion
            FROM items i1
                     LEFT JOIN items i2 ON i1.published_parent_id = i2.id AND i1.id = userItemId
            WHERE i2.version IS NOT NULL;
        ELSE
            SET userItemId = (SELECT item_id FROM items_public WHERE item_id = itemId);
            IF userItemId IS NULL THEN
                SET userItemId = (SELECT item_id FROM items_private WHERE user_id = userId AND item_id = itemId);
            END IF;

            IF userItemId IS NOT NULL THEN
                SELECT version, 0
                INTO authorVersion, currentVersion
                FROM items WHERE id = userItemId;
            END IF;
        END IF;
    END IF;

    SELECT currentVersion AS version, authorVersion AS author_version;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Items_Get_Weapon` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Items_Get_Weapon`(
    IN itemId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    DECLARE weaponId INT UNSIGNED;

    SET weaponId = (SELECT id FROM items WHERE user_id = userID AND id = itemId UNION SELECT item_id FROM items_shared WHERE user_id = userId AND item_id = itemId);
    IF weaponId IS NULL THEN
        SET weaponId = (SELECT item_id FROM items_public WHERE item_id = itemId);
    END IF;
    IF weaponId IS NULL THEN
        SET weaponId = (SELECT item_id FROM items_private WHERE user_id = userId AND item_id = itemId);
    END IF;
    IF weaponId IS NULL THEN
        SET weaponId = (SELECT ci.item_id
                        FROM creature_items ci
                                 JOIN creatures c ON c.id = ci.creature_id AND ci.item_id = itemId
                                 JOIN campaign_characters cc ON cc.creature_id = c.id
                                 JOIN campaigns c2 ON c2.id = cc.campaign_id AND c2.user_id = userId
                        LIMIT 1);
    END IF;

    SELECT i.id, i.name, i.description, i.sid, i.expendable, i.container, i.ignore_weight,
           i.cost, i.cost_unit AS cost_unit_id, cu.name AS cost_unit_name, cu.abbreviation AS cost_unit_abbreviation,
           cu.conversion_unit AS conversion_unit_id, cu.conversion_value, cu.weight AS cost_unit_weight, i.weight,
           w.weapon_type_id, wt.name AS weapon_type_name, wt.description AS weapon_type_description, wt.sid AS weapon_type_sid, wt.user_id = userId AS weapon_type_is_author, wt.version AS weapon_type_version,
           w.weapon_range_type, w.normal_range, w.long_range, w.attack_mod, w.ammo_id,
           ai.name AS ammo_name, ai.description AS ammo_description, ai.sid AS ammo_sid, ai.user_id = userId AS ammo_is_author,
           i.user_id = userId AS is_author, i.version
    FROM items i
        JOIN weapons w ON w.item_id = i.id AND i.id = weaponId
        JOIN cost_units cu on i.cost_unit = cu.id
        LEFT JOIN items ai ON w.ammo_id = ai.id
        JOIN attributes wt ON wt.id = w.weapon_type_id;

    IF weaponId IS NOT NULL THEN
        # weapon properties
        SELECT wwp.weapon_property_id, a.name AS weapon_property_name, a.description as weapon_property_description, a.sid as weapon_property_sid,
               a.user_id = userId AS weapon_property_is_author, a.version AS weapon_property_version
        FROM weapon_weapon_properties wwp
            JOIN weapon_properties wp ON wwp.weapon_property_id = wp.attribute_id
            JOIN attributes a ON wp.attribute_id = a.id
        WHERE wwp.weapon_id = weaponId;

        # non-versatile damages
        SELECT num_dice, dice_size, misc_mod, versatile,
               ability_modifier_id, a.name AS ability_name, a.description AS ability_description, a.sid AS ability_sid, ab.abbr,
               a.user_id = userId AS ability_is_author, a.version AS ability_version,
               damage_type_id, dt.name AS damage_type_name, dt.description AS damage_type_description, dt.sid AS damage_type_sid,
               dt.user_id = userId AS damage_type_is_author, dt.version AS damage_type_version
        FROM items i
            JOIN item_damages d ON d.item_id = i.id AND i.id = weaponId AND d.versatile = 0
            LEFT JOIN attributes a ON a.id = d.ability_modifier_id
            LEFT JOIN abilities ab ON ab.attribute_id = a.id
            LEFT JOIN attributes dt ON dt.id = d.damage_type_id;

        # versatile damages
        SELECT num_dice, dice_size, misc_mod, versatile,
               ability_modifier_id, a.name AS ability_name, a.description AS ability_description, a.sid AS ability_sid, ab.abbr,
               a.user_id = userId AS ability_is_author, a.version AS ability_version,
               damage_type_id, dt.name AS damage_type_name, dt.description AS damage_type_description, dt.sid AS damage_type_sid,
               dt.user_id = userId AS damage_type_is_author, dt.version AS damage_type_version
        FROM items i
            JOIN item_damages d ON d.item_id = i.id AND i.id = weaponId AND d.versatile = 1
            LEFT JOIN attributes a ON a.id = d.ability_modifier_id
            LEFT JOIN abilities ab ON ab.attribute_id = a.id
            LEFT JOIN attributes dt ON dt.id = d.damage_type_id;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Items_InUse` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Items_InUse`(
    IN itemId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    CREATE TEMPORARY TABLE IF NOT EXISTS temp_attributes
    (
        id INT UNSIGNED NOT NULL,
        required BIT
    );

    CREATE TEMPORARY TABLE IF NOT EXISTS temp_characteristics
    (
        id INT UNSIGNED NOT NULL,
        required BIT
    );

    CREATE TEMPORARY TABLE IF NOT EXISTS temp_items
    (
        id INT UNSIGNED NOT NULL,
        required BIT
    );

    CREATE TEMPORARY TABLE IF NOT EXISTS temp_creatures
    (
        id INT UNSIGNED NOT NULL,
        required BIT
    );

    CREATE TEMPORARY TABLE IF NOT EXISTS temp_monsters
    (
        id INT UNSIGNED NOT NULL,
        required BIT
    );

    INSERT INTO temp_items
    SELECT w.item_id, 1
    FROM weapons w
        JOIN items ui ON ui.user_id = userId AND ui.id = w.item_id
    WHERE ammo_id = itemId;

    INSERT INTO temp_items
    SELECT w.item_id, 1
    FROM weapons w
        JOIN items_shared ui ON ui.user_id = userId AND ui.item_id = w.item_id
    WHERE ammo_id = itemId;

    INSERT INTO temp_items
    SELECT p.item_id, 0
    FROM packs p
        JOIN items ui ON ui.user_id = userId AND ui.id = p.item_id
        JOIN pack_items pi ON p.item_id = pi.pack_id
    WHERE pi.item_id = itemId OR pi.sub_item_id = itemId;

    INSERT INTO temp_items
    SELECT p.item_id, 0
    FROM packs p
        JOIN items_shared ui ON ui.user_id = userId AND ui.item_id = p.item_id
        JOIN pack_items pi ON p.item_id = pi.pack_id
    WHERE pi.item_id = itemId OR pi.sub_item_id = itemId;

    INSERT INTO temp_characteristics
    SELECT cip.characteristic_id, 0
    FROM characteristic_item_profs cip
        JOIN characteristics uc ON uc.user_id = userId AND uc.id = cip.characteristic_id
    WHERE item_id = itemId;

    INSERT INTO temp_characteristics
    SELECT cip.characteristic_id, 0
    FROM characteristic_item_profs cip
        JOIN characteristics_shared uc ON uc.user_id = userId AND uc.characteristic_id = cip.characteristic_id
    WHERE item_id = itemId;

    INSERT INTO temp_characteristics
    SELECT cse.characteristic_id, 0
    FROM characteristic_starting_equipments cse
        JOIN characteristics uc ON uc.user_id = userId AND uc.id = cse.characteristic_id
    WHERE item_id = itemId;

    INSERT INTO temp_characteristics
    SELECT cse.characteristic_id, 0
    FROM characteristic_starting_equipments cse
        JOIN characteristics_shared uc ON uc.user_id = userId AND uc.characteristic_id = cse.characteristic_id
    WHERE item_id = itemId;

    INSERT INTO temp_characteristics
    SELECT csip.class_id, 0
    FROM class_secondary_item_profs csip
        JOIN characteristics uc ON uc.user_id = userId AND uc.id = csip.class_id
    WHERE item_id = itemId;

    INSERT INTO temp_characteristics
    SELECT csip.class_id, 0
    FROM class_secondary_item_profs csip
        JOIN characteristics_shared uc ON uc.user_id = userId AND uc.characteristic_id = csip.class_id
    WHERE item_id = itemId;

    INSERT INTO temp_creatures
    SELECT cip.creature_id, 0
    FROM creature_item_profs cip
        JOIN creatures uc ON uc.user_id = userId AND uc.id = cip.creature_id
    WHERE item_id = itemId;

    INSERT INTO temp_creatures
    SELECT cip.creature_id, 0
    FROM creature_item_profs cip
        JOIN creatures_shared uc ON uc.user_id = userId AND uc.creature_id = cip.creature_id
    WHERE item_id = itemId;

    INSERT INTO temp_monsters
    SELECT mip.monster_id, 0
    FROM monster_item_profs mip
        JOIN monsters uc ON uc.user_id = userId AND uc.id = mip.monster_id
    WHERE item_id = itemId;

    INSERT INTO temp_monsters
    SELECT mip.monster_id, 0
    FROM monster_item_profs mip
        JOIN monsters_shared uc ON uc.user_id = userId AND uc.monster_id = mip.monster_id
    WHERE item_id = itemId;

    INSERT INTO temp_monsters
    SELECT mi.monster_id, 0
    FROM monster_items mi
        JOIN monsters uc ON uc.user_id = userId AND uc.id = mi.monster_id
    WHERE item_id = itemId;

    INSERT INTO temp_monsters
    SELECT mi.monster_id, 0
    FROM monster_items mi
        JOIN monsters_shared uc ON uc.user_id = userId AND uc.monster_id = mi.monster_id
    WHERE item_id = itemId;

    INSERT INTO temp_monsters
    SELECT mi.monster_id, 0
    FROM monster_items mi
        JOIN monsters uc ON uc.user_id = userId AND uc.id = mi.monster_id
    WHERE sub_item_id = itemId;

    INSERT INTO temp_monsters
    SELECT mi.monster_id, 0
    FROM monster_items mi
        JOIN monsters_shared uc ON uc.user_id = userId AND uc.monster_id = mi.monster_id
    WHERE sub_item_id = itemId;

    INSERT INTO temp_creatures
    SELECT ca.creature_id, 0
    FROM creature_action_items cai
        JOIN creature_actions ca ON ca.id = cai.creature_action_id
        JOIN creatures uc ON uc.user_id = userId AND uc.id = ca.creature_id
    WHERE cai.item_id = itemId;

    INSERT INTO temp_creatures
    SELECT ca.creature_id, 0
    FROM creature_action_items cai
        JOIN creature_actions ca ON ca.id = cai.creature_action_id
        JOIN creatures_shared uc ON uc.user_id = userId AND uc.creature_id = ca.creature_id
    WHERE cai.item_id = itemId;

    INSERT INTO temp_creatures
    SELECT ca.creature_id, 0
    FROM creature_action_items cai
        JOIN creature_actions ca ON ca.id = cai.creature_action_id
        JOIN creatures uc ON uc.user_id = userId AND uc.id = ca.creature_id
    WHERE cai.sub_item_id = itemId;

    INSERT INTO temp_creatures
    SELECT ca.creature_id, 0
    FROM creature_action_items cai
        JOIN creature_actions ca ON ca.id = cai.creature_action_id
        JOIN creatures_shared uc ON uc.user_id = userId AND uc.creature_id = ca.creature_id
    WHERE cai.sub_item_id = itemId;

    INSERT INTO temp_creatures
    SELECT ci.creature_id, 0
    FROM creature_items ci
        JOIN creatures uc ON uc.user_id = userId AND uc.id = ci.creature_id
    WHERE ci.item_id = itemId;

    INSERT INTO temp_creatures
    SELECT ci.creature_id, 0
    FROM creature_items ci
        JOIN creatures_shared uc ON uc.user_id = userId AND uc.creature_id = ci.creature_id
    WHERE ci.item_id = itemId;

    INSERT INTO temp_creatures
    SELECT ci.creature_id, 0
    FROM creature_items ci
        JOIN creatures uc ON uc.user_id = userId AND uc.id = ci.creature_id
    WHERE ci.magic_item_type_id = itemId;

    INSERT INTO temp_creatures
    SELECT ci.creature_id, 0
    FROM creature_items ci
        JOIN creatures_shared uc ON uc.user_id = userId AND uc.creature_id = ci.creature_id
    WHERE ci.magic_item_type_id = itemId;

    INSERT INTO temp_creatures
    SELECT mp.monster_id, 0
    FROM monster_actions ma
        JOIN monster_powers mp ON mp.id = ma.monster_power_id
        JOIN creatures_shared uc ON uc.user_id = userId AND uc.creature_id = mp.monster_id
    WHERE ma.ammo_id = itemId;

    INSERT INTO temp_items
    SELECT pi.pack_id, 0
    FROM pack_items pi
        JOIN items ui ON ui.user_id = userId AND ui.id = pi.pack_id
    WHERE pi.item_id = itemId;

    INSERT INTO temp_items
    SELECT pi.pack_id, 0
    FROM pack_items pi
        JOIN items_shared ui ON ui.user_id = userId AND ui.item_id = pi.pack_id
    WHERE pi.item_id = itemId;

    # Get Values
    SELECT * FROM (
        SELECT 1 AS type_id, c.creature_type_id AS sub_type_id, c.id, c.name, t.required
        FROM (SELECT id, MAX(required) AS required FROM temp_creatures GROUP BY id) AS t
            JOIN creatures c ON t.id = c.id

        UNION

        SELECT 2 AS type_id, c.characteristic_type_id AS sub_type_id, c.id, c.name, t.required
        FROM (SELECT id, MAX(required) AS required FROM temp_characteristics GROUP BY id) AS t
            JOIN characteristics c ON t.id = c.id

        UNION

        SELECT 4 AS type_id, i.item_type_id AS sub_type_id, i.id, i.name, t.required
        FROM (SELECT id, MAX(required) AS required FROM temp_items GROUP BY id) AS t
            JOIN items i ON t.id = i.id

        UNION

        SELECT 5 AS type_id, null AS sub_type_id, m.id, m.name, t.required
        FROM (SELECT id, MAX(required) AS required FROM temp_monsters GROUP BY id) AS t
                 JOIN monsters m ON t.id = m.id
    ) AS a
    ORDER BY type_id, sub_type_id, name;

    DROP TEMPORARY TABLE IF EXISTS temp_characteristics;
    DROP TEMPORARY TABLE IF EXISTS temp_items;
    DROP TEMPORARY TABLE IF EXISTS temp_creatures;
    DROP TEMPORARY TABLE IF EXISTS temp_monsters;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Items_Share_Private` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
