/*!50003 DROP PROCEDURE IF EXISTS `MonsterPowers_GetVersionInfo` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `MonsterPowers_GetVersionInfo`(
    IN monsterPowerId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    DECLARE userPowerId INT UNSIGNED;
    DECLARE parentPowerId INT UNSIGNED;
    DECLARE publishedPowerId INT UNSIGNED;
    DECLARE currentVersion SMALLINT UNSIGNED;
    DECLARE authorVersion SMALLINT UNSIGNED;

    SET userPowerId = (SELECT id FROM monster_powers WHERE user_id = userID AND id = monsterPowerId UNION SELECT monster_power_id FROM monster_powers_shared WHERE user_id = userId AND monster_power_id = monsterPowerId);

    IF userPowerId IS NOT NULL THEN
        SET parentPowerId = (SELECT published_parent_id FROM monster_powers WHERE id = userPowerId);
        SET publishedPowerId = (SELECT monster_power_id FROM monster_powers_public WHERE monster_power_id = parentPowerId);
        IF publishedPowerId IS NULL THEN
            SET publishedPowerId = (SELECT monster_power_id FROM monster_powers_private WHERE user_id = userId AND monster_power_id = parentPowerId);
        END IF;

        SELECT p2.version, p1.published_parent_version
        INTO authorVersion, currentVersion
        FROM monster_powers p1
            LEFT JOIN monster_powers p2 ON p1.published_parent_id = p2.id AND p1.id = userPowerId AND p2.id = publishedPowerId
        WHERE p2.version IS NOT NULL;
    ELSE
        SET userPowerId = (SELECT id FROM monster_powers WHERE published_parent_id = monsterPowerId AND user_id = userId);
        IF userPowerId IS NOT NULL THEN
            SELECT p2.version, p1.published_parent_version
            INTO authorVersion, currentVersion
            FROM monster_powers p1
                LEFT JOIN monster_powers p2 ON p1.published_parent_id = p2.id AND p1.id = userPowerId
            WHERE p2.version IS NOT NULL;
        ELSE
            SET userPowerId = (SELECT monster_power_id FROM monster_powers_public WHERE monster_power_id = monsterPowerId);
            IF userPowerId IS NULL THEN
                SET userPowerId = (SELECT monster_power_id FROM monster_powers_private WHERE user_id = userId AND monster_power_id = monsterPowerId);
            END IF;

            IF userPowerId IS NOT NULL THEN
                SELECT version, 0
                INTO authorVersion, currentVersion
                FROM monster_powers WHERE id = userPowerId;
            END IF;
        END IF;
    END IF;

    SELECT currentVersion AS version, authorVersion AS author_version;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `MonsterPowers_Get_Action` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `MonsterPowers_Get_Action`(
    IN monsterPowerId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    SELECT p.id AS monster_power_id, p.name, p.sid, p.user_id = userId AS is_author, p.version,
           l.limited_use_type_id, l.quantity, l.ability_modifier_id, l.dice_size_id,
           p.recharge_min, p.recharge_max, a.action_type_id, a.legendary_cost, a.weapon_range_type_id,
           a.reach, a.normal_range, a.long_range, a.ammo_id,
           ai.name AS ammo_name, ai.description AS ammo_description, ai.sid AS ammo_sid, ai.user_id = userId AS ammo_is_author,
           a.attack_type_id, a.temporary_hp, a.attack_mod, a.attack_ability_modifier_id,
           a.save_type_id, saveType.name AS save_type_name, saveType.description AS save_type_description, saveType.sid AS save_type_sid, saveType.user_id = userId AS save_type_is_author, saveType.version AS save_type_version,
           a.save_proficiency_modifier,
           a.save_ability_modifier_id, a.half_on_save,
           a.description
    FROM monster_powers p
        JOIN monster_actions a on p.id = a.monster_power_id AND p.id = monsterPowerId
        LEFT JOIN monster_power_limited_uses l on p.id = l.monster_power_id
        LEFT JOIN items ai ON a.ammo_id = ai.id
        LEFT JOIN attributes saveType ON saveType.id = a.save_type_id;

    # modifiers
    SELECT pm.monster_power_id, modifier_category_id, modifier_sub_category_id,
           attribute_id, a.name AS attribute_name, a.description AS attribute_description, a.attribute_type_id, a.sid as attribute_sid,
           a.user_id = userId AS attribute_is_author, a.version AS attribute_version,
           value, adjustment, proficient, half_proficient, round_up, advantage, disadvantage,
           pm.ability_modifier_id, ab.name AS ability_modifier_name, ab.sid AS ability_modifier_sid, ab.user_id = userId AS ability_modifier_is_author
    FROM monster_power_modifiers pm
        JOIN monster_powers p ON p.id = pm.monster_power_id AND p.id = monsterPowerId
        JOIN attributes a ON pm.attribute_id = a.id
        LEFT JOIN attributes ab ON pm.ability_modifier_id = ab.id;

    # damages
    SELECT d.monster_action_id, d.num_dice, d.dice_size, d.misc_mod,
           d.ability_modifier_id, abilityModifier.name AS ability_modifier_name, abilityModifier.description AS ability_modifier_description,
           abilityModifier.sid AS ability_modifier_sid, abilityModifier.user_id = userId AS ability_modifier_is_author,
           abilityModifier.version AS ability_modifier_version, abilityModifier2.abbr AS ability_modifier_abbr,
           d.damage_type_id, damageType.name AS damage_type_name, damageType.description AS damage_type_description,
           damageType.sid AS damage_type_sid, damageType.user_id = userId AS damage_type_is_author, damageType.version AS damage_type_version,
           d.healing, d.adjustment
    FROM monster_action_damages d
        JOIN monster_powers p ON p.id = d.monster_action_id AND p.id = monsterPowerId
        LEFT JOIN attributes damageType on damageType.id = d.damage_type_id
        LEFT JOIN attributes abilityModifier ON abilityModifier.id = d.ability_modifier_id
        LEFT JOIN abilities abilityModifier2 ON abilityModifier2.attribute_id = abilityModifier.id;

END ;;
DELIMITER ;
