/*!50003 DROP PROCEDURE IF EXISTS `Monsters_GetAddToMyStuffDetails` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Monsters_GetAddToMyStuffDetails`(
    IN monsterId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED,
    IN checkRights BIT
)
BEGIN
    DECLARE authorMonsterId INT UNSIGNED;
    DECLARE existingMonsterId INT UNSIGNED;
    DECLARE authorUserId MEDIUMINT UNSIGNED;

    IF checkRights = 0 THEN
        SET authorMonsterId = monsterId;
    ELSE
        SET authorMonsterId = (SELECT published_parent_id FROM monsters WHERE user_id = userId AND id = monsterId);
        IF authorMonsterId IS NULL THEN
            SET authorMonsterId = (SELECT monster_id FROM monsters_public WHERE monster_id = monsterId);
        END IF;
        IF authorMonsterId IS NULL THEN
            SET authorMonsterId = (SELECT monster_id FROM monsters_private WHERE user_id = userId AND monster_id = monsterId);
        END IF;
    END IF;

    SELECT user_id
    INTO authorUserId
    FROM monsters WHERE id = authorMonsterId;

    SELECT id
    INTO existingMonsterId
    FROM monsters WHERE published_parent_id = authorMonsterId AND user_id = userId;

    SELECT authorMonsterId AS author_monster_id,
           authorUserId AS author_user_id,
           existingMonsterId AS existing_monster_id;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Monsters_GetItems` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Monsters_GetItems`(
    IN creatureId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    DECLARE monsterId INT UNSIGNED;
    DECLARE monsterUserId MEDIUMINT UNSIGNED;

    SET monsterId = (SELECT id FROM monsters WHERE user_id = userID AND id = creatureId UNION SELECT monster_id FROM monsters_shared WHERE user_id = userId AND monster_id = creatureId);
    IF monsterId IS NULL THEN
        SET monsterId = (SELECT monster_id FROM monsters_public WHERE monster_id = creatureId);
    END IF;
    IF monsterId IS NULL THEN
        SET monsterId = (SELECT monster_id FROM monsters_private WHERE user_id = userId AND monster_id = creatureId);
    END IF;
    IF monsterId IS NULL THEN
        SET monsterId = (SELECT m.id
                         FROM monsters m
                                  JOIN companions c ON m.id = c.monster_id AND c.monster_id = creatureId
                                  JOIN character_companions cc ON c.creature_id = cc.companion_id
                                  JOIN campaign_characters cc2 ON cc.character_id = cc2.creature_id
                                  JOIN campaigns c2 ON cc2.campaign_id = c2.id AND c2.user_id = userId
                         LIMIT 1);
    END IF;
    SET monsterUserId = (SELECT user_id FROM monsters WHERE id = monsterId);

    # Items
    SELECT mi.item_id, i.name AS item_name, i.sid AS item_sid, i.user_id = userId AS item_is_author, mi.quantity, mi.user_id = userId AS item_quantity_author,
           i.cost,i.cost_unit,i.item_type_id,i.version,
           mi.sub_item_id, i2.name AS sub_item_name, i2.sid AS sub_item_sid, i2.user_id = userId AS sub_item_is_author, i2.cost AS sub_item_cost,
           i2.cost_unit AS sub_item_cost_unit, i2.item_type_id AS sub_item_type_id
    FROM monster_items mi
        JOIN items i ON mi.item_id = i.id AND mi.monster_id = monsterId
        LEFT JOIN items i2 ON i2.id = mi.sub_item_id
        JOIN monsters m ON m.id = mi.monster_id
    WHERE mi.user_id = monsterUserId OR mi.user_id = m.user_id
    ORDER BY i.name;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Monsters_GetList` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Monsters_GetList`(
    IN userId MEDIUMINT UNSIGNED,
    IN search VARCHAR(45),

    IN monsterTypeId TINYINT UNSIGNED,
    IN challengeRatingId TINYINT UNSIGNED,
    IN alignmentId INT UNSIGNED,
    IN isSpellcaster BIT,
    IN isLegendary BIT,
    IN isFlying BIT,
    IN isSwimming BIT,

    IN offset INT UNSIGNED,
    IN pageSize INT UNSIGNED,
    IN listSource TINYINT UNSIGNED
)
BEGIN
    CREATE TEMPORARY TABLE IF NOT EXISTS temp_list
    (
        id INT UNSIGNED NOT NULL
    );

    CREATE TEMPORARY TABLE IF NOT EXISTS temp_flying
    (
        id INT UNSIGNED NOT NULL
    );

    CREATE TEMPORARY TABLE IF NOT EXISTS temp_swimming
    (
        id INT UNSIGNED NOT NULL
    );

    IF listSource = 1 THEN
        INSERT INTO temp_list
        SELECT id FROM monsters WHERE user_id = userId
        UNION
        SELECT monster_id FROM monsters_shared WHERE user_id = userId;
    ELSEIF listSource = 2 THEN
        INSERT INTO temp_list SELECT monster_id FROM monsters_public;
    ELSEIF listSource = 3 THEN
        INSERT INTO temp_list SELECT monster_id FROM monsters_private WHERE user_id = userId;
    END IF;

    IF isFlying IS NOT NULL THEN
        INSERT INTO temp_flying (id)
        SELECT m.id FROM monsters m JOIN monster_speeds ms ON ms.monster_id = m.id
        WHERE ms.speed_id = 5 AND ms.value > 0;
    END IF;

    IF isSwimming IS NOT NULL THEN
        INSERT INTO temp_swimming (id)
        SELECT m.id FROM monsters m JOIN monster_speeds ms ON ms.monster_id = m.id
        WHERE ms.speed_id = 4 AND ms.value > 0;
    END IF;

    SELECT m.id, name, sid, m.user_id = userId AS is_author, m.challenge_rating_id
    FROM temp_list uc
        JOIN monsters m ON m.id = uc.id
        LEFT JOIN temp_flying f ON m.id = f.id
        LEFT JOIN temp_swimming s ON m.id = s.id
    WHERE (search IS NULL OR search = '' OR search = '%%' OR name LIKE search)
      AND (monsterTypeId IS NULL OR m.monster_type_id = monsterTypeId)
      AND (challengeRatingId IS NULL OR m.challenge_rating_id = challengeRatingId)
      AND (alignmentId IS NULL OR m.alignment_id = alignmentId)
      AND (isSpellcaster IS NULL OR m.spellcaster = isSpellcaster)
      AND (isLegendary IS NULL OR (isLegendary = 0 AND m.legendary_points = 0) OR (isLegendary = 1 AND m.legendary_points != 0))
      AND (isFlying IS NULL OR (isFlying = 0 AND f.id IS NULL) OR (isFlying = 1 AND f.id IS NOT NULL))
      AND (isSwimming IS NULL OR (isSwimming = 0 AND s.id IS NULL) OR (isSwimming = 1 AND s.id IS NOT NULL))
    ORDER BY name
    LIMIT offset, pageSize;

    DROP TEMPORARY TABLE IF EXISTS temp_list;
    DROP TEMPORARY TABLE IF EXISTS temp_flying;
    DROP TEMPORARY TABLE IF EXISTS temp_swimming;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Monsters_GetPublishedDetails` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Monsters_GetPublishedDetails`(
    IN monsterId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    DECLARE authorMonsterId INT UNSIGNED;

    SET authorMonsterId = (SELECT id FROM monsters WHERE user_id = userId AND id = monsterId);
    SELECT EXISTS(
        SELECT 1 FROM monsters_public WHERE monster_id = authorMonsterId
        UNION
        SELECT 1 FROM monsters_private WHERE monster_id = authorMonsterId
    ) AS published;

    SELECT u.username
    FROM monsters_private ap
        JOIN users u ON u.id = ap.user_id AND ap.monster_id = authorMonsterId;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
