	(@EttinMorningstarId, 1, 0, 1, 5, 0, 0, null, 1, 0, 7, null, null, 0, null, 0, ''),
	(@ShriekerShriekId, 1, 0, 1, 0, 0, 0, null, 4, 0, 0, null, null, 0, null, 0, 'When bright light or a creature is within 30 feet of the shrieker, it emits a shriek audible within 300 feet of it. The shrieker continues to shriek until the disturbance moves out of range and for 1d4 of the shrieker''s turns afterward.'),
	(@VioletFungusMultiattackId, 1, 0, 1, 0, 0, 0, null, 4, 0, 0, null, null, 0, null, 0, 'The fungus makes 1d4 Rotting Touch attacks.'),
