/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Powers_Delete`(
    IN powerId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    DECLARE powerTypeId TINYINT UNSIGNED;

    SET powerTypeId = (SELECT power_type_id FROM powers WHERE id = powerId);

    IF powerTypeId = 1 THEN
        CALL Powers_Delete_Spell(powerId, userId);
    ELSEIF powerTypeId = 2 THEN
        CALL Powers_Delete_Feature(powerId, userId);
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Powers_Delete_Common` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Powers_Delete_Common`(
    IN powerId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    DELETE cvip FROM character_validation_ignored_powers cvip JOIN creatures c ON c.id = cvip.character_id WHERE power_id = powerId AND c.user_id = userId;
    DELETE cpt FROM creature_power_tags cpt JOIN creatures c ON c.id = cpt.creature_id WHERE cpt.power_id = powerId AND c.user_id = userId;
    DELETE cp FROM creature_powers cp JOIN creatures c ON c.id = cp.creature_id WHERE cp.power_id = powerId AND c.user_id = userId;
    DELETE pd FROM power_damages pd JOIN powers p ON p.id = pd.power_id WHERE pd.power_id = powerId AND p.user_id = userId;
    DELETE pl FROM power_limited_uses pl JOIN powers p ON p.id = pl.power_id WHERE pl.power_id = powerId AND p.user_id = userId;
    DELETE pm FROM power_modifiers pm JOIN powers p ON p.id = pm.power_id WHERE pm.power_id = powerId AND p.user_id = userId;

    CREATE TEMPORARY TABLE IF NOT EXISTS temp_creature_actions
    (
        id INT UNSIGNED NOT NULL
    );

    INSERT INTO temp_creature_actions
    SELECT ca.id
    FROM creature_action_powers cap JOIN creature_actions ca ON ca.id = cap.creature_action_id JOIN creatures c ON c.id = ca.creature_id WHERE power_id = powerId AND c.user_id = userId;

    DELETE cai FROM chained_action_items cai JOIN temp_creature_actions tca ON tca.id = cai.creature_action_id;
    DELETE cap FROM creature_action_powers cap JOIN temp_creature_actions tca ON tca.id = cap.creature_action_id;
    DELETE ca FROM creature_actions ca JOIN temp_creature_actions tca ON tca.id = ca.id;

    DROP TEMPORARY TABLE IF EXISTS temp_creature_actions;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Powers_Delete_Feature` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Powers_Delete_Feature`(
    IN powerId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    DECLARE characteristicId INT UNSIGNED;
    DECLARE featureId INT UNSIGNED;
    DECLARE isOwner BIT;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
        BEGIN
            ROLLBACK;
            SELECT -1 AS result;
        END;

    START TRANSACTION;

    SELECT id, user_id = userId, f.characteristic_id
    INTO featureId, isOwner, characteristicId
    FROM powers p
             JOIN features f ON f.power_id = p.id
    WHERE user_id IN (0, userId) AND id = powerId;

    IF featureId IS NOT NULL THEN
        CALL Powers_Delete_Common(featureId, userId);

        IF isOwner THEN
            DELETE FROM powers_public WHERE power_id = powerId;
            DELETE FROM powers_private WHERE power_id = powerId;
            UPDATE powers SET published_parent_id = NULL, published_parent_version = NULL WHERE published_parent_id = powerId;

            DELETE f FROM features f JOIN powers p ON p.id = f.power_id WHERE power_id = featureId AND p.user_id = userId;
            DELETE FROM powers WHERE user_id = userId AND id = featureId;
        ELSE
            DELETE FROM powers_shared WHERE user_id = userId AND power_id = featureId;
        END IF;

        IF characteristicId IS NOT NULL THEN
            UPDATE characteristics SET version = version + 1 WHERE user_id = userId AND id = characteristicId;
        END IF;
    END IF;

    COMMIT;

    SELECT 1 AS result;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Powers_Delete_Spell` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Powers_Delete_Spell`(
    IN powerId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    DECLARE spellId INT UNSIGNED;
    DECLARE isOwner BIT;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        SELECT -1 AS result;
    END;

    START TRANSACTION;

    SELECT id, user_id = userId
    INTO spellId, isOwner
    FROM powers
    WHERE user_id IN (0, userId) AND id = powerId;

    IF spellId IS NOT NULL THEN
        DELETE ms FROM monster_spells ms JOIN monsters m ON m.id = ms.monster_id WHERE ms.spell_id = spellId AND (m.user_id = userId OR ms.user_id = userId);
        DELETE mis FROM monster_innate_spells mis JOIN monsters m ON m.id = mis.monster_id WHERE mis.spell_id = spellId AND (m.user_id = userId OR mis.user_id = userId);
        DELETE csc FROM characteristic_spell_configurations csc JOIN characteristics c ON c.id = csc.characteristic_id WHERE csc.spell_id = spellId AND (c.user_id = userId OR csc.user_id = userId);
        DELETE csc FROM creature_spell_configurations csc JOIN creatures c ON c.id = csc.creature_id WHERE csc.spell_id = spellId AND (c.user_id = userId OR csc.user_id = userId);
        DELETE cas FROM creature_active_spells cas JOIN creatures  c ON c.id = cas.creature_id WHERE cas.spell_id = spellId AND c.user_id = userId;
        DELETE cis FROM creature_item_spells cis JOIN creature_items ci ON ci.id = cis.creature_item_id JOIN creatures c ON c.id = ci.creature_id WHERE cis.spell_id = spellId AND c.user_id = userId;
        DELETE mis FROM magical_item_spells mis JOIN items i ON i.id = mis.magical_item_id WHERE mis.spell_id = spellId AND i.user_id = userId;
        DELETE mias FROM magical_item_applicable_spells mias JOIN items i ON i.id = mias.magical_item_id WHERE mias.spell_id = spellId AND i.user_id = userId;

        CALL Powers_Delete_Common(spellId, userId);

        IF isOwner THEN
            DELETE FROM powers_public WHERE power_id = powerId;
            DELETE FROM powers_private WHERE power_id = powerId;
            UPDATE powers SET published_parent_id = NULL, published_parent_version = NULL WHERE published_parent_id = powerId;

            DELETE s FROM spells s JOIN powers p ON p.id = s.power_id WHERE power_id = spellId AND p.user_id = userId;
            DELETE FROM powers WHERE user_id = userId AND id = spellId;
        ELSE
            DELETE FROM powers_shared WHERE user_id = userId AND power_id = spellId;
        END IF;
    END IF;

    COMMIT;

    SELECT 1 AS result;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Powers_ForCharacteristic_GetAddToMyStuffDetails` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Powers_ForCharacteristic_GetAddToMyStuffDetails`(
    IN authorCharacteristicId INT UNSIGNED,
    IN authorUserId MEDIUMINT UNSIGNED,
    IN characteristicId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    CREATE TEMPORARY TABLE IF NOT EXISTS temp_powers
    (
        id INT UNSIGNED NOT NULL
    );

    INSERT INTO temp_powers
    SELECT p.id
    FROM powers p
        JOIN features f on p.id = f.power_id AND f.characteristic_id = authorCharacteristicId AND p.user_id IN (0, authorUserId);

    SELECT tp.id AS author_power_id, 2 AS author_power_type_id, p.id AS existing_power_id, p.power_type_id AS existing_power_type_id
    FROM temp_powers tp
        LEFT JOIN powers p ON p.published_parent_id = tp.id AND p.user_id = userId;

    SELECT id
    FROM powers p
        JOIN features f ON f.power_id = p.id AND f.characteristic_id = characteristicId
    WHERE p.published_parent_id IS NULL OR p.published_parent_id NOT IN (SELECT id FROM temp_powers);

    DROP TEMPORARY TABLE IF EXISTS temp_powers;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Powers_Get` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Powers_Get`(
    IN powerId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    DECLARE powerTypeId TINYINT UNSIGNED;
    SET powerTypeId = (SELECT power_type_id FROM powers WHERE id = powerId);
    SELECT powerTypeId AS power_type_id;

    IF powerTypeId = 1 THEN
        CALL Powers_Get_Spell(powerId, userId);
    ELSEIF powerTypeId = 2 THEN
        CALL Powers_Get_Feature(powerId, userId);
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Powers_GetAddToMyStuffDetails` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Powers_GetAddToMyStuffDetails`(
    IN powerId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED,
    IN checkRights BIT
)
BEGIN
    DECLARE authorPowerId INT UNSIGNED;
    DECLARE existingPowerId INT UNSIGNED;
    DECLARE authorUserId MEDIUMINT UNSIGNED;
    DECLARE authorPowerTypeId TINYINT UNSIGNED;
    DECLARE existingPowerTypeId TINYINT UNSIGNED;

    IF checkRights = 0 THEN
        SET authorPowerId = powerId;
    ELSE
        SET authorPowerId = (SELECT published_parent_id FROM powers WHERE user_id = userId AND id = powerId);
        IF authorPowerId IS NULL THEN
            SET authorPowerId = (SELECT power_id FROM powers_public WHERE power_id = powerId);
        END IF;
        IF authorPowerId IS NULL THEN
            SET authorPowerId = (SELECT power_id FROM powers_private WHERE user_id = userId AND power_id = powerId);
        END IF;
    END IF;

    SELECT user_id, power_type_id
    INTO authorUserId, authorPowerTypeId
    FROM powers WHERE id = authorPowerId;

    SELECT id, power_type_id
    INTO existingPowerId, existingPowerTypeId
    FROM powers WHERE published_parent_id = authorPowerId AND user_id = userId;

    SELECT authorPowerId AS author_power_id,
           authorUserId AS author_user_id,
           existingPowerId AS existing_power_id,
           authorPowerTypeId AS author_power_type_id,
           existingPowerTypeId AS existing_power_type_id;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Powers_GetList_CreatureFeaturesInList` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Powers_GetList_CreatureFeaturesInList`(
    IN creatureId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED,
    IN featureIds VARCHAR(500)
)
BEGIN
    DECLARE characterId INT UNSIGNED;
    SET characterId = (SELECT id FROM creatures WHERE user_id = userID AND id = creatureId UNION SELECT creature_id FROM creatures_shared WHERE user_id = userId AND creature_id = creatureId);

    CREATE TEMPORARY TABLE IF NOT EXISTS temp_ids
    (
        id INT UNSIGNED NOT NULL
    );

    IF featureIds IS NOT NULL THEN
        SET @sql = CONCAT('INSERT INTO temp_ids (id) SELECT id FROM powers WHERE power_type_id = 2 AND id IN (', featureIds, ')');
        PREPARE stmt FROM @sql;
        EXECUTE stmt;
        DEALLOCATE PREPARE stmt;
    END IF;

    SELECT p.id AS feature_id, p.name AS feature_name, p.sid as feature_sid, p.user_id = userId AS feature_is_author, f.characteristic_type_id,
           c.id AS characteristic_id, c.name AS characteristic_name, c.sid AS characteristic_sid, c.user_id = userId AS characteristic_is_author, f.passive
    FROM temp_ids ti
             JOIN powers p ON p.id = ti.id
             JOIN features f ON f.power_id = p.id
             LEFT JOIN characteristics c ON f.characteristic_id = c.id
    GROUP BY p.id;

    # Tags
    SELECT p.power_id, t.id, t.power_type_id, t.title, t.color
    FROM creature_power_tags p
             JOIN creature_tags t ON p.creature_tag_id = t.id
    WHERE p.creature_id = characterId and p.power_id IN (SELECT id FROM temp_ids);

    DROP TEMPORARY TABLE IF EXISTS temp_ids;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Powers_GetList_Features` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Powers_GetList_Features`(
    IN userId MEDIUMINT UNSIGNED,
    IN search VARCHAR(50),
    IN isPassive BIT,
    IN isFeat BIT,
    IN characteristicTypeId TINYINT UNSIGNED,
    IN characteristicId INT UNSIGNED,
    IN includeChildren BIT,
    IN characterLevelId INT UNSIGNED,
    IN isRanged BIT,
    IN isAreaOfEffect BIT,
    IN areaOfEffectId INT UNSIGNED,
    IN offset INT UNSIGNED,
    IN pageSize INT UNSIGNED,
    IN listSource TINYINT UNSIGNED
)
BEGIN
    DECLARE powerTypeId TINYINT UNSIGNED;
    SET powerTypeId = 2;

    CREATE TEMPORARY TABLE IF NOT EXISTS temp_list
    (
        id INT UNSIGNED NOT NULL
    );

    CREATE TEMPORARY TABLE IF NOT EXISTS temp_characteristics
    (
        id INT UNSIGNED NOT NULL
    );

    IF listSource = 1 THEN
        INSERT INTO temp_list
        SELECT id FROM powers WHERE user_id = userId
        UNION
        SELECT power_id FROM powers_shared WHERE user_id = userId;
    ELSEIF listSource = 2 THEN
        INSERT INTO temp_list SELECT power_id FROM powers_public;
    ELSEIF listSource = 3 THEN
        INSERT INTO temp_list SELECT power_id FROM powers_private WHERE user_id = userId;
    END IF;

    IF characteristicId IS NOT NULL THEN
        INSERT INTO temp_characteristics (id) VALUES (characteristicId);

        INSERT INTO temp_characteristics (id)
        WITH RECURSIVE parents (parent_characteristic_id) AS
        (
            SELECT parent_characteristic_id
            FROM characteristics
            WHERE id = characteristicId

            UNION ALL

            SELECT c2.parent_characteristic_id
            FROM parents p
                JOIN characteristics AS c2 ON p.parent_characteristic_id = c2.id AND c2.parent_characteristic_id IS NOT NULL
        )
        SELECT parent_characteristic_id FROM parents WHERE parent_characteristic_id IS NOT NULl;

        IF includeChildren THEN
            INSERT INTO temp_characteristics (id)
            WITH RECURSIVE children (id) AS
            (
               SELECT id
               FROM characteristics
               WHERE parent_characteristic_id = characteristicId

               UNION ALL

               SELECT c2.id
               FROM children c
                        JOIN characteristics AS c2 ON c.id = c2.parent_characteristic_id
            )
            SELECT id FROM children;
        END IF;
    END IF;

    SELECT p.id, p.name, p.sid, p.user_id = userId AS is_author
    FROM temp_list up
        JOIN powers p ON p.id = up.id
            AND p.power_type_id = powerTypeId
        JOIN features f ON f.power_id = p.id
    WHERE (search IS NULL OR search = '' OR search = '%%' OR name LIKE search)
        AND (isPassive IS NULL OR f.passive = isPassive)
        AND (isFeat IS NULL
                 OR (isFeat = 1 AND f.characteristic_type_id IS NULL)
                 OR (isFeat = 0 AND f.characteristic_type_id IS NOT NULL AND (
                     characteristicTypeId IS NULL OR (
                         f.characteristic_type_id = characteristicTypeId AND (
                             characteristicId IS NULL OR f.characteristic_id IN (SELECT id FROM temp_characteristics)
                            )
                         )
                     )
                 )
            )
        AND (characterLevelId IS NULL OR f.character_level_id = characterLevelId)
        AND (isRanged IS NULL
                 OR (isRanged = 1 AND p.range_type = 5)
                 OR (isRanged = 0 AND p.range_type != 5))
        AND (isAreaOfEffect IS NULL
                 OR (isAreaOfEffect = 1 AND p.area_of_effect_id IS NOT NULL AND (areaOfEffectId IS NULL OR p.area_of_effect_id = areaOfEffectId))
                 OR (isAreaOfEffect = 0 AND p.area_of_effect_id IS NULL))
    ORDER BY p.name
    LIMIT offset, pageSize;

    # todo - verify that a group by p.id isn't needed

    DROP TEMPORARY TABLE IF EXISTS temp_list;
    DROP TEMPORARY TABLE IF EXISTS temp_characteristics;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Powers_GetList_FeaturesByCharacteristicType` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Powers_GetList_FeaturesByCharacteristicType`(
    IN userId MEDIUMINT UNSIGNED,
    IN characteristicTypeId TINYINT UNSIGNED
)
BEGIN
    CREATE TEMPORARY TABLE IF NOT EXISTS temp_ids
    (
        id INT UNSIGNED NOT NULL
    );

    INSERT INTO temp_ids
    SELECT f.power_id FROM powers up
                               JOIN features f ON up.user_id = userId AND f.power_id = up.id
    WHERE (characteristicTypeId IS NULL AND f.characteristic_type_id IS NULL)
       OR (characteristicTypeId IS NOT NULL AND f.characteristic_type_id = characteristicTypeId);

    INSERT INTO temp_ids
    SELECT f.power_id FROM powers_shared up
                               JOIN features f ON up.user_id = userId AND f.power_id = up.power_id
    WHERE (characteristicTypeId IS NULL AND f.characteristic_type_id IS NULL)
       OR (characteristicTypeId IS NOT NULL AND f.characteristic_type_id = characteristicTypeId);

    SELECT p.id AS feature_id, p.name AS feature_name, p.sid as feature_sid, p.user_id = userId AS feature_is_author, f.characteristic_type_id,
           c.id AS characteristic_id, c.name AS characteristic_name, c.sid AS characteristic_sid, c.user_id = userId AS characteristic_is_author, f.passive
    FROM temp_ids t
             JOIN powers p ON p.id = t.id
             JOIN features f ON f.power_id = p.id
             LEFT JOIN characteristics c ON f.characteristic_id = c.id
    ORDER BY p.name;

    DROP TEMPORARY TABLE IF EXISTS temp_ids;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Powers_GetList_FeaturesForCharacteristic` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Powers_GetList_FeaturesForCharacteristic`(
    IN characteristicId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    SELECT p.id AS power_id, p.name, p.sid, p.user_id = userId AS is_author, p.version,
           p.attack_type, p.temporary_hp, p.attack_mod,
           p.save_type_id, saveType.name AS save_type_name, saveType.description AS save_type_description, saveType.sid AS save_type_sid, saveType.user_id = userId AS save_type_is_author, saveType.version AS save_type_version, saveType2.abbr AS save_type_abbr,
           p.half_on_save, p.extra_damage, p.num_levels_above_base,
           p.advancement, p.extra_modifiers, p.modifiers_num_levels_above_base, p.modifier_advancement,
           f.characteristic_id, c.name as characteristic_name, c.sid as characteristic_sid, c.user_id = userId AS characteristic_is_author, f.characteristic_type_id,
           f.character_level_id, cl.name AS character_level_name, cl.sid AS character_level_sid, cl.user_id = userId AS character_level_is_author,
           p.range_type, p.range, p.range_unit,
           p.area_of_effect_id, p.radius, p.width, p.height, p.length, a.name as area_of_effect_name, a.description as area_of_effect_description, a.sid AS area_of_effect_sid,
           a.user_id = userId AS area_of_effect_is_author, a.version AS area_of_effect_version,
           aoe.radius AS area_of_effect_radius, aoe.width AS area_of_effect_width, aoe.height AS area_of_effect_height, aoe.length AS area_of_effect_length,
           p.recharge_min, p.recharge_max, p.recharge_on_short_rest, p.recharge_on_long_rest, f.prerequisite, f.description, f.passive, f.save_proficiency_modifier, f.save_ability_modifier_id, action_id
    FROM powers p
        JOIN features f on p.id = f.power_id AND f.characteristic_id = characteristicId
        JOIN characteristics c ON f.characteristic_id = c.id
        LEFT JOIN area_of_effects aoe ON p.area_of_effect_id = aoe.attribute_id
        LEFT JOIN attributes a ON aoe.attribute_id = a.id
        LEFT JOIN attributes cl ON f.character_level_id = cl.id
        LEFT JOIN attributes saveType ON saveType.id = p.save_type_id
        LEFT JOIN abilities saveType2 ON saveType2.attribute_id = saveType.id
    WHERE p.user_id = userId OR p.user_id = c.user_id;

    # todo - if !null

    CALL Powers_Get_DamageConfigurationsForCharacteristic(characteristicId, 0, 0, userId);
    CALL Powers_Get_DamageConfigurationsForCharacteristic(characteristicId, 0, 1, userId);
    CALL Powers_Get_DamageConfigurationsForCharacteristic(characteristicId, 1, 0, userId);

    CALL Powers_Get_ModifierConfigurationsForCharacteristic(characteristicId, 0, 0, userId);
    CALL Powers_Get_ModifierConfigurationsForCharacteristic(characteristicId, 0, 1, userId);
    CALL Powers_Get_ModifierConfigurationsForCharacteristic(characteristicId, 1, 0, userId);

    CALL Powers_Get_LimitedUsesForCharacteristic(characteristicId, userId);
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Powers_GetList_FeaturesInList` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Powers_GetList_FeaturesInList`(
    IN userId MEDIUMINT UNSIGNED,
    IN featureIds VARCHAR(500)
)
BEGIN
    CREATE TEMPORARY TABLE IF NOT EXISTS temp_ids
    (
        id INT UNSIGNED NOT NULL
    );

    IF featureIds IS NOT NULL THEN
        SET @sql = CONCAT('INSERT INTO temp_ids (id) SELECT id FROM powers WHERE power_type_id = 2 AND id IN (', featureIds, ')');
        PREPARE stmt FROM @sql;
        EXECUTE stmt;
        DEALLOCATE PREPARE stmt;
    END IF;

    SELECT p.id AS feature_id, p.name AS feature_name, p.sid as feature_sid, p.user_id = userId AS feature_is_author, f.characteristic_type_id,
           c.id AS characteristic_id, c.name AS characteristic_name, c.sid AS characteristic_sid, c.user_id = userId AS characteristic_is_author, f.passive
    FROM temp_ids ti
             JOIN powers p ON p.id = ti.id
             JOIN features f ON f.power_id = p.id
             LEFT JOIN characteristics c ON f.characteristic_id = c.id
    GROUP BY p.id;

    DROP TEMPORARY TABLE IF EXISTS temp_ids;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Powers_GetList_FeaturesSimpleForCharacteristic` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Powers_GetList_FeaturesSimpleForCharacteristic`(
    IN characteristicId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    SELECT p.id, p.name, p.sid, p.user_id = userId AS is_author
    FROM powers p
        JOIN features f on p.id = f.power_id AND f.characteristic_id = characteristicId
        JOIN characteristics c ON f.characteristic_id = c.id
    WHERE p.user_id = userId OR p.user_id = c.user_id;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Powers_GetList_Spells` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Powers_GetList_Spells`(
    IN userId MEDIUMINT UNSIGNED,
    IN search VARCHAR(50),
    IN spellSchoolId INT UNSIGNED,
    IN isRitual BIT,
    IN spellLevel TINYINT UNSIGNED,
    IN isVerbal BIT,
    IN isSomatic BIT,
    IN isMaterial BIT,
    IN isInstantaneous BIT,
    IN isConcentration BIT,
    IN isAreaOfEffect BIT,
    IN areaOfEffectId INT UNSIGNED,
    IN characteristicId INT UNSIGNED,
    IN offset INT UNSIGNED,
    IN pageSize INT UNSIGNED,
    IN listSource TINYINT UNSIGNED
)
BEGIN
    DECLARE powerTypeId TINYINT UNSIGNED;
    SET powerTypeId = 1;

    CREATE TEMPORARY TABLE IF NOT EXISTS applicable_conditions
    (
        id INT UNSIGNED NOT NULL
    );

    CREATE TEMPORARY TABLE IF NOT EXISTS temp_characteristics
    (
        id INT UNSIGNED NOT NULL
    );

    CREATE TEMPORARY TABLE IF NOT EXISTS temp_spells
    (
        id INT UNSIGNED NOT NULL,
        level TINYINT UNSIGNED NOT NULL
    );

    CREATE TEMPORARY TABLE IF NOT EXISTS temp_list
    (
        id INT UNSIGNED NOT NULL
    );

    IF listSource = 1 THEN
        INSERT INTO temp_list
        SELECT id FROM powers WHERE user_id = userId
        UNION
        SELECT power_id FROM powers_shared WHERE user_id = userId;
    ELSEIF listSource = 2 THEN
        INSERT INTO temp_list SELECT power_id FROM powers_public;
    ELSEIF listSource = 3 THEN
        INSERT INTO temp_list SELECT power_id FROM powers_private WHERE user_id = userId;
    END IF;

    IF characteristicId IS NOT NULL THEN
        INSERT INTO temp_characteristics (id) VALUES (characteristicId);

        INSERT INTO temp_characteristics (id)
        WITH RECURSIVE parents (parent_characteristic_id) AS
                           (
                               SELECT parent_characteristic_id
                               FROM characteristics c
                               WHERE user_id = userId AND id = characteristicId

                               UNION ALL

                               SELECT parent_characteristic_id
                               FROM characteristics c
                                        JOIN characteristics_shared uc ON uc.user_id = userId AND uc.characteristic_id = c.id AND c.id = characteristicId

                               UNION ALL

                               SELECT c2.parent_characteristic_id
                               FROM parents p
                                        JOIN characteristics AS c2 ON p.parent_characteristic_id = c2.id AND c2.parent_characteristic_id IS NOT NULL
                                        JOIN characteristics uc2 ON uc2.user_id = userId AND uc2.id = c2.id

                               UNION ALL

                               SELECT c2.parent_characteristic_id
                               FROM parents p
                                        JOIN characteristics AS c2 ON p.parent_characteristic_id = c2.id AND c2.parent_characteristic_id IS NOT NULL
                                        JOIN characteristics_shared uc2 ON uc2.user_id = userId AND uc2.characteristic_id = c2.id
                           )
        SELECT parent_characteristic_id FROM parents WHERE parent_characteristic_id IS NOT NULl;
    END IF;

    INSERT INTO temp_spells (id, level)
    SELECT p.id, s.level
    FROM temp_list up
             JOIN powers p ON p.id = up.id
        AND p.power_type_id = powerTypeId
             JOIN spells s ON s.power_id = p.id
             LEFT JOIN characteristic_spell_configurations csc ON csc.spell_id = s.power_id
             LEFT JOIN characteristics c ON c.id = csc.characteristic_id
    WHERE (search IS NULL OR search = '' OR search = '%%' OR p.name LIKE search)
      AND (spellSchoolId IS NULL OR s.spell_school_id = spellSchoolId)
      AND (isRitual IS NULL OR s.ritual = isRitual)
      AND (spellLevel IS NULL OR s.level = spellLevel)
      AND (isVerbal IS NULL OR s.verbal = isVerbal)
      AND (isSomatic IS NULL OR s.somatic = isSomatic)
      AND (isMaterial IS NULL OR s.material = isMaterial)
      AND (isInstantaneous IS NULL OR s.instantaneous = isInstantaneous)
      AND (isConcentration IS NULL OR s.concentration = isConcentration)
      AND (isAreaOfEffect IS NULL
        OR (isAreaOfEffect = 1 AND p.area_of_effect_id IS NOT NULL AND (areaOfEffectId IS NULL OR p.area_of_effect_id = areaOfEffectId))
        OR (isAreaOfEffect = 0 AND p.area_of_effect_id IS NULL))
      AND (characteristicId IS NULL OR (csc.characteristic_id IN (SELECT id FROM temp_characteristics) AND (csc.user_id = userId OR csc.user_id = c.user_id)))
    GROUP BY p.id, p.name
    ORDER BY p.name
    LIMIT offset, pageSize;

    SELECT p.id AS spell_id, p.name AS spell_name, p.sid AS spell_sid, p.user_id = userId AS spell_is_author, ts.level AS spell_level
    FROM temp_spells ts
             JOIN powers p ON p.id = ts.id;

    DROP TEMPORARY TABLE IF EXISTS temp_list;
    DROP TEMPORARY TABLE IF EXISTS temp_characteristics;
    DROP TEMPORARY TABLE IF EXISTS temp_spells;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Powers_GetList_SpellsInList` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Powers_GetList_SpellsInList`(
    IN creatureId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED,
    IN spellIds VARCHAR(500)
)
BEGIN
    DECLARE characterId INT UNSIGNED;
    SET characterId = (SELECT id FROM creatures WHERE user_id = userID AND id = creatureId UNION SELECT creature_id FROM creatures_shared WHERE user_id = userId AND creature_id = creatureId);

    CREATE TEMPORARY TABLE IF NOT EXISTS temp_ids
    (
        id INT UNSIGNED NOT NULL
    );

    IF spellIds IS NOT NULL THEN
        SET @sql = CONCAT('INSERT INTO temp_ids (id) SELECT id FROM powers WHERE power_type_id = 1 AND id IN (', spellIds, ')');
        PREPARE stmt FROM @sql;
        EXECUTE stmt;
        DEALLOCATE PREPARE stmt;
    END IF;

    SELECT p.id AS spell_id, p.name AS spell_name, p.sid as spell_sid, p.user_id = userId AS spell_is_author, s.level AS spell_level
    FROM temp_ids ti
             JOIN powers p ON p.id = ti.id
             JOIN spells s ON s.power_id = p.id
    GROUP BY p.id;

    # Tags
    SELECT p.power_id, t.id, t.power_type_id, t.title, t.color
    FROM creature_power_tags p
             JOIN creature_tags t ON p.creature_tag_id = t.id
    WHERE p.creature_id = characterId and p.power_id IN (SELECT id FROM temp_ids);

    DROP TEMPORARY TABLE IF EXISTS temp_ids;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Powers_GetPublishedDetails` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Powers_GetPublishedDetails`(
    IN powerId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    DECLARE authorPowerId INT UNSIGNED;

    SET authorPowerId = (SELECT id FROM powers WHERE user_id = userId AND id = powerId);
    SELECT EXISTS(
                   SELECT 1 FROM powers_public WHERE power_id = authorPowerId
                   UNION
                   SELECT 1 FROM powers_private WHERE power_id = authorPowerId
               ) AS published;

    SELECT u.username
    FROM powers_private pp
             JOIN users u ON u.id = pp.user_id AND pp.power_id = authorPowerId;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
