/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Rolls_Get` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Rolls_Get`(
    IN rollId INT UNSIGNED,
    IN creatureId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    CREATE TEMPORARY TABLE IF NOT EXISTS temp_ids
    (
        id INT UNSIGNED NOT NULL
    );

    INSERT INTO temp_ids
    SELECT rollId
    UNION
    SELECT id
    FROM rolls
    WHERE parent_roll_id = rollId;

    # Rolls
    SELECT id, creature_id, roll_type_id, reason, half_on_miss, advantage, disadvantage, critical, timestamp, result
    FROM rolls
    WHERE id = rollId AND creature_id = creatureId;

    # Children Rolls
    SELECT id, creature_id, roll_type_id, reason, half_on_miss, advantage, disadvantage, critical, timestamp, result
    FROM rolls
    WHERE parent_roll_id = rollId
    ORDER BY timestamp DESC;

    # Roll Results
    SELECT roll_id, id AS result_id
    FROM roll_results
    WHERE roll_id IN (SELECT id FROM temp_ids);

    # Dice Results
    SELECT roll_result_id, dice_size_id, modifier, results, critical, damage_type_id, damageType.name AS damage_type_name,
           damageType.description AS damage_type_description, damageType.sid AS damage_type_sid,
           damageType.user_id = userId AS damage_type_is_author, damageType.version AS damage_type_version
    FROM roll_dice_results rdr
        LEFT JOIN attributes damageType ON rdr.damage_type_id = damageType.id
    WHERE roll_result_id IN (
            SELECT id
            FROM roll_results
            WHERE roll_id IN (SELECT id FROM temp_ids)
        );

    DROP TEMPORARY TABLE IF EXISTS temp_ids;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Rolls_GetList` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Rolls_GetList`(
    IN creatureId INT UNSIGNED,
    IN isArchived BIT
)
BEGIN
    CREATE TEMPORARY TABLE IF NOT EXISTS temp_ids
    (
        id INT UNSIGNED NOT NULL
    );
    
    INSERT INTO temp_ids
    SELECT id
    FROM rolls
    WHERE creature_id = creatureId AND archived = isArchived AND parent_roll_id IS NULL;

    # Rolls
    SELECT r.id, creature_id, roll_type_id, reason, half_on_miss, advantage, disadvantage, critical, timestamp, result
    FROM temp_ids ti
        JOIN rolls r ON r.id = ti.id
    ORDER BY timestamp DESC;

    # Children Rolls
    SELECT parent_roll_id, id, creature_id, roll_type_id, reason, half_on_miss, advantage, disadvantage, critical, timestamp, result
    FROM rolls
    WHERE parent_roll_id IN (SELECT id FROM temp_ids)
    ORDER BY timestamp DESC;
    
    DROP TEMPORARY TABLE IF EXISTS temp_ids;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `Spells_GetCharacteristics` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`squire`@`%` PROCEDURE `Spells_GetCharacteristics`(
    IN spellId INT UNSIGNED,
    IN userId MEDIUMINT UNSIGNED
)
BEGIN
    SELECT c.id, c.name, c.sid, c.user_id = userId AS is_author, cs.user_id = userId AS config_is_author
    FROM characteristic_spell_configurations cs
        JOIN spells s ON cs.spell_id = s.power_id
        JOIN powers p ON s.power_id = p.id
        JOIN characteristics c ON c.id = cs.characteristic_id
    WHERE cs.spell_id = spellId
        AND (cs.user_id = userId OR cs.user_id = p.user_id)
    ORDER BY p.name;
END ;;
DELIMITER ;
