	#abilities
	INSERT INTO `attributes` (`name`, `description`, `attribute_type_id`, `user_id`, `sid`) VALUES 
	('Strength', 'Strength measures bodily power, athletic training, and the extent to which you can exert raw physical force. A Strength check can model any attempt to lift, push, pull, or break something, to force your body through a space, or to otherwise apply brute force to a situation. The Athletics skill reflects aptitude in certain kinds of Strength checks.', @abilityTypeId, userId, 1),
	('Dexterity', 'Dexterity measures agility, reflexes, and balance. A Dexterity check can model any attempt to move nimbly, quickly, or quietly, or to keep from falling on tricky footing. The Acrobatics, Sleight of Hand, and Stealth skills reflect aptitude in certain kinds of Dexterity checks.', @abilityTypeId, userId, 2),
	('Constitution', 'Constitution measures health, stamina, and vital force. Constitution checks are uncommon, and no skills apply to Constitution checks, because the endurance this ability represents is largely passive rather than involving a specific effort on the part of a character or monster.', @abilityTypeId, userId, 3),
	('Intelligence', 'Intelligence measures mental acuity, accuracy of recall, and the ability to reason. An Intelligence check comes into play when you need to draw on logic, education, memory, or deductive reasoning. The Arcana, History, Investigation, Nature, and Religion skills reflect aptitude in certain kinds of Intelligence checks.', @abilityTypeId, userId, 4),
	('Wisdom', 'Wisdom reflects how attuned you are to the world around you and represents perceptiveness and intuition. A Wisdom check might reflect an effort to read body language, understand someone''s feelings, notice things about the environment, or care for an injured person. The Animal Handling, Insight, Medicine, Perception, and Survival skills reflect aptitude in certain kinds of Wisdom checks.', @abilityTypeId, userId, 5),
	('Charisma', 'Charisma measures your ability to interact effectively with others. It includes such factors as confidence and eloquence, and it can represent a charming or commanding personality. A Charisma check might arise when you try to influence or entertain others, when you try to make an impression or tell a convincing lie, or when you are navigating a tricky social situation. The Deception, Intimidation, Performance, and Persuasion skills reflect aptitude in certain kinds of Charisma checks.', @abilityTypeId, userId, 6);

	SET @strId = (SELECT id FROM attributes WHERE name = 'Strength' AND user_id = userId AND attribute_type_id = @abilityTypeId);
	SET @dexId = (SELECT id FROM attributes WHERE name = 'Dexterity' AND user_id = userId AND attribute_type_id = @abilityTypeId);
	SET @conId = (SELECT id FROM attributes WHERE name = 'Constitution' AND user_id = userId AND attribute_type_id = @abilityTypeId);
	SET @intId = (SELECT id FROM attributes WHERE name = 'Intelligence' AND user_id = userId AND attribute_type_id = @abilityTypeId);
	SET @wisId = (SELECT id FROM attributes WHERE name = 'Wisdom' AND user_id = userId AND attribute_type_id = @abilityTypeId);
	SET @chaId = (SELECT id FROM attributes WHERE name = 'Charisma' AND user_id = userId AND attribute_type_id = @abilityTypeId);

	INSERT INTO `abilities` (`attribute_id`, `abbr`) VALUES 
	(@strId, 'Str'),
	(@dexId, 'Dex'),
	(@conId, 'Con'),
	(@intId, 'Int'),
	(@wisId, 'Wis'),
	(@chaId, 'Cha');

