	#conditions
	INSERT INTO `attributes` (`name`, `description`, `attribute_type_id`, `user_id`, `sid`) VALUES
	('Blinded', '• A blinded creature can''t see and automatically fails any ability check that requires sight.\n• Attack rolls against the creature have advantage, and the creature''s attack rolls have disadvantage.', @conditionId, userId, 49),
	('Charmed', '• A charmed creature can''t attack the charmer or target the charmer with harmful abilities or magical effects.\n• The charmer has advantage on any ability check to interact socially with the creature.', @conditionId, userId, 50),
	('Deafened', '• A deafened creature can''t hear and automatically fails any ability check that requires hearing.', @conditionId, userId, 51),
	('Frightened', '• A frightened creature has disadvantage on ability checks and attack rolls while the source of its fear is within line of sight.\n• The creature can''t willing move closer to the source of its fear.', @conditionId, userId, 53),
	('Grappled', '• A grappled creature''s speed becomes 0, and it can''t benefit from any bonus to its speed.\n• The condition ends if the grappler is incapacitated.\n• The condition also ends if an effect removes the grappled creature from the reach of the grappler or grappling effect, such as when a creature is hurled away by the thunderwave spell.', @conditionId, userId, 54),
	('Incapacitated', '• An incapacitated creature can''t take actions or reactions.', @conditionId, userId, 55),
	('Invisible', '• An invisible creature is impossible to see without the aid of magic or a special sense. For the purpose of hiding, the creature is heavily obscured. The creature''s location can be detected by any noise it makes or any tracks it leaves.\n• Attack rolls against the creature have disadvantage, and the creature''s attack rolls have advantage.', @conditionId, userId, 56),
	('Paralyzed', '• A paralyzed creature is incapacitated and can''t move or speak.\n• The creature automatically fails Strength and Dexterity saving throws.\n• Attack rolls against the creature have advantage.\n• Any attack that hits the creature is a critical hit if the attacker is within 5 feet of the creature.', @conditionId, userId, 57),
	('Petrified', '• A petrified creature is transformed, along with any nonmagical object it is wearing or carrying, into a solid inanimate substance (usually stone). Its weight increases by a factor of ten, and it ceases aging.\n• The creature is incapacitated, can''t move or speak, and is unaware of its surroundings.\n• Attack rolls against the creature have advantage.\n•The creature automatically fails Strength and Dexterity saving throws.\n• The creature has resistance to all damage.\n• The creature is immune to poison and disease, although a poison or disease already in its system is suspended, not neutralized.', @conditionId, userId, 58),
	('Poisoned', '• A poisoned creature has disadvantage on attack rolls and ability checks.', @conditionId, userId, 59),
	('Prone', '• A prone creature''s only movement option is to crawl, unless it stands up and thereby ends the condition.\n• The creature has disadvantage on attack rolls.\n• An attack roll against the creature has advantage if the attacker is within 5 feet of the creature. Otherwise, the attack roll has disadvantage.', @conditionId, userId, 60),
	('Restrained', '• A restrained creature''s speed becomes 0, and it can''t benefit from any bonus to its speed.\n• Attack rolls against the creature have advantage, and the creature''s attack rolls have disadvantage.\n• The creature has disadvantage on Dexterity saving throws.', @conditionId, userId, 61),
	('Stunned', '• A stunned creature is incapacitated, can''t move, and can speak only falteringly.\n• The creature automatically fails Strength and Dexterity saving throws.\n• Attack rolls against the creature have advantage.', @conditionId, userId, 62),
	('Unconscious', '• An unconscious creature is incapacitated, can''t move or speak, and is unaware of its surroundings.\n• The creature drops whatever it''s holding and falls prone.\n•The creature automatically fails Strength and Dexterity saving throws.\n• Attack rolls against the creature have advantage.\n• Any attack that hits the creature is a critical hit if the attacker is within 5 feet of the creature.', @conditionId, userId, 63);

	SET @BlindedConditionId = (SELECT id FROM attributes WHERE name = 'Blinded' AND user_id = userId AND attribute_type_id = @conditionId);
	SET @CharmedConditionId = (SELECT id FROM attributes WHERE name = 'Charmed' AND user_id = userId AND attribute_type_id = @conditionId);
	SET @DeafenedConditionId = (SELECT id FROM attributes WHERE name = 'Deafened' AND user_id = userId AND attribute_type_id = @conditionId);
	SET @FrightenedConditionId = (SELECT id FROM attributes WHERE name = 'Frightened' AND user_id = userId AND attribute_type_id = @conditionId);
	SET @GrappledConditionId = (SELECT id FROM attributes WHERE name = 'Grappled' AND user_id = userId AND attribute_type_id = @conditionId);
	SET @IncapacitatedConditionId = (SELECT id FROM attributes WHERE name = 'Incapacitated' AND user_id = userId AND attribute_type_id = @conditionId);
	SET @InvisibleConditionId = (SELECT id FROM attributes WHERE name = 'Invisible' AND user_id = userId AND attribute_type_id = @conditionId);
	SET @ParalyzedConditionId = (SELECT id FROM attributes WHERE name = 'Paralyzed' AND user_id = userId AND attribute_type_id = @conditionId);
	SET @PetrifiedConditionId = (SELECT id FROM attributes WHERE name = 'Petrified' AND user_id = userId AND attribute_type_id = @conditionId);
	SET @PoisonedConditionId = (SELECT id FROM attributes WHERE name = 'Poisoned' AND user_id = userId AND attribute_type_id = @conditionId);
	SET @ProneConditionId = (SELECT id FROM attributes WHERE name = 'Prone' AND user_id = userId AND attribute_type_id = @conditionId);
	SET @RestrainedConditionId = (SELECT id FROM attributes WHERE name = 'Restrained' AND user_id = userId AND attribute_type_id = @conditionId);
	SET @StunnedConditionId = (SELECT id FROM attributes WHERE name = 'Stunned' AND user_id = userId AND attribute_type_id = @conditionId);
	SET @UnconsciousConditionId = (SELECT id FROM attributes WHERE name = 'Unconscious' AND user_id = userId AND attribute_type_id = @conditionId);

