	#damage_types
	INSERT INTO `attributes` (`name`, `description`, `attribute_type_id`, `user_id`, `sid`) VALUES 
	('Acid', 'The corrosive spray of a black dragon''s breath and the dissolving enzymes secreted by a black pudding deal acid damage.', @damageTypeId, userId, 64),
	('Bludgeoning', 'Blunt force attacks, falling, constriction, and the like deal bludgeoning damage.', @damageTypeId, userId, 65),
	('Cold', 'The infernal chill radiating from an ice devil''s spear and the frigid blast of a white dragon''s breath deal cold damage.', @damageTypeId, userId, 66),
	('Fire', 'Red dragons breathe fire, and many spells conjure flames to deal fire damage.', @damageTypeId, userId,67),
	('Force', 'Force is pure magical energy focused into a damaging form. Most effects that deal force damage are spells, including magic missile and spiritual weapon.', @damageTypeId, userId, 68),
	('Lightning', 'A lightning bolt spell and a blue dragon''s breath deal lightning damage.', @damageTypeId, userId, 69),
	('Necrotic', 'Necrotic damage, dealt by certain undead and a spell such as chill touch, withers matter and even the soul.', @damageTypeId, userId, 70),
	('Piercing', 'Puncturing and impaling attacks, including spears and monsters'' bites, deal piercing damage.', @damageTypeId, userId, 71),
	('Poison', 'Venomous stings and the toxic gas of a green dragon''s breath deal poison damage.', @damageTypeId, userId, 72),
	('Psychic', 'Mental abilities such as a psionic blast deal psychic damage.', @damageTypeId, userId, 73),
	('Radiant', 'Radiant damage, dealt by a cleric''s flame strike spell or an angel''s smiting weapon, sears the flesh like fire and overloads the spirit with power.', @damageTypeId, userId, 74),
	('Slashing', 'Swords, axes, and monsters'' claws deal slashing damage.', @damageTypeId, userId, 75),
	('Thunder', 'A concussive burst of sound, such as the effect of the thunderwave spell, deals thunder damage.', @damageTypeId, userId, 76);

	SET @acidDamageTypeId = (SELECT id FROM attributes WHERE name = 'Acid' AND user_id = userId AND attribute_type_id = @damageTypeId);
	SET @bludgeoningDamageTypeId = (SELECT id FROM attributes WHERE name = 'Bludgeoning' AND user_id = userId AND attribute_type_id = @damageTypeId);
