	#tool_categories
	INSERT INTO `attributes` (`name`, `description`, `attribute_type_id`, `user_id`, `sid`) VALUES 
	('Artisan''s Tools',   'These special tools include the items needed to pursue a craft or trade. Proficiency with a set of artisan''s tools lets you add your proficiency bonus to any ability checks you make using the tools in your craft.', @toolCategoryId, userId, 113),
	('Gaming Set',         'This item encompasses a wide range of game pieces, including dice and decks of cards (for games such as Three-Dragon Ante). If you are proficient with a gaming set, you can add your proficiency bonus to ability checks you make to play a game with that set.', @toolCategoryId, userId, 114),
	('Kits',               '', @toolCategoryId, userId, 115),
	('Musical Instrument', 'If you have proficiency with a given musical instrument, you can add your proficiency onus to any ability checks you make to play music with the instrument. A bard can use a musical instrument as a spellcasting focus.', @toolCategoryId, userId, 116),
	('Professional Tools', '', @toolCategoryId, userId, 117);
# 	('Vehicles',           'If you have proficiency with a certain kind of vehicle, you can add your proficiency bonus to any check you make to control that kind of vehicle in difficult circumstances.', @toolCategoryId, userId, 118);

