	#gears
	INSERT INTO `items` (`name`, `item_type_id`, `expendable`, `equippable`, `slot`, `container`, `ignore_weight`, `cost`, `cost_unit`, `weight`, `description`, `user_id`, `sid`) VALUES
	('Abacus',                             @gearId, 0, 0, null,          0, 0, 2,    @gpId, 2,    'Calculator', userId, 259),
	('Acid',                               @gearId, 1, 0, null,          0, 0, 25,   @gpId, 1,    'As an action, you can splash the contents of this vial onto a creature within 5 feet of you or throw the vial up to 20 feet, shattering it on impact. In either case, make a ranged attack against a creature or object, treating the acid as an improvised weapon. On a hit, the target takes 2d6 acid damage.', userId, 260),
	('Alchemist''s fire - flask',          @gearId, 1, 0, null,          0, 0, 50,   @gpId, 1,    'This sticky, adhesive fluid ignites when exposed to air. As an action, you can throw this flask up to 20 feet, shattering it on impact. Make a ranged attack against a creature or object, treating the alchemist''s fire as an improvised weapon. On a hit, the target takes 1d4 fire damage at the start of each of its turns. A creature can end this damage by using its action to make a DC 10 Dexterity check to extinguish the flames.', userId, 261),
	('Antitoxin - vial',                   @gearId, 1, 0, null,          0, 0, 50,   @gpId, 0,    'A creature that drinks this vial of liquid gains advantage on saving throws against poison for 1 hour. It confers no benefit to undead or constructs.', userId, 262),
	('Crystal - Arcane Focus',             @gearId, 0, 1, @handSlotId,   0, 0, 10,   @gpId, 1,    '', userId, 263),
	('Orb - Arcane Focus',                 @gearId, 0, 1, @handSlotId,   0, 0, 20,   @gpId, 3,    '', userId, 264),
	('Rod - Arcane Focus',                 @gearId, 0, 1, @handSlotId,   0, 0, 10,   @gpId, 2,    '', userId, 265),
	('Staff - Arcane Focus',               @gearId, 0, 1, @handSlotId,   0, 0, 5,    @gpId, 4,    '', userId, 266),
	('Wand - Arcane Focus',                @gearId, 0, 1, @handSlotId,   0, 0, 10,   @gpId, 1,    '', userId, 267),
	('Backpack',                           @gearId, 0, 0, null,          1, 0, 2,    @gpId, 5,    'You can also strap items, such as a bedroll or a coil of rope to the outside of a backpack.\n\n1 cubic foot/30 pounds of gear', userId, 268),
	('Ball bearings - bag of 1000',        @gearId, 1, 0, null,          0, 0, 1,    @gpId, 2,    'As an action, you can spill these tiny metal balls from their pouch to cover a level area 10 feet square. A creature moving across the covered area must succeed a DC 10 Dexterity saving throw or fall prone. A creature moving through the area at half speed doesn''t need to make the saving throw.', userId, 269),
	('Barrel',                             @gearId, 0, 0, null,          1, 0, 2,    @gpId, 70,   '40 gallons of liquid, 4 cubic feet solid', userId, 270),
	('Basket',                             @gearId, 0, 0, null,          1, 0, 4,    @spId, 2,    '2 cubic feet/40 pounds of gear', userId, 271),
	('Bedroll',                            @gearId, 0, 0, null,          0, 0, 1,    @gpId, 7,    '', userId, 272),
	('Bell',                               @gearId, 0, 0, null,          0, 0, 1,    @gpId, 0,    '', userId, 273),
	('Blanket',                            @gearId, 0, 0, null,          0, 0, 5,    @spId, 3,    '', userId, 274),
	('Block and Tackle',                   @gearId, 0, 0, null,          0, 0, 1,    @gpId, 5,    'A set of pulleys with a cable threaded through them and a hook to attach to objects, a block and tackle allows you to hoist up to four times the weight you can normally lift.', userId, 275),
	('Book',                               @gearId, 0, 0, null,          0, 0, 25,   @gpId, 5,    'A book might contain poetry, historical accounts, information pertaining to a particular field or lore, diagrams and notes on gnomish contraptions, or just about anything else that can be represented using text or pictures.', userId, 276),
	('Glass Bottle',                       @gearId, 0, 0, null,          1, 0, 2,    @gpId, 2,    '1.5 pints of liquid', userId, 277),
	('Bucket',                             @gearId, 0, 0, null,          1, 0, 5,    @cpId, 2,    '3 gallons of liquid, 0.5 cubic feet solid', userId, 278),
	('Caltrops - bag of 20',               @gearId, 1, 0, null,          0, 0, 1,    @gpId, 2,    'As an action, you can spread a single bag of caltrops to cover a 5-foot-square area. Any creature that enters the area must succeed a DC 15 Dexterity saving throw or stop moving and take 1 piercing damage. Until the creature regains at least 1 hit point, its walking speed is reduced by 10 feet. A creature moving through the area at half speed doesn''t need to make the saving throw.', userId, 279),
	('Candle',                             @gearId, 1, 0, null,          0, 0, 1,    @cpId, 0,    'For 1 hour, a candle sheds bright light in a 5-foot radius and dim light for ad additional 5 feet.', userId, 280),
	('Crossbow Bolt Case',                 @gearId, 0, 0, null,          1, 0, 1,    @gpId, 1,    'This wooden case can hold up to twenty crossbow bolts.', userId, 281),
	('Case - map or scroll',               @gearId, 0, 0, null,          1, 0, 1,    @gpId, 1,    'This cylindrical leather case can hold up to ten rolled-up sheets of paper or five rolled-up sheets of parchment.', userId, 282),
	('Chain - 10 feet',                    @gearId, 0, 1, @handSlotId,   0, 0, 5,    @gpId, 10,   'A chain has 10 hit points. It can be burst with a successful DC 20 Strength check.', userId, 283),
	('Chalk - 1 piece',                    @gearId, 0, 0, null,          0, 0, 1,    @cpId, 0,    '', userId, 284),
	('Chest',                              @gearId, 0, 0, null,          1, 0, 5,    @gpId, 25,   '12 cubic feet/300 pounds of gear', userId, 285),
	('Climber''s Kit',                     @gearId, 0, 0, null,          0, 0, 25,   @gpId, 12,   'A climber''s kit includes special pitons, boot tips, gloves, and a harness. You can use the climber''s kit as an action to anchor yourself; when you do, you can''t fall more than 25 feet from the point where you anchored yourself, and you can''t climb more than 25 feet away from that point without undoing the anchor.', userId, 286),
	('Clothes - common',                   @gearId, 0, 1, @bodySlotId,   0, 0, 5,    @spId, 3,    '', userId, 287),
	('Clothes - costume',                  @gearId, 0, 1, @bodySlotId,   0, 0, 5,    @gpId, 4,    '', userId, 288),
	('Clothes - fine',                     @gearId, 0, 1, @bodySlotId,   0, 0, 15,   @gpId, 6,    '', userId, 289),
	('Clothes - traveler''s',              @gearId, 0, 1, @bodySlotId,   0, 0, 2,    @gpId, 4,    '', userId, 290),
	('Component Pouch',                    @gearId, 0, 0, null,          1, 0, 25,   @gpId, 2,    'A component pouch is a small watertight leather belt pouch that has compartments to hold all the material components and other special items you need to cast your spells, except for those components that have a specific cost.', userId, 291),
	('Crowbar',                            @gearId, 0, 1, @handSlotId,   0, 0, 2,    @gpId, 5,    'Using a crowbar grants advantage to Strength checks where the crowbar''s leverage can be applied.', userId, 292),
	('Sprig of Mistletoe - Druidic Focus', @gearId, 1, 0, null,          0, 0, 1,    @gpId, 0,    '', userId, 293),
	('Totem - Druidic Focus',              @gearId, 1, 0, null,          0, 0, 1,    @gpId, 0,    '', userId, 294),
	('Wooden Staff - Druidic Focus',       @gearId, 0, 1, @handSlotId,   0, 0, 5,    @gpId, 4,    '', userId, 295),
	('Yew Wand - Druidic Focus',           @gearId, 0, 1, @handSlotId,   0, 0, 10,   @gpId, 1,    '', userId, 296),
	('Fishing Tackle',                     @gearId, 0, 0, null,          0, 0, 1,    @gpId, 4,    'This kit includes a wooden rod, silken line, corkwood bobbers, steel hooks, lead sinkers, velvet lures, and narrow netting.', userId, 297),
	('Flask / Tankard',                    @gearId, 0, 0, null,          1, 0, 2,    @cpId, 1,    '1 pint liquid', userId, 298),
	('Grappling Hook',                     @gearId, 0, 1, @handSlotId,   0, 0, 2,    @gpId, 4,    '', userId, 299),
	('Hammer',                             @gearId, 0, 1, @handSlotId,   0, 0, 1,    @gpId, 3,    '', userId, 300),
	('Sledge Hammer',                      @gearId, 0, 1, @handSlotId,   0, 0, 2,    @gpId, 10,   '', userId, 301),
	('Healer''s Kit',                      @gearId, 1, 0, null,          0, 0, 5,    @gpId, 3,  'This kit is a leather pouch containing bandages, salves, and splints. As an action, you can expend/use the kit to stabilize a creature that has 0 hit points, without needing to make a Wisdom (Medicine) check.', userId, 302),
	('Amulet - Holy Symbol',               @gearId, 0, 1, @neckSlotId,   0, 0, 5,    @gpId, 1,    'A holy symbol is a representation of a god or pantheon. It might be an amulet depicting a symbol representing a deity, the same symbol carefully engraved or inlaid as an emblem on a shield, or a tiny box holding a fragment of a sacred relic. A cleric or a Paladin can use a holy symbol as a spellcasting focus. To use the symbol in this way, the caster must hold it in hand, wear it visibly, or bear it on a shield.', userId, 303),
	('Emblem - Holy Symbol',               @gearId, 0, 1, @handSlotId,   0, 0, 5,    @gpId, 0,    'A holy symbol is a representation of a god or pantheon. It might be an amulet depicting a symbol representing a deity, the same symbol carefully engraved or inlaid as an emblem on a shield, or a tiny box holding a fragment of a sacred relic. A cleric or a Paladin can use a holy symbol as a spellcasting focus. To use the symbol in this way, the caster must hold it in hand, wear it visibly, or bear it on a shield.', userId, 304),
	('Reliquary - Holy Symbol',            @gearId, 0, 0, null,          0, 0, 5,    @gpId, 2,    'A holy symbol is a representation of a god or pantheon. It might be an amulet depicting a symbol representing a deity, the same symbol carefully engraved or inlaid as an emblem on a shield, or a tiny box holding a fragment of a sacred relic. A cleric or a Paladin can use a holy symbol as a spellcasting focus. To use the symbol in this way, the caster must hold it in hand, wear it visibly, or bear it on a shield.', userId, 305),
	('Holy Water - flask',                 @gearId, 1, 0, null,          0, 0, 25,   @gpId, 1,    'As an action, you can splash the contents of this flask onto a creature within 5 feet of you or throw it up to 20 feet, shattering it on impact. In either case, make a ranged attack against a target creature, treating the holy water as an improvised weapon. If the target is a fiend or undead, it takes 2d6 radiant damage. A cleric or paladin may create holy water by performing a special ritual. The ritual takes 1 hour to perform, uses 25 gp worth of powdered silver, and requires the caster to expend a 1st-level spell slot.', userId, 306),
	('Hourglass',                          @gearId, 0, 0, null,          0, 0, 25,   @gpId, 1,    '', userId, 307),
	('Hunting Trap',                       @gearId, 1, 0, null,          0, 0, 5,    @gpId, 25,   'When you use your action to set it, this trap forms a saw-toothed steel ring that snaps shut when a creature steps on a pressure plate in the center. The trap is affixed by a heavy chain to an immobile object, such as a tree or a spike driven into the ground. A creature that steps on the plate must succeed on a DC 13 Dexterity saving throw or take 1d4 piercing damage and stop moving. Thereafter until the creature breaks free of the trap, its movement is limited by the length of the chain (typically 3 feet long). A creature can use its action to make a DC 13 Strength check, freeing itself or another creature within its reach on a success. Each failed check deals 1 piercing damage to the trapped creature.', userId, 308),
	('Ink - 1 ounce bottle',               @gearId, 1, 0, null,          0, 0, 10,   @gpId, 0,    '', userId, 309),
	('Ink pen',                            @gearId, 0, 0, null,          0, 0, 2,    @cpId, 0,    '', userId, 310),
	('Jug / Pitcher',                      @gearId, 0, 0, null,          1, 0, 2,    @cpId, 4,    '1 gallon liquid', userId, 311),
	('Ladder - 10-foot',                   @gearId, 0, 0, null,          0, 0, 1,    @spId, 25,   '', userId, 312),
	('Lamp',                               @gearId, 0, 1, @handSlotId,   0, 0, 5,    @spId, 1,    'A lamp casts bright light in a 15-foot radius and dim light for an additional 30 feet. Once lit, it burns for 6 hours on a flask (1 pint) of oil.', userId, 313),
	('Lantern - bullseye',                 @gearId, 0, 1, @handSlotId,   0, 0, 10,   @gpId, 2,    'A bullseye lantern casts bright light in a 60-foot cone and dim light for an additional 60 feet. Once lit, it burns for 6 hours on a flask (1 pint) of oil.', userId, 314),
	('Lantern - hooded',                   @gearId, 0, 1, @handSlotId,   0, 0, 5,    @gpId, 2,    'A hooded lantern casts bright light in a 30-foot radius and dim light for an additional 30 feet. Once lit, it burns for 6 hours on a flask (1 pint) of oil. As an action, you can lower the hood, reducing the light to dim light in a 5-foot radius.', userId, 315),
	('Lock',                               @gearId, 0, 0, null,          0, 0, 10,   @gpId, 1,    'A key is provided with the lock. Without the key, a creature proficient with thieves'' tools can pick this lock with a successful DC 15 Dexterity check.', userId, 316),
	('Magnifying Glass',                   @gearId, 0, 0, null,          0, 0, 100,  @gpId, 0,    'This lens allows a closer look at small objects. It is also useful as a substitute for flint and steel when starting fires. Lighting a fire with a magnifying glass requires light as bright as sunlight to focus, tinder to ignite, and about 5 minutes for the fire to ignite. A magnifying glass grants advantage on any ability check to appraise or inspect an item that is small or highly detailed.', userId, 317),
	('Manacles',                           @gearId, 0, 0, null,          0, 0, 2,    @gpId, 6,    'These metal restraints can bind a Small or Medium creature. Escaping the manacles requires a successful DC 20 Dexterity check. Breaking them requires a successful DC 20 Strength check. Each set of manacles comes with one key. Without the key, a creature proficient with thieves'' tools can pick the manacles'' lock with a successful DC 15 Dexterity check. Manacles have 15 hit points.', userId, 318),
	('Mess Kit',                           @gearId, 0, 0, null,          0, 0, 2,    @spId, 1,    'This tin box contains a cup and simple cutlery. The box clamps together, and one side can be used as a cooking pan and the other as a plate or shallow bowl.', userId, 319),
	('Mirror - steel',                     @gearId, 0, 0, null,          0, 0, 5,    @gpId, 0.5,  '', userId, 320),
	('Oil - flask',                        @gearId, 1, 0, null,          0, 0, 1,    @spId, 1,    'Oil usually comes in a clay flask that holds 1 pint. As an action, you can splash the oil in this flask onto a creature within 5 feet of you or throw it up to 20 feet, shattering it on impact. Make a ranged attack against a target creature or object, treating the oil as an improvised weapon. On a hit, the target is covered in oil. If the target takes any fire damage before the oil dries (after 1 minute), the target takes an additional 5 fire damage from the burning oil. You can also pour a flask of oil on the ground to cover a 5-foot-square area, provided that the surface is level. If lit, the oil burns for 2 rounds and deals 5 fire damage to any creature that enters the area. A creature can take this damage only once per turn.', userId, 321),
	('Paper - 1 sheet',                    @gearId, 1, 0, null,          0, 0, 2,    @spId, 0,    '', userId, 322),
	('Parchment - 1 sheet',                @gearId, 1, 0, null,          0, 0, 1,    @spId, 0,    '', userId, 333),
	('Perfume - vial',                     @gearId, 1, 0, null,          0, 0, 5,    @gpId, 0,    '', userId, 334),
	('Miner''s Pick',                      @gearId, 0, 1, @handSlotId,   0, 0, 2,    @gpId, 10,   '', userId, 335),
	('Piton',                              @gearId, 0, 0, null,          0, 0, 5,    @cpId, 0.25, '', userId, 336),
	('Poison - basic, vial',               @gearId, 1, 0, null,          0, 0, 100,  @gpId, 0,    'You can use the poison in this vial to coat one slashing or piercing weapon or up to three pieces of ammunition. Applying the poison takes an action. A creature hit by the poisoned weapon or ammunition must make a DC 10 Constitution saving throw or take 1d4 poison damage. Once applied, the poison retains potency for 1 minute before drying.', userId, 337),
	('Pole - 10-foot',                     @gearId, 0, 1, @handSlotId,   0, 0, 5,    @cpId, 7,    '', userId, 338),
	('Pot - iron',                         @gearId, 0, 1, @handSlotId,   1, 0, 2,    @gpId, 10,   '1 gallon liquid', userId, 339),
	('Pouch',                              @gearId, 0, 0, null,          1, 0, 5,    @spId, 1,    'A cloth or leather pouch can hold up to 20 sling bullets or 50 blowgun needles, among other things. A compartmentalized pouch for holding spell components is called a component pouch. 0.2 cubic feet/6 pounds of gear', userId, 340),
	('Quiver',                             @gearId, 0, 0, null,          1, 0, 1,    @gpId, 1,    'A quiver can hold up to 20 arrows.', userId, 341),
	('Ram - portable',                     @gearId, 0, 0, null,          0, 0, 4,    @gpId, 35,   'You can use a portable ram to break down doors. When doing so, you gain a +4 bonus on the Strength check. One other character can help you use the ram, giving you advantage on this check.', userId, 342),
	('Rations - 1 day',                    @gearId, 1, 0, null,          0, 0, 5,    @spId, 2,    'Rations consist of dry foods suitable for extended travel, including jerky, dried fruit, hardtack, and nuts.', userId, 343),
	('Robes',                              @gearId, 0, 1, @bodySlotId,   0, 0, 1,    @gpId, 4,    '', userId, 344),
	('Rope - hempen, 50 feet',             @gearId, 0, 1, @handSlotId,   0, 0, 1,    @gpId, 10,   'Rope has 2 hit points and can be burst with a DC 17 Strength check.', userId, 345),
	('Rope - silk, 50 feet',               @gearId, 0, 1, @handSlotId,   0, 0, 10,   @gpId, 5,    'Rope has 2 hit points and can be burst with a DC 17 Strength check.', userId, 346),
	('Sack',                               @gearId, 0, 0, null,          1, 0, 1,    @cpId, 0.5,  '1 cubic foot/30 pounds of gear', userId, 347),
	('Scale',                              @gearId, 0, 0, null,          0, 0, 5,    @gpId, 3,    'A scale includes a small balance, pans, and a suitable assortment of weights up to 2 pounds. With it, you can measure the exact weight of small objects, such as raw precious metals or trade goods, to help determine their worth.', userId, 348),
	('Sealing Wax',                        @gearId, 1, 0, null,          0, 0, 5,    @spId, 0,    '', userId, 349),
