	('Soap',                               @gearId, 1, 0, null,          0, 0, 2,    @cpId, 0,    '', userId, 353),
	('Spellbook',                          @gearId, 0, 0, null,          0, 0, 50,   @gpId, 3,    'Essential for wizards, a spellbook is a leather-bound tome with 100 blank vellum pages suitable for recording spells.', userId, 354),
	('Iron Spike',                         @gearId, 1, 0, null,          0, 0, 1,    @spId, 0.5,  '', userId, 355),
	('Spyglass',                           @gearId, 0, 0, null,          0, 0, 1000, @gpId, 1,    'Objects viewed through a spyglass are magnified to twice their size.', userId, 356),
	('Tent - 2-person',                    @gearId, 0, 0, null,          0, 0, 2,    @gpId, 20,   'A simple and portable canvas shelter, a tent sleeps two.', userId, 357),
	('Tinderbox',                          @gearId, 0, 0, null,          0, 0, 5,    @spId, 1,    'This small container holds flint, fire steel, and tinder (usually dry cloth soaked in light oil) used to kindle a fire. Using it to light a torch - or anything else with abundant, exposed fuel - takes an action. Lighting any other fire takes 1 minute.', userId, 358),
	('Torch',                              @gearId, 1, 1, @handSlotId,   0, 0, 1,    @cpId, 1,    'A torch burns for 1 hour, providing bright light in a 20-foot radius and dim light for an additional 20 feet. If you make a melee attack with a burning torch and hit, it deals 1 fire damage.', userId, 359),
