	#backgrounds
	INSERT INTO `characteristics` (`name`, `parent_characteristic_id`, `characteristic_type_id`, `num_abilities`, `num_languages`, `num_saving_throws`, `num_skills`, `num_tools`, `spellcasting_ability_id`, `user_id`, `sid`) VALUES 
	('Acolyte', null, @backgroundId, 0, 2, 0, 0, 0, null, userId, 701);

	SET @acolyteId = (SELECT id FROM characteristics WHERE name = 'Acolyte' AND user_id = userId AND characteristic_type_id = @backgroundId);

	INSERT INTO `backgrounds` (`characteristic_id`, `description`, `starting_gold`) VALUES
	(@acolyteId, 'You have spent your life in the service of a temple to a specific god or pantheon of gods. You act as an intermediary between the realm of the holy and the mortal world, performing sacred rites and offering sacrifices in order to conduct worshipers into the presence of the divine. You are not necessarily a cleric - performing sacred rites is not the same thing as channeling divine power.\n\nChoose a god, a pantheon of gods, or some other quasi-divine being from among those listed in appendix B of the Player''s Handbook or those specified by your GM, and work with you GM to detail the nature of your religious service. Were you a lesser functionary in a temple, raised from childhood to assist the priests in the sacred rites? Or were you a high priest who suddenly experienced a call to serve your god in a different way. Perhaps you were the leader of a small cult outside of any established temple structure, or even an occult group that served a fiendish master that you now deny.', 15);
    
    INSERT INTO `background_traits` (`background_id`, `background_trait_type_id`, `description`) VALUES
	#personalities
    (@acolyteId, @personalityId, 'I idolize a particular hero of my faith, and constantly refer to that person''s deeds and example.'),
    (@acolyteId, @personalityId, 'I can find common ground between the fiercest enemies, empathizing with them and always working toward peace.'),
    (@acolyteId, @personalityId, 'I see omens in every event and action. The gods try to speak to us, we just need to listen.'),
    (@acolyteId, @personalityId, 'Nothing can shake my optimistic attitude.'),
    (@acolyteId, @personalityId, 'I quote (or misquote) sacred texts and provers in almost every situation.'),
    (@acolyteId, @personalityId, 'I am tolerant (or intolerant) of other faiths and respect (or condemn) the worship of other gods.'),
    (@acolyteId, @personalityId, 'I''ve enjoyed find food, drink, and high society among my temple''s elite. Rough living grates on me.'),
    (@acolyteId, @personalityId, 'I''ve spent so long in the temple that I have little practical experience dealing with people in the outside world.'),
    #ideals
    (@acolyteId, @idealId, 'Tradition: The ancient traditions of worship and sacrifice must be preserved and upheld. (Lawful)'),
    (@acolyteId, @idealId, 'Charity: I always try to help those in need, no matter what the personal cost. (Good)'),
    (@acolyteId, @idealId, 'Change: We must help bring about the changes the gods are constantly working in the world. (Chaotic)'),
    (@acolyteId, @idealId, 'Power: I hope to one day rise to the top of my faith''s religious hierarchy. (Lawful)'),
    (@acolyteId, @idealId, 'Faith: I trust that my deity will guide my actions. I have faith that if I work hard, things will go well. (Lawful)'),
    (@acolyteId, @idealId, 'Aspiration: I seek to prove myself worthy of my god''s favor by matching my actions against his or her teachings. (Any)'),
    #bonds
    (@acolyteId, @bondId, 'I would die to recover an ancient relic of my faith that was lost long ago.'),
    (@acolyteId, @bondId, 'I will someday get revenge on the corrupt temple hierarchy who branded me a heretic.'),
    (@acolyteId, @bondId, 'I owe my life to the priest who took me in when my parents died.'),
    (@acolyteId, @bondId, 'Everything I do is for the common people.'),
    (@acolyteId, @bondId, 'I will do anything to protect the temple where I served.'),
    (@acolyteId, @bondId, 'I seek to preserve a sacred text that my enemies consider heretical and seek to destroy.'),
    #flaws
    (@acolyteId, @flawId, 'I judge others harshly, and myself even more severely.'),
    (@acolyteId, @flawId, 'I put too much trust in those who wield power within my temple''s hierarchy.'),
    (@acolyteId, @flawId, 'My piety sometimes leads me to blindly trust those that profess faith in my god.'),
    (@acolyteId, @flawId, 'I am inflexible in my thinking.'),
    (@acolyteId, @flawId, 'I am suspicious of strangers and expect the worst of them.'),
    (@acolyteId, @flawId, 'Once I pick a goal, I become obsessed with it to the detriment of everything else in my life.');

