    INSERT INTO `characteristics` (`name`, `parent_characteristic_id`, `characteristic_type_id`, `num_abilities`, `num_languages`, `num_saving_throws`, `num_skills`, `num_tools`, `spellcasting_ability_id`, `user_id`, `sid`) VALUES 
	('Dwarf', null, @raceId,      0, 0, 0, 0, 1, null,   userId, 732),
	('Elf', null, @raceId,        0, 0, 0, 0, 0, null,   userId, 733),
	('Halfling', null, @raceId,   0, 0, 0, 0, 0, null,   userId, 734),
	('Human', null, @raceId,      0, 1, 0, 0, 0, null,   userId, 735),
