	('Gnome', null, @raceId,      0, 0, 0, 0, 0, null,   userId, 737),
	('Half-Elf', null, @raceId,   2, 1, 0, 2, 0, null,   userId, 738),
	('Half-Orc', null, @raceId,   0, 0, 0, 0, 0, null,   userId, 739),
	('Tiefling', null, @raceId,   0, 0, 0, 0, 0, @chaId, userId, 740);
    
