	(@CircleOfTheArtNaturesWardId, @circleOfTheArtic, @classId, @level10Id, 1, null, 0, null, '', 'You can''t be charmed or frightened by elementals or fey, and you are immune to poison and disease.'),
	(@CircleOfTheCoaNaturesWardId, @circleOfTheCoast, @classId, @level10Id, 1, null, 0, null, '', 'You can''t be charmed or frightened by elementals or fey, and you are immune to poison and disease.'),
	(@CircleOfTheDeseNaturesWardId, @circleOfTheDesert, @classId, @level10Id, 1, null, 0, null, '', 'You can''t be charmed or frightened by elementals or fey, and you are immune to poison and disease.'),
	(@CircleOfTheForeNaturesWardId, @circleOfTheForest, @classId, @level10Id, 1, null, 0, null, '', 'You can''t be charmed or frightened by elementals or fey, and you are immune to poison and disease.'),
